INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('WM-16662650', '丸内双雁', 'Japanese Crest Maru ni futatu Karigane.svg', NULL, '东亚邻邦', 'basic', NULL, '["鸟兽鱼虫"]', '["东亚邻邦"]', '2011-09-24', '由本地SVG渲染的960像素图像', 'assets/patterns/basic-WM-16662650.webp', 'assets/patterns/basic-WM-16662650-thumb.webp', '1df077a583a43b70bc94a4d7b405a4d21d4ba1c8cfaa67ca5eac39a5d39c12b4', NULL, NULL, NULL, '维基共享资源', '维基共享资源', 'https://commons.wikimedia.org/wiki/File:Japanese_Crest_Maru_ni_futatu_Karigane.svg', NULL, 'Mukai', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', '16662650', NULL, NULL, '丸に二つ雁金（まるにふたつかりがね）は、日本の家紋「雁金紋」の一種である。江戸時代に編纂された『寛政重修諸家譜』に掲載されている柴田氏の定紋である。柴田勝家の旗に描かれている 二つ雁金 に丸を加えたものだ。『寛政重修諸家譜』掲載の柴田氏は柴田勝家の子孫一族とされる。', NULL, '中文名称为检索用整理名。难度为图形筛选建议，尚未经实际试绣验证。原图、线稿、简配色仅计作一份。', FALSE, 0, '丸内双雁 东亚邻邦  鸟兽鱼虫');
