INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('WM-185375213', '手稿装饰 · 5213', '01 ornament – Al Quran Melayu A47 Hal 606.svg', NULL, '东南亚织绣', 'basic', NULL, '["边饰与织锦","花草藤蔓"]', '["东南亚织绣"]', '2026-03-03', '由本地SVG渲染的960像素图像', 'assets/patterns/basic-WM-185375213.webp', 'assets/patterns/basic-WM-185375213-thumb.webp', 'fe34bc758b967ccba496ceacedffa05dd0d8c172e2845579faacd09072165987', NULL, NULL, NULL, '维基共享资源', '维基共享资源', 'https://commons.wikimedia.org/wiki/File:01_ornament_%E2%80%93_Al_Quran_Melayu_A47_Hal_606.svg', NULL, 'Benabrid', 'CC0', 'http://creativecommons.org/publicdomain/zero/1.0/deed.en', '185375213', NULL, NULL, 'Iluminasi ini diperkirakan ini berasal dari etnis Melayu tepatnya di Terengganu Malaysia. Terdapat empat halaman beriluminasi, namun hanya menggunakan dua ragam hias. Ragam hias terdapat pada halaman 6 dan 7 (mirroring) yaitu pada surat Al-Baqarah ayat 1-5 dan juga Al-Fathihah. Ragam hias berikutnya ada pada Al-Falaq dan An-Nas pada halaman 606 dan 607.', NULL, '中文名称为检索用整理名。难度为图形筛选建议，尚未经实际试绣验证。原图、线稿、简配色仅计作一份。', FALSE, 0, '手稿装饰 · 5213 东南亚织绣  边饰与织锦 花草藤蔓');
