INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('WM-185376518', '手稿装饰 · 6518', '03 ornament – Al Quran Aceh Or2064 Hal 17.svg', NULL, '东南亚织绣', 'basic', NULL, '["边饰与织锦","花草藤蔓"]', '["东南亚织绣"]', '2026-03-03', '由本地SVG渲染的960像素图像', 'assets/patterns/basic-WM-185376518.webp', 'assets/patterns/basic-WM-185376518-thumb.webp', 'd54708606920d81a55c7b93ae20470f01ee475e5f0655d0a268a9496f54c61a7', NULL, NULL, NULL, '维基共享资源', '维基共享资源', 'https://commons.wikimedia.org/wiki/File:03_ornament_%E2%80%93_Al_Quran_Aceh_Or2064_Hal_17.svg', NULL, 'Benabrid', 'CC0', 'http://creativecommons.org/publicdomain/zero/1.0/deed.en', '185376518', NULL, NULL, 'Iluminasi pada Manuskrip Or. 2064 koleksi digital dari Leiden University Libraries. Terdapat lima halaman beriluminasi, namun hanya menggunakan dua ragam hias yang berbeda. Ragam hias pertama terdapat pada halaman 16 dan 17 (mirroring) pada Surat Al-Fatihah. Ragam hias kedua terdapat pada halaman 378 dan 379 (mirroring) pada Surat Al-Kahfi, dan pola yang sama kembali digunakan pada halaman 565 untuk Surat An-Nas. Iluminasi ini diperkirakan ini berasal dari Aceh Indonesia.', NULL, '中文名称为检索用整理名。难度为图形筛选建议，尚未经实际试绣验证。原图、线稿、简配色仅计作一份。', FALSE, 0, '手稿装饰 · 6518 东南亚织绣  边饰与织锦 花草藤蔓');
