INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('WM-20527853', '一文字菊纹', 'Japanese Crest Kiku ni Ichimonnji.svg', NULL, '东亚邻邦', 'basic', NULL, '["花草藤蔓"]', '["东亚邻邦"]', '2012-08-04', '矢量原作的960像素栅格版本', 'assets/patterns/basic-WM-20527853.webp', 'assets/patterns/basic-WM-20527853-thumb.webp', 'efbb5fafe5ccbcfe348d48d2fd828321aae7b066791883f87c22f1519d1c0810', NULL, NULL, NULL, '维基共享资源', '维基共享资源', 'https://commons.wikimedia.org/wiki/File:Japanese_Crest_Kiku_ni_Ichimonnji.svg', NULL, 'Mukai', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', '20527853', NULL, NULL, '菊に一文字（きくにいちもんじ）は、日本の家紋「菊紋」の一種である。十六菊の下に漢数字の「一」（一文字）を描く図案が通常である。一文字の長さや細さに決まりはない。図はそのうちの一つである。同名紋で別の図案も参照されたい。近似の家紋に「菊菱に一文字」や「半菊に一文字」がある。十六菊の上部に一文字を描いたものは「一文字に菊」という。', NULL, '中文名称为检索用整理名。难度为图形筛选建议，尚未经实际试绣验证。原图、线稿、简配色仅计作一份。', FALSE, 0, '一文字菊纹 东亚邻邦  花草藤蔓');
