INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('WM-6743797', '三河骨叶纹', 'Japanese Crest Mitu Kouhone.svg', NULL, '东亚邻邦', 'basic', NULL, '["花草藤蔓"]', '["东亚邻邦"]', '2008-05-04(PNG) - 9 May 2009(SVG)', '矢量原作的960像素栅格版本', 'assets/patterns/basic-WM-6743797.webp', 'assets/patterns/basic-WM-6743797-thumb.webp', '9657763bae230c8ba1400dc7196565dbe747b491991a922be99b1b2f8676c0ad', NULL, NULL, NULL, '维基共享资源', '维基共享资源', 'https://commons.wikimedia.org/wiki/File:Japanese_Crest_Mitu_Kouhone.svg', NULL, 'Mukai', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', '6743797', NULL, NULL, '​三つ河骨（みつこうほね）は、日本の家紋「河骨紋」の一種である。スイレン科の「コウホネ」を図案化したもので、 葵紋 の葉に似た図案である。本来の図案は縦長の葉で、主に、徳川家が葵紋の使用を規制した後に葵紋の代わりとして使用された。', NULL, '中文名称为检索用整理名。难度为图形筛选建议，尚未经实际试绣验证。原图、线稿、简配色仅计作一份。', FALSE, 0, '三河骨叶纹 东亚邻邦  花草藤蔓');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('WM-185519288', '手稿装饰 · 9288', '16 ornament – Al Quran Hs. Or. 15528 Hal 413.svg', NULL, '东南亚织绣', 'basic', NULL, '["边饰与织锦","花草藤蔓"]', '["东南亚织绣"]', '2026-03-05', '矢量原作的960像素栅格版本', 'assets/patterns/basic-WM-185519288.webp', 'assets/patterns/basic-WM-185519288-thumb.webp', '10605b385dc1911d96fe2df18a581930e90b2c836ea542932faf89b59eda7605', NULL, NULL, NULL, '维基共享资源', '维基共享资源', 'https://commons.wikimedia.org/wiki/File:16_ornament_%E2%80%93_Al_Quran_Hs._Or._15528_Hal_413.svg', NULL, 'Benabrid', 'CC0', 'http://creativecommons.org/publicdomain/zero/1.0/deed.en', '185519288', NULL, NULL, 'Ilumanasi pada kitab Al-Quran Hs. Or. 15528 Staatsbibliothek zu Berlin Hal 413. Manuskrip ini memiliki enam halaman beriluminasi, namun hanya menggunakan tiga ragam hias yang berbeda. Ragam hias pertama terdapat pada halaman 12 dan 13 (mirroring) di surat Al Baqarah. Ragam hias kedua pada halaman 412 dan 413 (mirroring) di surat Al Kahfi, dan terakhir pada halaman 786 dan 787 di Surat An-Nas. Manuskrip ini berasal dari Aceh Indonesia.', NULL, '中文名称为检索用整理名。难度为图形筛选建议，尚未经实际试绣验证。原图、线稿、简配色仅计作一份。', FALSE, 0, '手稿装饰 · 9288 东南亚织绣  边饰与织锦 花草藤蔓');
