INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('WM-6723730', '木瓜花纹', 'Japanese Crest Mokkou.svg', NULL, '东亚邻邦', 'basic', NULL, '["花草藤蔓"]', '["东亚邻邦"]', '2009-05-07', '矢量原作的960像素栅格版本', 'assets/patterns/basic-WM-6723730.webp', 'assets/patterns/basic-WM-6723730-thumb.webp', 'dc2019e7afeb43e7258d4d92685654bf5a0e0068014ea06af14cd598f791eb0e', NULL, NULL, NULL, '维基共享资源', '维基共享资源', 'https://commons.wikimedia.org/wiki/File:Japanese_Crest_Mokkou.svg', NULL, 'Mukai', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', '6723730', NULL, NULL, '木瓜（もっこう）は日本の家紋「木瓜紋」の一種である。主にこの図案のものは横木瓜（よこもっこう）、対して、縦方向のものを竪木瓜（たてもっこう）ともいう。竪木瓜は滝川氏や堀田氏などの使用例が見られ、横木瓜は朝倉氏などが用いている。織田木瓜は織田瓜（おだか・おだうり）のことで、五瓜である。', NULL, '中文名称为检索用整理名。难度为图形筛选建议，尚未经实际试绣验证。原图、线稿、简配色仅计作一份。', FALSE, 0, '木瓜花纹 东亚邻邦  花草藤蔓');
