INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('WM-8629467', '对鸟竹叶纹', 'Japanese Crest Uesugi Sasa.svg', NULL, '东亚邻邦', 'basic', NULL, '["花草藤蔓"]', '["东亚邻邦"]', '2009-11-29', '矢量原作的960像素栅格版本', 'assets/patterns/basic-WM-8629467.webp', 'assets/patterns/basic-WM-8629467-thumb.webp', '87dd6ef8f7c0693f1e3658319a4d8a69134b722b74d03c40473cfd8cee803ede', NULL, NULL, NULL, '维基共享资源', '维基共享资源', 'https://commons.wikimedia.org/wiki/File:Japanese_Crest_Uesugi_Sasa.svg', NULL, 'Mukai', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', '8629467', NULL, NULL, '上杉笹（うえすぎざさ）は、日本の家紋「竹紋・笹紋」の一種である。丸に九枚笹に対い雀を描いたもので、仙台笹と同様に俗に「竹に雀」とも呼ばれる構図の家紋であるが、この図案のものは主に上杉氏が用いた。江戸初期に会津から米沢へ転封した米沢上杉家では、この変形を用いて「米沢笹」といっている。上杉家と同じ藤原北家の勧修寺流の勧修寺家では竹輪に九枚笹に三つ集め雀の図案である「勧修寺笹」を用いている。', NULL, '中文名称为检索用整理名。难度为图形筛选建议，尚未经实际试绣验证。原图、线稿、简配色仅计作一份。', FALSE, 0, '对鸟竹叶纹 东亚邻邦  花草藤蔓');
