INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('WM-9589053', '双笠纹', 'Japanese Crest Yagyuu Kasa.svg', NULL, '东亚邻邦', 'basic', NULL, '["几何与团花"]', '["东亚邻邦"]', '2010-02-28', '矢量原作的960像素栅格版本', 'assets/patterns/basic-WM-9589053.webp', 'assets/patterns/basic-WM-9589053-thumb.webp', '5b1d5ccaaacc8c0a19ae920943a95a17e6d934ec8f8872619f2915ac1ade52fb', NULL, NULL, NULL, '维基共享资源', '维基共享资源', 'https://commons.wikimedia.org/wiki/File:Japanese_Crest_Yagyuu_Kasa.svg', NULL, 'Mukai', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', '9589053', NULL, NULL, '柳生笠（やぎゅうがさ）は、日本の家紋「笠紋」の一種である。「二階笠（にかいがさ）」、「二蓋笠（にがいがさ）」ともいう。柳生氏の替紋である。もとは、坂崎氏の家紋であったが、坂崎成正（坂崎直盛）が、千姫事件の際、責を負って自害するときに、友人であった宗矩の説得に感謝して坂崎家の家紋を譲渡したとされる。「二階笠」ともいうように、もとは市女笠を上下に2つ重ねた図案であった。縦置きと横置きがあるがどちらも柳生笠という。', NULL, '中文名称为检索用整理名。难度为图形筛选建议，尚未经实际试绣验证。原图、线稿、简配色仅计作一份。', FALSE, 0, '双笠纹 东亚邻邦  几何与团花');
