INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('WM-6793040', '井桁菱框', 'Japanese crest Igeta.svg', NULL, '东亚邻邦', 'basic', NULL, '["几何与团花"]', '["东亚邻邦"]', '2008-05-18(PNG) - 2009-05-09(SVG)', '矢量原作的960像素栅格版本', 'assets/patterns/basic-WM-6793040.webp', 'assets/patterns/basic-WM-6793040-thumb.webp', '1d400753352715205b8a03a3dc0346c8fe73a23fd6376077f2af43b4c0a43051', NULL, NULL, NULL, '维基共享资源', '维基共享资源', 'https://commons.wikimedia.org/wiki/File:Japanese_crest_Igeta.svg', NULL, 'Mukai', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', '6793040', NULL, NULL, '​井桁（いげた）は、日本の家紋「井桁紋」の一種である。井戸の地上部分の構造（井桁）を図案化した家紋である。特に菱形に変形したものを井桁という。同類の家紋に「井筒（いづつ）」があるが、これは元々井戸地上部分が円筒形（筒状）のものを意味する言葉であったのだが、後に家紋では井桁を真上から見たような図案を言うようになった。', NULL, '中文名称为检索用整理名。难度为图形筛选建议，尚未经实际试绣验证。原图、线稿、简配色仅计作一份。', FALSE, 0, '井桁菱框 东亚邻邦  几何与团花');
