INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('WM-28867735', '雪覆竹叶纹', 'Japanese crest Kituki Sasa.svg', NULL, '东亚邻邦', 'basic', NULL, '["花草藤蔓"]', '["东亚邻邦"]', '2013-10-06 14:09:47', '矢量原作的960像素栅格版本', 'assets/patterns/basic-WM-28867735.webp', 'assets/patterns/basic-WM-28867735-thumb.webp', 'b2ec3eb21a1140edf17dcfe696958ca749d88e08feb91b61c60585d002a33eb3', NULL, NULL, NULL, '维基共享资源', '维基共享资源', 'https://commons.wikimedia.org/wiki/File:Japanese_crest_Kituki_Sasa.svg', NULL, 'Mukai', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', '28867735', NULL, NULL, '​杵築笹（きつきささ）は、日本の家紋「竹紋」または「笹紋」の一種である。五枚笹の上に雪を描いた「雪持ち笹」であるが、雪の部分に枝を描かない。江戸時代に豊後国杵築（現在の大分県杵築市）を治めた能見松平家が使用した。', NULL, '中文名称为检索用整理名。难度为图形筛选建议，尚未经实际试绣验证。原图、线稿、简配色仅计作一份。', FALSE, 0, '雪覆竹叶纹 东亚邻邦  花草藤蔓');
