INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('MET-70535', '玉堂富贵图', 'Magnolia, crabapple, and tree peony', NULL, '中国传统', 'archive', NULL, '["花草藤蔓","吉祥与礼仪"]', '["China"]', 'late 17th–early 18th century', 'Silk embroidery on silk twill', 'assets/patterns/archive-MET-70535.webp', 'assets/patterns/archive-MET-70535-thumb.webp', 'a7a8f59bfb8706b29629709c14f66ffde623012017fd37defd5be88bc6e125cb', NULL, 1800, 3244, 'The Met', '大都会艺术博物馆', 'https://www.metmuseum.org/art/collection/search/70535', NULL, '馆方未注明', 'CC0', 'https://www.metmuseum.org/about-the-met/policies-and-documents/open-access', '1973.8', NULL, NULL, '玉兰、海棠和牡丹组成“玉堂富贵”的吉祥寓意。', NULL, '中文名称与寓意依据馆方作品记录。', FALSE, 0, '玉堂富贵图 中国传统  花草藤蔓 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-156897', '牡丹 · 云纹 · 刺绣', 'Embroidery from a Cloud Collar: Ocean, Rocks, and Peonies', NULL, '中国传统', 'archive', NULL, '["花草藤蔓","吉祥与礼仪","边饰与织锦"]', '["China, Yuan dynasty (1271-1368) - early Ming dynasty (1368-1644)"]', '1300s', 'silk and silver thread, silvered paper; needleloop embroidery', 'assets/patterns/archive-CMA-156897.webp', 'assets/patterns/archive-CMA-156897-thumb.webp', '013aec771affa2ee25db5013a06409a9d5973df38e6b0357fc04c566e843fcb3', NULL, 1536, 1630, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1993.10', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1993.10', NULL, NULL, 'Against a deep blue satin ground, a peony tree emerges from an undulating sea. This embroidery was made using the needle looping technique, in which rows of detached loops are worked over silvered paper, attaching the ground only along the contours of the design. The design is filled with auspicious symbols, including the peony symbolizing wealth and honor, and the rock (shoushi 壽石) symbolizing longevity. There are small Buddhist symbols among the flowers, including the wheel of the law, a pair of conch shells representing the sounds of the Buddha’s teachings, and a swastika, an auspicious symbol signifying good fortune introduced into China from India with Buddhism.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '牡丹 · 云纹 · 刺绣 中国传统  花草藤蔓 吉祥与礼仪 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-148522', '龙纹 · 云纹 · 织物', 'Silk Panel with Dragon and Cloud Motif', NULL, '中国传统', 'archive', NULL, '["鸟兽鱼虫","吉祥与礼仪","边饰与织锦"]', '["China, Qing dynasty (1644-1911), Jiangnan Imperial Factory"]', 'c. 1700s-1800s', 'Silk and metal thread: Jacquard weave', 'assets/patterns/archive-CMA-148522.webp', 'assets/patterns/archive-CMA-148522-thumb.webp', 'ac15a1b9b5acd7db17ea30e4308a2a0b4b0157cc594256b8db645c144f868c31', NULL, 1201, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1976.1087', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1976.1087', NULL, NULL, 'This panel of silk produced in one of the imperial factories is the end part of a bolt of silk, some of which were shipped to Beijing as tax payments. The inscription woven into the lower body of the fabric reads Jiangnan Silk Factory under Superintendent Wen Feng(?). An additional signature by the weaver is woven into the left corner.Since the Southern Song dynasty in the 1100s, the production of silk for imperial use was increasingly concentrated in the Lower Yangzi Delta, also called Jiangnan. By the Ming and Qing dynasties the main official imperial workshops were situated in the region’s cities of Hangzhou, Suzhou, and Nanjing.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '龙纹 · 云纹 · 织物 中国传统  鸟兽鱼虫 吉祥与礼仪 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-156886', '牡丹 · 树木 · 凤鸟', 'Phoenix and Tree Peony', NULL, '中国传统', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","吉祥与礼仪"]', '["China, Yuan dynasty (1271-1368) - Ming dynasty (1368-1644)"]', '1300s', 'Silk and silver thread: needle-loop embroidery, silvered paper', 'assets/patterns/archive-CMA-156886.webp', 'assets/patterns/archive-CMA-156886-thumb.webp', 'c39a5f50e4e662146e66223adb0f2f869ed7157dfc2585aaeba417172c2054f7', NULL, 2048, 1489, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1992.95', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1992.95', NULL, NULL, 'This needle-loop embroidery is distinguished by its exceptionally fine execution. Few other examples incorporate the variety of intricate diaper patterns seen here. Like most needle-loop embroideries, the phoenix is fragmentary. Rows of loops worked over pieces of gilded or silvered paper make needle-loop embroidery quite heavy. On the other hand, the ground fabrics upon which they were executed were usually lightweight silks. Unable to support the embroidery, they simply wore out over time.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '牡丹 · 树木 · 凤鸟 中国传统  花草藤蔓 鸟兽鱼虫 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-157440', '凤鸟 · 云纹 · 织锦', 'Brocade with Soaring Phoenixes among Clouds', NULL, '中国传统', 'archive', NULL, '["鸟兽鱼虫","吉祥与礼仪","边饰与织锦"]', '["China, Jin dynasty (1115–1234)"]', '1100s–1200s', 'Silk and gold thread; tabby, brocaded', 'assets/patterns/archive-CMA-157440.webp', 'assets/patterns/archive-CMA-157440-thumb.webp', '87eb725ab89093200c6a86f2434f2c28b3f5a13e53b3d0cdddbf594211e9b304', NULL, 3400, 3061, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1994.292', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1994.292', NULL, NULL, 'The gold-brocaded designs of Jin brocades, such as this example with graceful phoenixes soaring into clouds, are typically asymmetrical. Moreover, they have no frame or border, and appear to have been cut out of larger decorative images.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '凤鸟 · 云纹 · 织锦 中国传统  鸟兽鱼虫 吉祥与礼仪 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-157441', '莲花 · 花卉 · 织锦', 'Brocade with Lotus Flowers', NULL, '中国传统', 'archive', NULL, '["花草藤蔓","吉祥与礼仪","边饰与织锦"]', '["Northern China, Yuan dynasty (1271-1368)"]', '1200s–mid-1300s', 'Silk: tabby, brocaded; gold thread', 'assets/patterns/archive-CMA-157441.webp', 'assets/patterns/archive-CMA-157441-thumb.webp', '94628c40f52d076166cf4a41420af4c30777ba6b5fd203fc3d181c14f41b1a3d', NULL, 3400, 2926, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1994.293', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1994.293', NULL, NULL, 'The tradition of brocade weaving in northern China continued after the Mongol conquest. However, the arrival of eastern Iranian craftsmen affected both the design and the structure of the brocades: patterns became symmetrical and paired warps replaced single warps. Both of these modifications can be observed in this example. At the same time, however, the Jin tradition of floating foundation wefts across the back sides of the brocaded areas continued. Brocades such as this may have been woven in Hongzhou (in Hebei province), where weavers from both western Asia and from the former Jin capital, Bianjing, are known to have worked together.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '莲花 · 花卉 · 织锦 中国传统  花草藤蔓 吉祥与礼仪 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-157572', '花卉 · 龙纹', 'Canopy with Dragon among Flowers', NULL, '中国传统', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","吉祥与礼仪"]', '["China, Center: Southern Song dynasty (1127-1270)  Border: Ming dynasty (1368-1644)"]', '1100s/1400s', 'Center: silk, gold, tapestry weave (kesi). Border: silk, gold, lampas weave', 'assets/patterns/archive-CMA-157572.webp', 'assets/patterns/archive-CMA-157572-thumb.webp', '49a2841d86b64e761aac11ad9e839a68c90ccd9308d03e14b86899d84e47d7bf', NULL, 3271, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1995.1', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1995.1', NULL, NULL, 'The tapestry sewn into the center of this canopy depicts dragons among flowers, a classic design in Chinese art. Its weavers paid attention to fine details, such as the color gradation of the dragon’s scales, or subtle color changes in the flower petals and leaves. The selection of colored silk threads is soft in tone but rich in variety. All these stylistic characteristics indicate that this tapestry was woven in an imperial Southern Song workshop in the capital of Hangzhou, a center of textile production in the Jiangnan region.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 龙纹 中国传统  花草藤蔓 鸟兽鱼虫 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-159280', '龙纹 · 凤鸟 · 织物', 'Textile with Phoenixes and Dragons', NULL, '中国传统', 'archive', NULL, '["鸟兽鱼虫","吉祥与礼仪","边饰与织锦"]', '["China, Yuan dynasty (1260-1368)"]', '1279–1368', 'Silk and gold thread; lampas', 'assets/patterns/archive-CMA-159280.webp', 'assets/patterns/archive-CMA-159280-thumb.webp', '50436b30ad4dd41ea18ad9e56108e422a3ae25b5ad5acdd5b1196004e93a0236', NULL, 3386, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1995.73', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1995.73', NULL, NULL, 'This is one of the very few northern Chinese silk and gold textiles to have survived from the Yuan dynasty. The curled dragons chasing pearls, the phoenixes, and the background of tiny hexagons are Chinese motifs, but the lobed roundels enclosing the dragons and phoenixes indicate the influence of eastern Iranian craftsmen who had been relocated to northern China. A red and gold silk woven with the same pattern is preserved in Beijing. The extraordinary survival of the two silks demonstrates that patterns were typically used over and over.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '龙纹 · 凤鸟 · 织物 中国传统  鸟兽鱼虫 吉祥与礼仪 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-153812', '龙纹 · 鹿纹', 'Tigers Chasing Deer, with Dragon', NULL, '中国传统', 'archive', NULL, '["鸟兽鱼虫","吉祥与礼仪"]', '["China, Eastern, 11th-12th century"]', '1000s–1200', 'Silk and gold thread; tapestry', 'assets/patterns/archive-CMA-153812.webp', 'assets/patterns/archive-CMA-153812-thumb.webp', 'a5a49d2f0cc93ddd34725dc29b22f50b17911f4af5e1c5066e3d7ae795b9cf3f', NULL, 1627, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1988.100', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1988.100', NULL, NULL, 'This reversible tapestry (kesi) fragment woven with silk and metal thread is a section from yardage likely intended for a garment, but no contemporary paintings exist to confirm this. The starting, bottom edge of the textile is preserved which indicates the bands at the base would have been the cuff ends of a garment. The design motifs of this kesi—a dragon at the top, bands of pearls and split palmettes, and tigers chasing deer with mushroom-shaped antlers—are a synthesis of Western and Chinese elements. The pearls, palmettes, and deer motifs originated in Iran and Sogdiana (an area east of the Caspian Sea and northwest of the Himalayas) but migrated east to China during the Tang dynasty (618–907). Although these motifs disappeared from Chinese art after the fall of the Tang, they survived in Central Asia. In contrast, the dragon is Chinese in origin, but here has a Central Asian form (particularly its extended snout).', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '龙纹 · 鹿纹 中国传统  鸟兽鱼虫 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-154215', '龙纹', 'Dragons Chasing Flaming Pearls', NULL, '中国传统', 'archive', NULL, '["鸟兽鱼虫","吉祥与礼仪"]', '["Central China"]', '1200s or earlier', 'silk and gold thread: tapestry', 'assets/patterns/archive-CMA-154215.webp', 'assets/patterns/archive-CMA-154215-thumb.webp', '64ce25c92b15c0b93ef5ba9049e793d8cbc3cd1f1dea957d53b288bacaeb31df', NULL, 1828, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1988.33', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1988.33', NULL, NULL, 'This rectangular, reversible tapestry (kesi) fragment, woven with silk and metal thread on a deep purple ground, is a section from yardage likely intended for a garment, but no contemporary paintings exist to confirm this. A selvage edge remains on the left; having an extant selvage edge provides us with information about the loom on which this textile was woven. The design motif of this kesi—dragons chasing flaming pearls—is Chinese. But the form of the dragons and the way they are crowded together is not Chinese. Rather than animals and birds among flowers, a frequently occurring pattern in the decorative art of eastern Central Asia that long predated the Mongol conquest, here the dragons are chasing flaming pearls. This deviation is indicative of the powerful influence of the Mongols.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '龙纹 中国传统  鸟兽鱼虫 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-157565', '鸟纹 · 刺绣', 'Embroidery with Birds', NULL, '中国传统', 'archive', NULL, '["鸟兽鱼虫","边饰与织锦"]', '["China, Tang dynasty (618-906)"]', '700s-800s', 'embroidery, silk thread on silk ground', 'assets/patterns/archive-CMA-157565.webp', 'assets/patterns/archive-CMA-157565-thumb.webp', '6090df2f4f95e55e3b98184a6f9fb8b4064e647515c7ef9b9b27ec74e4a8bbe9', NULL, 2048, 380, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1994.96', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1994.96', NULL, NULL, 'These engaging little birds are embroidered in a naturalistic style that developed during the 8th and 9th centuries. All but one are oriented away from the central pair that flanks a tulip growing from a hill. Contrasting with the spontaneity of the birds is the structured pattern of the silk ground—rosettes within a lozenge grid. Such contrasts frequently occur among embroideries of the Tang dynasty. Also characteristic of embroideries from that period is the use of discrete areas of color with no attempts at shading. The form of the birds, the hill, and the flower are based on Persian models. The introduction of foreign motifs into the decorative arts of Central Asia and China was one of the most important results of active trading in precious objects along the Silk Road.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '鸟纹 · 刺绣 中国传统  鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-163632', '龙纹', 'Woman''s Bridal Dress: Dragon Jacket, Pleated Skirt, Tabard', NULL, '中国传统', 'archive', NULL, '["鸟兽鱼虫","吉祥与礼仪"]', '["China, Qing dynasty (1644-1911)"]', '1800s', 'Silk, gilt-metal thread; embroidery', 'assets/patterns/archive-CMA-163632.webp', 'assets/patterns/archive-CMA-163632-thumb.webp', '8d44872aa075a55b348c88727c2bc377acf53270a79744034efb537aba0eaa61', NULL, 3400, 2336, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2005.135', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2005.135', NULL, NULL, 'This three-piece bridal dress includes a dragon jacket, a pleated skirt, and a tabard, a short loose-fitting sleeveless vest. The ensemble reveals the high rank of her husband even though it did not fall under the scope of the Qing Dynasty sumptuary laws. The woman''s bridal trousseau contains a short red coat with side-fastening and wide sleeves. It is decorated with ten dragons and other cosmological motifs commonly found on court dress. The presence of ten dragons indicates that the wife''s husband was a high-ranking official. The dragon jacket was worn over a pleated turquoise skirt, with six embroidered panels which feature dragons in the front and back.A three-quarter-length sleeveless tabard completes the outfit, with a front closure, open sides secured by cloth bands, and a colorful tasseled fringe around the hem. Dragons, water, and clouds are embroidered on the silk ground. In addition, a rank badge applied on the front and back shows that the bride married a man of high official rank.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '龙纹 中国传统  鸟兽鱼虫 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-133698', '刺绣', 'Embroidered Square', NULL, '中国传统', 'archive', NULL, '["几何与团花","边饰与织锦"]', '["China, late 19th century"]', 'late 1800s', 'embroidery, silk', 'assets/patterns/archive-CMA-133698.webp', 'assets/patterns/archive-CMA-133698-thumb.webp', '7bd10aa50b884869e3279a5d6b0d7745df498dfce33ef68af1ca7566981b20d3', NULL, 3400, 2397, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1956.312', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1956.312', NULL, NULL, NULL, NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '刺绣 中国传统  几何与团花 边饰与织锦');
