INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95083', '边饰与织锦', 'Wrapper for the Tapestry Scroll Mingling of Clear and Muddy Water at the Junction of the Jing and Wei Rivers', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Qing dynasty (1644–1911), Qianlong reign (1736–95)"]', '1736–95', 'Silk and metal thread: tapestry weave, painted with ink and colors', 'assets/patterns/archive-CMA-95083.webp', 'assets/patterns/archive-CMA-95083-thumb.webp', 'f1c2e6d5a2a9083a0914a313c2c8ad92b6016af88b65306294d124b19716f988', NULL, 3334, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1915.618.b', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1915.618.b', NULL, NULL, 'The cloth to wrap the tapestry scroll, Mingling of Clear and Muddy Water at the Junction of the Jing and Wei Rivers, CMA 1915.618.a, features a dragon, emblem of imperial power, on an imperial yellow ground.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95612', '吉祥与礼仪', 'Rank Badge (buzi)', NULL, '中国传统', 'archive', NULL, '["吉祥与礼仪"]', '["China, Qing dynasty (1644-1911)"]', '1850–99', 'silk and metal thread; slit tapestry weave (kesi)', 'assets/patterns/archive-CMA-95612.webp', 'assets/patterns/archive-CMA-95612-thumb.webp', '119bb68cd4fc45c91279a0f6f3a5f5757a7876f231639d01e7a32e519244c16f', NULL, 3400, 3218, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1329', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1329', NULL, NULL, 'Rank badges (also called rank insignia or Mandarin squares) were used in China during the Ming (1368–1644) and Qing (1644–1911) dynasties to demonstrate the wearer’s rank. In 1391 new clothing regulations directed court officials to wear decorative squares indicating their rank—birds for civil officials and animals for military officials. During the Qing dynasty rank badge design was regulated, and certain creatures were associated with specific ranks. Qing badges depict a representation of the universe with a landscape and a central creature, surrounded by clouds and facing the sun. The sun represented the emperor and this composition showed the official’s loyalty to him. An official’s wife wore rank badges that mirrored her husband’s. Most of the examples in CMA’s collection depict creatures facing a sun on the left. Attached to the front and back of a ceremonial robe, rank badges were woven in pairs with identical imagery. One was divided vertically up the center to attach to the front of a robe with a center opening. Rank badges are generally square or rectangular, although round examples exist. They are typically satin weave or slit tapestry weave (kesi) silk. Satin weave badges often have dark backgrounds with silk and/or metal thread embroidery. Some badges incorporate peacock feathers or beads. Late in the Qing dynasty appliqué replaced embroidery to allow for quicker production and a change in rank.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '吉祥与礼仪 中国传统  吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95642', '边饰与织锦', 'Rainbow Skirt', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Qing dynasty (1644-1911)"]', 'late 1800s', 'Silk: embroidery', 'assets/patterns/archive-CMA-95642.webp', 'assets/patterns/archive-CMA-95642-thumb.webp', '9870eb5439659d25b73c21a2e8cbf8af4219d109f84a6b4e314efc7f17099b7c', NULL, 2396, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1353', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1353', NULL, NULL, 'This bridal garment is referred to as a rainbow skirt. Originally jingling bells hung from the ends of each strip.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-122571', '边饰与织锦', 'Family Gathering on New Year''s Morning', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Qing dynasty (1644-1911)"]', 'late 1760s', 'Silk and wool: tapestry weave', 'assets/patterns/archive-CMA-122571.webp', 'assets/patterns/archive-CMA-122571-thumb.webp', '431bd147390eb41662e34d6ea8fa5b59e7715ce432f180b1589b9f0e5e3bbfe4', NULL, 3400, 2354, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1942.825', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1942.825', NULL, NULL, 'This European-style tapestry depicts a family gathering, in a woven Western picture frame, that presumably once furnished the Hall of Cultivating the Mind (Yangxin dian) in the Forbidden City. The tapestry employs Western perspective and shading combined with the traditional Chinese subject of a family gathering in a palace, including motifs expressing wishes for good fortune and for a peaceful reign. In 1766, six French tapestries had been presented to the Chinese court. The Qianlong emperor was so intrigued that he commissioned tapestries in the French style from Suzhou. Records mention an imperial order for tapestries in the Western style, such as this one, in 1769, 1770, and 1775.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中国传统  边饰与织锦');
