INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-127970', '边饰与织锦', 'Cope', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Macao"]', '1500s', 'Silk', 'assets/patterns/archive-CMA-127970.webp', 'assets/patterns/archive-CMA-127970-thumb.webp', '4136aa855c751ab6d0f057f2e6a5dbc74cc210367a72cd781f05dc26e28007e0', NULL, 3400, 1575, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1950.6', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1950.6', NULL, NULL, 'Silk fabric woven in China with European motifs was transported by European traders by the early 16th century. This popular pattern features a crowned double-headed eagle grasping arrows in its claws above a vase emitting blossoming vines. The eagle motif was derived from the Habsburg coat of arms, rulers of Spain and Austria during the 1500s and 1600s. Vertical borders with Chinese flora occur near the selvages of the five silk lengths forming the cope. The gilt-metal braided and fringed hood and broad orphrey band, or ornamental border, along the front edges feature fashionable small-scale floral sprigs.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-136409', '鸟纹', 'A Myriad of Birds', NULL, '中国传统', 'archive', NULL, '["鸟兽鱼虫"]', '["China, Qing dynasty (1644–1911)"]', '1700s–1800s', 'silk: satin weave with polychrome silk embroidery', 'assets/patterns/archive-CMA-136409.webp', 'assets/patterns/archive-CMA-136409-thumb.webp', '385c45829e711a8d14669de8200b9f29b763c9688f6180f8c4acfc548391745a', NULL, 2200, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1960.276', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1960.276', NULL, NULL, 'This embroidered panel, made with extremely fine silk threads, presents a lavishly detailed composition filled with fortuitous imagery. Pairs of birds, including mandarin ducks, peacocks, cranes, swallows, and pheasants, move among flowering trees, ornamental rocks, and aquatic plants, symbolizing harmony, prosperity, and longevity. Cranes stand for longevity, while a pair of mandarin ducks convey wishes for a harmonious marriage. Inspired by the decorative bird-and-flower paintings of the artist Lü Ji, the work prioritizes symbolism over spatial logic. With vibrant colors, meticulous stitching, and fortuitous meaning, the embroidery exemplifies the technical brilliance of Qing dynasty textile art, rivaling the quality of imperial production.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '鸟纹 中国传统  鸟兽鱼虫');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-148525', '袍服 · 织物', 'Uncut Robe: Proper Right Front and Back Panel', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Qing dynasty (1644–1911)"]', 'c. 1890s', 'embroidered silk, gauze weave', 'assets/patterns/archive-CMA-148525.webp', 'assets/patterns/archive-CMA-148525-thumb.webp', '6401fd56ef69e3b57d3618ed0e3a14e30b4e2bac56dc53416c4994d209c521b8', NULL, 1139, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1976.1088.b', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1976.1088.b', NULL, NULL, 'This is one of three panels of silk netting that would have been cut out and sewn into a gown. This continuous length of fabric would become the gown''s proper right front and back panel. The airy fabric is embroidered in gold, white, blues, pinks, and violets with designs of phoenix birds, chrysanthemums, and symbols of longevity.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '袍服 · 织物 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-151451', '袍服', 'Semi-formal Court Robe (Jifu)', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Qing dynasty (1644–1911), Jiaqing period (1796–1820)"]', 'late 1700s', 'Silk: satin weave; silk and metal thread: embroidery', 'assets/patterns/archive-CMA-151451.webp', 'assets/patterns/archive-CMA-151451-thumb.webp', '8a67cd75b47c7e021997e79aae41885b317925d8ee5c29d66ddcd6434b923ed9', NULL, 3400, 2483, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1983.32', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1983.32', NULL, NULL, 'The lavishly embroidered motifs of dragons, clouds, waves, and rocks on this robe form a diagram that symbolizes the universe: the lower horizontal band of waves at the hem represents the oceans that surround the earth, while the prism-shaped rocks emerging from the waves at the sides, front, and back of the coat symbolize the earth. The cloud-filled firmament above the waves shows dragons—symbols of imperial authority. During the Qing dynasty, yellow indicated “imperial” and the color’s use in garments was reserved for the emperor and his consorts. The emperor would have worn this type of court robe at semi-official meetings at court but not when he performed the official state rituals.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '袍服 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-152498', '吉祥与礼仪', 'Rank Badge (buzi)', NULL, '中国传统', 'archive', NULL, '["吉祥与礼仪"]', '["China, Ming dynasty (1368–1644)"]', 'c. 1500–1550', 'silk; slit tapestry weave (kesi)', 'assets/patterns/archive-CMA-152498.webp', 'assets/patterns/archive-CMA-152498-thumb.webp', '5de24fe0d3713203dc6dd302ada5091072133dd7a2801e986ecf087b04ef8dc5', NULL, 3400, 2996, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1985.32', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1985.32', NULL, NULL, 'Rank badges (also called rank insignia or Mandarin squares) were used in China during the Ming (1368–1644) and Qing (1644–1911) dynasties to demonstrate the wearer’s rank. In 1391 new clothing regulations directed court officials to wear decorative squares indicating their rank—birds for civil officials and animals for military officials. During the Qing dynasty rank badge design was regulated, and certain creatures were associated with specific ranks. Qing badges depict a representation of the universe with a landscape and a central creature, surrounded by clouds and facing the sun. The sun represented the emperor and this composition showed the official’s loyalty to him. An official’s wife wore rank badges that mirrored her husband’s. Most of the examples in CMA’s collection depict creatures facing a sun on the left. Attached to the front and back of a ceremonial robe, rank badges were woven in pairs with identical imagery. One was divided vertically up the center to attach to the front of a robe with a center opening. Rank badges are generally square or rectangular, although round examples exist. They are typically satin weave or slit tapestry weave (kesi) silk. Satin weave badges often have dark backgrounds with silk and/or metal thread embroidery. Some badges incorporate peacock feathers or beads. Late in the Qing dynasty appliqué replaced embroidery to allow for quicker production and a change in rank.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '吉祥与礼仪 中国传统  吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-153759', '袍服', 'Buddhist Priest''s Ceremonial Robe', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Ming dynasty (1368–1644)"]', '1400s', 'silk and gold thread; embroidery', 'assets/patterns/archive-CMA-153759.webp', 'assets/patterns/archive-CMA-153759-thumb.webp', '9b52847dc4ef15627a85c25ce2a539371e226d22e12193c5f9bacad28e11747b', NULL, 3400, 1413, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1987.57', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1987.57', NULL, NULL, 'This example of imperial embroidery is one of the earliest surviving Chinese Buddhist robes (kasaya) in the West. Depicting 991 Buddhas, each slightly different, it is constructed out of patches in reference to the legend in which the Buddha''s favorite disciple divided a robe he was given into 30 pieces. Patchwork is also a sign of humility. Multiple Buddha images known as “thousand Buddha” designs are seen painted and sculpted on the walls of cave temples in India, Afghanistan, Central Asia, and China, but are rare on garments. The Four Heavenly Kings, guardians of the four directions, occupy the textile’s corners. When draped around the body, the inverted figures in the upper left corner appear right side up. Robes with 25 columns were worn by the highest-ranking clergy on ceremonial occasions.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '袍服 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-155786', '织锦', 'Brocade with Hares', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["Northern China, Yuan dynasty (1271-1368)"]', '1200s–mid-1300s', 'Silk: tabby, brocaded; gold thread', 'assets/patterns/archive-CMA-155786.webp', 'assets/patterns/archive-CMA-155786-thumb.webp', 'a8d6b498b2548644814e8f3c782773c72a599b3b170fe249d7ea05c1959fb0f1', NULL, 3400, 2233, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1991.113', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1991.113', NULL, NULL, 'The motif of the hare among bushes may relate to the hunting activities of the Khitan, the Jurchen, and the Mongols. Hare hunts are recorded in the Liaoshi (History of the Liao Dynasty) and were often reported by envoys returning to China from the northern states. The asymmetry of the image in this textile is characteristic of Jin brocades. However, the paired (instead of single) warps reveal the influence of craftsmen from the eastern Iranian world and therefore dates the textile to the Mongol period.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织锦 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-155903', '佛教造像', 'Thangka with the Seventh Bodhisattva', NULL, '中国传统', 'archive', NULL, '["人物故事"]', '["China, Ming dynasty (1368–1644)"]', '1368–1424', 'Silk and gold thread on silk satin ground, embroidery', 'assets/patterns/archive-CMA-155903.webp', 'assets/patterns/archive-CMA-155903-thumb.webp', '5ebcbeb5d5621e074beb8754eacfbd5ac978b778bb08f8eee28b27752b733b4a', NULL, 1600, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1991.2', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1991.2', NULL, NULL, 'In remarkably pristine condition, this embroidery is from a dispersed set that included images of protectors and bodhisattvas. The embroidery technique and pictorial style are Chinese, but the subject matter and the type of devotional hanging called a thangka are associated with Tibetan Buddhism. Historical records state that during the early Ming dynasty (1368–1644), gifts of Buddhist art were sent from China to Tibet, since relationships between Chinese rulers and Tibetan monastic patriarchs were strong and amicable during this time. A Tibetan inscription on the back notes that this figure is the “seventh bodhisattva,” indicating the position in which it would have hung in a temple hall. Odd-numbered works were hung on one side of the main image, and even-numbered works on the other, counting from the center.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '佛教造像 中国传统  人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-156106', '织锦', 'Brocade with Djeiran Gazing at the Moon', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Jin dynasty (1115-1234)"]', '1115–1234', 'Silk and gold thread; tabby, brocaded', 'assets/patterns/archive-CMA-156106.webp', 'assets/patterns/archive-CMA-156106-thumb.webp', '20bb524c72986157988e4333a557bd1a39d5bbec472e65d23d8b63d941636644', NULL, 1508, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1991.4', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1991.4', NULL, NULL, 'The mysterious image of a deerlike animal gazing up at the moon among clouds has been variously interpreted over many centuries. The animal, lying down with one foreleg extended and looking back, originated as a djeiran, or Central Asian antelope. Commonly appearing on Sogdian silver from the 600s onward, the motif migrated via the trade routes to northern China. There, during the Jin and Yuan (1279–1368) dynasties, it was very popular and always depicted with the moon supported by clouds. Chinese writers often identify the djeiran as the mythical rhinoceros (xi''niu) that is said to gaze at the moon, or as the cow of Wu "panting upon seeing the moon."', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织锦 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-156273', '织物', 'Fragment from a Garment (smaller fragment, outer layer)', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Liao dynasty (907-1125), 10th century"]', '900s', 'weft-faced compound twill, silk', 'assets/patterns/archive-CMA-156273.webp', 'assets/patterns/archive-CMA-156273-thumb.webp', '59c208c95e4aeada6d4cca5c628dfb30ba9fd99c3f34c1ebd2ab25614029a1a0', NULL, 3400, 2694, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1992.112.2.a', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1992.112.2.a', NULL, NULL, 'This textile preserves part of an overall design of large, radiating floral motifs arranged in staggered, horizontal rows. In the spaces between are pairs of flying cranes and cloud scrolls that are common motifs in Liao paintings and decorative arts. The loose structure of the pattern and the naturalism of the motifs represent the final evolution of a pattern that had originated in the Tang dynasty (AD 618–907).', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-156749', '边饰与织锦', 'Pair of Boots', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Northern, Liao dynasty (907-1125)"]', '1000–1125', 'Silk: compound twill; silk and gold: tapestry; silk: tabby, gauze, batting; leather', 'assets/patterns/archive-CMA-156749.webp', 'assets/patterns/archive-CMA-156749-thumb.webp', 'bafba39c061056393533265c760b92392179385d5392862b13d4caa06ce644b9', NULL, 3179, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1992.349', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1992.349', NULL, NULL, 'The fabric and tailoring of garments have always defined social status. For these boots, different outer fabrics were used: a patterned silk for the leg portion, and tapestry (kesi) for the foot. Since both were considered luxury fabrics, they were pieced together from remnants too precious to discard. Consequently, the silk pattern was not used in relation to the form of the boot, as seen in some other imperial boots. By contrast, these boots would have been made for a court official, not a member of the imperial family. The patterned silk was woven with geese flanking a vase of flowers on a stand and surrounded by cloud scrolls. The Chinese motif of flowers arranged in a vase was adopted by the Liao during the 11th century and indicates an 11th- or early 12th-century date for the boots.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-156857', '边饰与织锦', 'Achala, King of the Wrathful Ones', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Zhejiang Province, probably Hangzhou"]', 'early 1200s', 'Thangka, silk tapestry with pearls', 'assets/patterns/archive-CMA-156857.webp', 'assets/patterns/archive-CMA-156857-thumb.webp', '5017ab21df499dad5464d194e74bc9222e2ab295e78badddbebab2e2d80c5469', NULL, 2485, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1992.72', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1992.72', NULL, NULL, 'The powerful blue body of Achala, meaning “immovable,” dominates the composition. He holds a sword to cut through ignorance and a noose for catching illusions that plague the path to enlightenment. Small personifications of furious destroyers of illusion (maya) emanate from him on either side, each with his own weapon. This image expresses what advanced practitioners would visualize in meditation rituals, as explained in Buddhist texts called tantras. Woven with a sophistication matched only by products of the Hangzhou looms, this devotional tapestry made its way to Khara-Khoto, capital of the Tangut Empire located in present-day Mongolia and Central Asia, where tantric Buddhism was prevalent.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-157004', '边饰与织锦', 'Pair of Boots', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["Northern China, Liao dynasty (907-1125)"]', '907–1125', 'Silk: tapestry weave; two kinds of metal threads', 'assets/patterns/archive-CMA-157004.webp', 'assets/patterns/archive-CMA-157004-thumb.webp', '3501208d963eb5ba191a65bf842d5ccd8bc0edead3b9ca431cb285ee81f1dc47', NULL, 3400, 2399, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1993.158', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1993.158', NULL, NULL, 'This magnificent pair of boots, made of finely woven silk tapestry (kesi), features two phoenixes in flight chasing a flaming pearl. Although the bright colors of the fabric have become muted from being buried in a tomb and the gold threads are partly disintegrated, the once lavish use of gold and the Chinese-inspired phoenix motif suggest that the boots were made for a member of the Liao imperial family, probably a woman. At the time the boots were made in the Khitan-occupied territory in northern China, footbinding was introduced among upper-class women in southern China. The high value the Khitan people accorded to boots relates to their mobile, seminomadic lifestyle.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-157337', '边饰与织锦', 'Pendant', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China"]', '1300s', 'silk, silvered paper, gilded paper, and gold thread; needleloop embroidery and knotting', 'assets/patterns/archive-CMA-157337.webp', 'assets/patterns/archive-CMA-157337-thumb.webp', 'ce202910928aee6e31e5f1f5c9f1471700e77d866c99d517d16e972dd5a82254', NULL, 593, 2048, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1994.20', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1994.20', NULL, NULL, 'Pendants were used extensively in Buddhist settings where they were attached to almost anything needing decoration: ritual objects, canopies, valances, pillars, and other architectural components. They could be made in a variety of ways. This example consists of a heading and six tiers, each embroidered separately and then attached, one to the next. The earliest known pendant of this type was found in Central Asia and dates from the Tang dynasty (618–907). The 14th-century date of this pendant is indicated by the style of the flowers.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-157588', '边饰与织锦', 'Pair of Headpieces', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Liao dynasty (907-1125)"]', '907–1125', 'embroidery, silk', 'assets/patterns/archive-CMA-157588.webp', 'assets/patterns/archive-CMA-157588-thumb.webp', '89954fc1a85d53a3cd528b515a7a35660dc2e92d097e273e78bcb79d959da0e2', NULL, 3400, 2897, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1995.109', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1995.109', NULL, NULL, 'These headpieces are embroidered with butterflies, birds, animals, flowers, leaves, and delicate vine scrolls. In general, the design is related to the theme of the lotus pond, best known from Liao tomb paintings. Paired ducks or geese swimming in water and looking in opposite directions seem to have become popular in the north of China before spreading further south and to Central Asia. On the other hand, recumbent animals looking back are a Central Asian image that migrated to northern China. Headpieces of this shape, intersected by two bands and secured by ties, have a long history in northern China. A gold replica was found in a tomb dating as early as 500–550.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-158153', '袍服', 'Woman''s Robe', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Liao dynasty (907-1125)"]', '907–1125', 'Silk and gold thread: embroidery on silk gauze ground; silk lining, silk batting', 'assets/patterns/archive-CMA-158153.webp', 'assets/patterns/archive-CMA-158153-thumb.webp', 'e5de50f5a5b547b7ed2b3273d95d5f478fa85cb4e6daacbb4790b2dae3d73e5d', NULL, 2048, 1623, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1995.20', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1995.20', NULL, NULL, 'The robe is embroidered on the back with clouds and paired phoenixes (associated with female members of the imperial family). Single phoenixes and clouds occur at the shoulders. On the front, fragments of another large pair of phoenixes remain. The birds and clouds are set against a scrolling vine pattern embroidered with gold thread, of which only the gold leaf remains. The design was drawn and then embroidered with silk and gold threads on lengths of fabric (gauze backed with silk) before they were cut and seamed. The robe was then lined with silk batting between the layers for warmth. Toward the end of the Liao dynasty, rules for wearing Khitan-style dress (overlapping toward the left) became increasingly relaxed. This may explain the robe''s front overlap toward the right, which accords with Chinese custom.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '袍服 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-161719', '袍服 · 织物', 'Woman''s Silk Robe', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Qing dynasty (1644-1911)"]', 'c. 1770–80', 'Silk: satin weave with supplementary weft pattern', 'assets/patterns/archive-CMA-161719.webp', 'assets/patterns/archive-CMA-161719-thumb.webp', '4937e5a5d7a68b1b569c7d9ce2c0f90a562cfa88f6b53864768bce1a3fd8a25b', NULL, 1536, 1949, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2000.77', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2000.77', NULL, NULL, 'This rare private, rather than court, surcoat displays flowers of all seasons arranged with elegant simplicity. Included among the 25 symbolic flowers are peonies, plum blossoms, magnolias, and chrysanthemums.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '袍服 · 织物 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-165310', '袍服', 'Tibetan Man''s Robe, Chuba', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Qing dynasty (1644-1911), Kangxi period (1662-1772)"]', 'late 1600s', 'Silk, gilt-metal thread of two kinds: satin weave with supplementary weft patterning', 'assets/patterns/archive-CMA-165310.webp', 'assets/patterns/archive-CMA-165310-thumb.webp', 'eace967bf83061fc3d18940a5972837c95b2f3ce49365d279f839a947a6d6257', NULL, 3400, 3143, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2007.216', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2007.216', NULL, NULL, 'This magnificent robe for a Tibetan lama or an aristocrat was originally a Chinese imperial wall hanging. Tibetan tailors cut it into 60 separate units, reassembling the fabric for a completely new and bold design. The wearer of such a garment must have impressed bystanders by his striking appearance. What you see here is the robe’s back side.Textiles played an important role in Chinese diplomacy with foreign governments. Diplomatic gifts of silk served to pacify border populations and to maintain balanced power relationships. Over centuries the Chinese court endeavored to keep a stable relationship with powerful Tibetan Buddhists. During the Qing dynasty (1644–1911) the Chinese court began to send gifts of court garments and furnishings to Tibet where they were altered to create Tibetan-style robes.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '袍服 中国传统  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95135', '织物', 'Kesi Panel: Rocks and Chrysanthemums', NULL, '中国传统', 'archive', NULL, '["边饰与织锦"]', '["China, Qing dynasty (1644-1911)"]', '1700s–1800s', 'Silk; embroidered', 'assets/patterns/archive-CMA-95135.webp', 'assets/patterns/archive-CMA-95135-thumb.webp', '907c778c18f4e00681acbf95500e0659470be8321ff269d35277ad9cd70dde84', NULL, 2073, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1915.653', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1915.653', NULL, NULL, NULL, NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 中国传统  边饰与织锦');
