INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-136335', '曼荼罗', 'Mandala of Chakrasamvara and Vajravarahi', NULL, '藏地与喜马拉雅', 'archive', NULL, '["人物故事","吉祥与礼仪"]', '["Nepal"]', 'late 1400s', 'Gum tempera on cloth', 'assets/patterns/archive-CMA-136335.webp', 'assets/patterns/archive-CMA-136335-thumb.webp', 'd2ba68d07680edf1cda6f591ec2ea64bc5c75a0c8c3f03d7687e049de210c947', NULL, 2968, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1960.211', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1960.211', NULL, NULL, 'A mandala is a two-dimensional diagram of a palace-like structure, viewed from above. This mandala depicts the abode of a 4-headed, 12-armed figure who personifies a major tantric Buddhist text, the Chakrasamvara-tantra. He dances in the bliss of sexual union with his consort, the red Vajravarahi, in the central circle, which is equivalent to the penthouse of their palace. Through guided meditation, practitioners can visualize entering through each of the four gates to experience the beauty of the enlightened realm. The outermost ring of cremation grounds indicates that one must overcome fear of death before reaching the realm of enlightenment.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '曼荼罗 藏地与喜马拉雅  人物故事 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-157147', '曼荼罗', 'Twenty-three Deity Nairatma Mandala', NULL, '藏地与喜马拉雅', 'archive', NULL, '["人物故事","吉祥与礼仪"]', '["Central Tibet"]', 'c. 1375', 'Gum tempera, ink, and gold on cloth', 'assets/patterns/archive-CMA-157147.webp', 'assets/patterns/archive-CMA-157147-thumb.webp', 'eefc7d92d27a50438dd9bba5300175d0da961595e472633e8b5eab496fefb159', NULL, 2958, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1993.4', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1993.4', NULL, NULL, 'A mandala is a diagram of a realm of enlightened beings. This mandala depicts the palace of Nairatma, who dances in the center. The outermost ring contains depictions of eight cremation grounds, where corpses burn, and dogs and vultures feed on human remains. Buddhist practitioners spend time in cremation grounds in order to overcome fear of death and attachment to their physical bodies. A practitioner can then reach the splendid realm of eternal bliss in the center. Accomplished teachers guide a practitioner’s meditations through the cremation grounds and every section of the mandala.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '曼荼罗 藏地与喜马拉雅  人物故事 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-94672', '曼荼罗', 'Mandala', NULL, '藏地与喜马拉雅', 'archive', NULL, '["人物故事","吉祥与礼仪"]', '["Tibet"]', 'early 1700s', 'color on canvas', 'assets/patterns/archive-CMA-94672.webp', 'assets/patterns/archive-CMA-94672-thumb.webp', '3b7d9308eb778b0f462c4756ca9c3ee46222eabf87f221738aa17c268cca9c22', NULL, 2206, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1915.316', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1915.316', NULL, NULL, NULL, NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '曼荼罗 藏地与喜马拉雅  人物故事 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-98873', '边饰与织锦', 'Yamantaka Vajrabhairava and consort Vajravetali', NULL, '藏地与喜马拉雅', 'archive', NULL, '["边饰与织锦"]', '["Tibet"]', '1700s', 'Silk appliqué embroidery with paper, metallic thread, hair, and ink', 'assets/patterns/archive-CMA-98873.webp', 'assets/patterns/archive-CMA-98873-thumb.webp', '707fd0ec73aab40db1651db9afe2fe32b4d6ef2d52493fdf6ad77b8a151d6434', NULL, 2289, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1918.548', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1918.548', NULL, NULL, 'Practitioners of tantric Buddhism meditate on this powerful image to conquer fear of death. As a manifestation of the bodhisattva of wisdom, Manjushri, whose gold head is at the apex of his nine heads, Yamantaka Vajrabhairava demonstrates that wisdom conquers fear and, ultimately, overcomes death itself by leading to enlightenment. With 9 heads, 34 hands, and 16 legs, he surpasses the powers of Yama, god of death. Yama, the blue figure with buffalo head below, has only two arms, and he wields his skull-topped scepter at impaled and decapitated bodies, judging their souls be sent to hell.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 藏地与喜马拉雅  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-539040', '人物故事', 'Ratnasambhava, Akshobhya, Vairochana with attendants, Amitabha, and Amoghasiddhi, Top cover, from a Manuscript of the Perfection of Wisdom in Eight Thousand Lines (Ashtasahasrika Prajnaparamita-sutra)', NULL, '藏地与喜马拉雅', 'archive', NULL, '["人物故事"]', '["Eastern India, Bihar, Vikramashila Monastery. Paintings: Nepal, Kathmandu"]', 'Sunday, September 14, 1119 (year 239 of the Newar Samvat in the month of Ashvina)', 'Covers: Gum tempera, colors, and paper on wood; pages: gum tempera and ink on palm leaves', 'assets/patterns/archive-CMA-539040.webp', 'assets/patterns/archive-CMA-539040-thumb.webp', 'a94b9bdc8d3121950aebb79bc15838db25724d899264c1ddb683e2eb221c97b9', NULL, 3400, 508, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1938.301.b', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1938.301.b', NULL, NULL, 'The inner side of the top cover is fully painted with images of the Five Cosmic Buddhas of Esoteric Buddhism. Each one has a different color, meaningful hand gesture, and is associated with a spatial direction. In the center is the white Vairochana holding his hands in the enlightenment mudra. On either side of the binding holes are the other four Cosmic Buddhas Akshobyha (blue, earth-touching mudra, east) and Amitabha (red, meditation mudra, west), and on the ends are Ratnasambhava (gold, gift-giving mudra, south) and Amoghasiddhi (green, fear-not mudra, north). The top side is covered with ritual materials indicating that this book was once an object of worship.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物故事 藏地与喜马拉雅  人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-132305', '佛教造像 · 人物', 'Temple Banner with pilgrimage sites and scenes from the "Svayambhu-purana" (Ancient Text of the Primordial Buddha)', NULL, '藏地与喜马拉雅', 'archive', NULL, '["人物故事"]', '["Nepal, Kathmandu Valley"]', '1635', 'Gum tempera and gold on cotton', 'assets/patterns/archive-CMA-132305.webp', 'assets/patterns/archive-CMA-132305-thumb.webp', 'e1cb25bbbc6c91639ce8e6b15261504be3a92bbef346ee6c6928c6a989f12d45', NULL, 3400, 1036, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1954.788', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1954.788', NULL, NULL, 'In the upper band, pilgrimage places in and around Nepal’s capital of Kathmandu are mapped and labeled with inscriptions in the Newari language. Below are scenes from the story of a king who ended a drought with the assistance of serpent deities and a Buddhist master. The king rides horseback at the lower left, and the serpent deities are the seated human figures with snake heads behind them. The white vase-shaped monument with pointed top, shown three times, is the Svayambhu Stupa, a sacred monument in Kathmandu dedicated to the Buddha Svayambhu.Probably half of a complete banner, this piece hung in a monastic courtyard during annual festivals.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '佛教造像 · 人物 藏地与喜马拉雅  人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-136332', '人物故事', 'Vajradhara, Nairatmya, and mahasiddhas Virupa and Kanha', NULL, '藏地与喜马拉雅', 'archive', NULL, '["人物故事"]', '["Central Tibet, Ngor monastery"]', 'c. 1450', 'Gum tempera and gold on cotton', 'assets/patterns/archive-CMA-136332.webp', 'assets/patterns/archive-CMA-136332-thumb.webp', 'a6b87108fd75643bed3d2a7eff9bacbfcc32f8a030e1eb563b9bc497e5dbf071', NULL, 2980, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1960.206', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1960.206', NULL, NULL, 'The first in a series depicting the masters who transmitted the teachings on how to reach enlightenment, this painting begins at the upper left with the dark blue Vajradhara, who represents the essence of all Buddhas. The female enlightened being Nairatmya is seated at the upper right. She transmitted the teachings to Virupa, the brown-skinned Indian yogi at the lower left, in a vision; his disciple Kanha is at the lower right.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物故事 藏地与喜马拉雅  人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-136333', '人物故事', 'Four seated Masters', NULL, '藏地与喜马拉雅', 'archive', NULL, '["人物故事"]', '["Central Tibet, Ngor monastery"]', 'c. 1450', 'Gum tempera and gold on cotton', 'assets/patterns/archive-CMA-136333.webp', 'assets/patterns/archive-CMA-136333-thumb.webp', 'b0de70d21012e28ec5a145d1dad1757f595a0d9ac46e8dc63991f9986be60c77', NULL, 2954, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1960.209', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1960.209', NULL, NULL, 'Founders and prominent masters of the Sakya order of Buddhism in Tibet are featured in this painting as part of the lineage of teachers who transmitted knowledge of their fundamental text, the Hevajra Tantra. It is part of a series of paintings made at one of the main Sakya monastic centers, which had close ties with Nepal. This Tibetan artwork includes Nepalese features, such as the delicate, decorative quality of the painting, its two-dimensionality, the exaggerated curvature of the upper eyelid, and the filling of all spaces with scrollwork.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物故事 藏地与喜马拉雅  人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-144961', '佛教造像', 'Green Tara', NULL, '藏地与喜马拉雅', 'archive', NULL, '["人物故事"]', '["Central Tibet"]', 'c. 1260s, mounted 2020', 'thangka; gum tempera, ink, and gold on sized cotton; mount: silk', 'assets/patterns/archive-CMA-144961.webp', 'assets/patterns/archive-CMA-144961-thumb.webp', 'f992f74dddc3b728788d22fe4003ee6cd00fe5f92c19c35b20f2687bb45d5837', NULL, 2877, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1970.156', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1970.156', NULL, NULL, 'For Tibetans, Green Tara is one of the preeminent figures of their Buddhist faith, a radiant savioress who embodies the female form of the perfect, enlightened mind. The Green Tara in the Cleveland thangka—a Tibetan devotional painting on cloth—specifically dispels fear and provides protection, just like her mantra inscribed on the back side of the painting. Her green color and fear-not gesture link her to the cosmic Buddha of the North, enshrined above her head. Most scholars agree that this work was painted by the celebrated Nepalese artist known as Aniko.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '佛教造像 藏地与喜马拉雅  人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-150723', '佛教造像', 'Eleven-Headed, Thousand-Armed Bodhisattva of Compassion (Avalokiteshvara)', NULL, '藏地与喜马拉雅', 'archive', NULL, '["人物故事"]', '["Western Tibet"]', 'c. 1500', 'Gum tempera and ink on cotton', 'assets/patterns/archive-CMA-150723.webp', 'assets/patterns/archive-CMA-150723-thumb.webp', 'b131f0d11554453bef3ec36652dc8bca92f7a3d82f7dc8b5aa66efcc2372db9b', NULL, 2483, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1982.147', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1982.147', NULL, NULL, 'One thousand arms surround the central figure like a radiating halo. Each hand has an eye in the palm to see the suffering of all beings, generating the sense of compassion that this figure embodies. The special form of the central image of the bodhisattva Avalokiteshvara derives from the mystic vision of a nun named Gelongma Palmo, who was born a Kashmiri princess, but prayed for leprosy to avoid having to marry and became an accomplished nun. While meditating in a cave, she achieved this vision of 11-headed, 1,000-armed Avalokiteshvara, who cured her leprosy and guided her on the path to enlightenment.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '佛教造像 藏地与喜马拉雅  人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-152324', '人物故事', 'Nagarjuna (c. 150–250 CE) with a Buddhist Master', NULL, '藏地与喜马拉雅', 'archive', NULL, '["人物故事"]', '["Nepal"]', 'c. 1300s', 'gum tempera on sized cotton', 'assets/patterns/archive-CMA-152324.webp', 'assets/patterns/archive-CMA-152324-thumb.webp', 'aa8655412eef620215b83fad67f3c42400fba336f5e294661b6578a47c299cf7', NULL, 2636, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1985.186', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1985.186', NULL, NULL, 'Nagarjuna, the Buddhist philosopher from southern India, sits on his eponymous red and black serpents, or naga. His interlocutor may be his disciple Aryadeva. A volume of the Perfection of Wisdom, honored with flowers, is on a golden bookstand between their heads. The figures sit beneath flowering and fruiting trees with peacocks and parrots, evoking the landscape of India. Lineage masters of the Sakya order of Buddhism are aligned in the top row, beginning with Virupa at the upper right. The monk who was the donor of this painting is in the lower left corner.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物故事 藏地与喜马拉雅  人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-153618', '人物故事', 'Portraits of Two Lineage Masters of the Kagyu Order: Phagmo Drupa (1110–1170) and Tashipel (1142–1210)', NULL, '藏地与喜马拉雅', 'archive', NULL, '["人物故事"]', '["Central Tibet"]', 'c. 1236–1310', 'Gum tempera on sized cotton', 'assets/patterns/archive-CMA-153618.webp', 'assets/patterns/archive-CMA-153618-thumb.webp', 'eea13eb42764be7b63f4a889fd4c4d49c17d16786935a141bcdea85a71784f83', NULL, 2606, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1987.146', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1987.146', NULL, NULL, 'High-level leaders of Buddhist monastic institutions were frequent portrait subjects of early thangka painting (devotional cloth scrolls) in Central Tibet. The lama (Tibetan monk) on the right founded Taklung Monastery in Lhasa, the capital of Tibet, which became an important institutional center of the Kagyu order. He is shown in discourse with his predecessor, whose teacher Gampopa (1079–1153), in turn, is the tiny gray-haired lama centered above them, between the colorful stylized mountain ranges.Their halos, lotus pedestal, and thrones with spitting elephant-trunked crocodiles and rearing griffins elevate them to the level of Buddhas and bodhisattvas. Despite their deification, they are still depicted with individualized facial features.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物故事 藏地与喜马拉雅  人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-159372', '狮纹 · 团形纹', 'Child’s Coat with Ducks in Pearl Medallions', NULL, '中亚与丝路', 'archive', NULL, '["鸟兽鱼虫","几何与团花"]', '["Probably Sogdia (present-day Uzbekistan)","China, Tang dynasty"]', '700s', 'Silk: weft-faced compound twill weave (samite)', 'assets/patterns/archive-CMA-159372.webp', 'assets/patterns/archive-CMA-159372-thumb.webp', 'c53043c30507b94b7b6ebfebebf9fd45733d3cdd67c29cc11c3cf4339a69b4d6', NULL, 3400, 2283, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1996.2.1', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1996.2.1', NULL, NULL, 'The coat’s outer fabric is woven in five brilliant colors featuring paired ducks in pearl roundels, hallmarks of the precious and highly desired silks from Sogdia. The coat’s inner lining is a twill damask with a floral pattern made in China. The combination of Sogdian and Chinese silks in one garment with Tibetan ownership history is evidence of the vital exchange and cultural interaction among the peoples living along the trade routes of the Silk Road.This precious coat was presumably made for a Tibetan prince. Given the coat’s pristine condition, though, it is unclear whether the garment was ever worn, or was used as a diplomatic gift or perhaps as currency.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '狮纹 · 团形纹 中亚与丝路  鸟兽鱼虫 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-156047', '狮纹', 'Tapestry with golden lions and palmettes', NULL, '中亚与丝路', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","边饰与织锦"]', '["Central Asia"]', '1200s or earlier', 'silk, gold thread; tapestry weave', 'assets/patterns/archive-CMA-156047.webp', 'assets/patterns/archive-CMA-156047-thumb.webp', 'bbda702375c6cd7f913e8ff7719caf3ccff33edba6f20caa7efcb44c5d913443', NULL, 1927, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1991.3', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1991.3', NULL, NULL, 'This reversible tapestry (kesi) fragment, woven with silk and metal thread, is a section from yardage likely intended for a garment, but no contemporary paintings exist to confirm this. A fringe of warps and a striped starting edge are preserved at the bottom of this fragment, as is a selvage along the left edge. Iranian golden lions, traditional symbols of royalty, are depicted amid large palmette leaves on vines. This kesi is different from other Central Asian silk kesi in the repetition of lions and palmettes in horizontal rows, facing alternate directions in an asymmetrical Chinese-inspired layout. But the depiction of lions with parted manes and tilted heads dates from the Sasanian dynasty of Iran (226–637 CE). The palmettes are common to both the Iranian world and Central Asia. This kesi may have been woven by Uyghurs living in the vicinity of Khotan, where the influence of Iranian culture was strong.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '狮纹 中亚与丝路  花草藤蔓 鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-156118', '花卉 · 凤鸟', 'Makaras, Phoenixes and Flowers', NULL, '中亚与丝路', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","吉祥与礼仪"]', '["Central Asia or Daidu, 13th century"]', '1200s', 'lampas, silk and gold thread', 'assets/patterns/archive-CMA-156118.webp', 'assets/patterns/archive-CMA-156118-thumb.webp', '474bbfcb4ecd5eec5b51dae3a652abe292be594a374e37fae8a85cff40d5b4ba', NULL, 3400, 2347, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1991.5', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1991.5', NULL, NULL, 'Central Asian designers drew from a wide variety of motifs, both imaginary and real. In this silk, rows of soaring phoenixes alternate with rows of makaras. Combining a fish body and tail, wings, and a dragon''s head, the makara originated in India as a water creature. With the spread of Buddhism, the motif migrated into the art of Central Asia and, from there, into the art of northern China. In Italy, exotic Central Asian patterns such as this inspired flights of imagination. One such example (seen in the photograph below) shows a creature, strikingly similar to the makara, spewing forth a dragon while a dog walks up its back.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 凤鸟 中亚与丝路  花草藤蔓 鸟兽鱼虫 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-157414', '凤鸟 · 织锦', 'Brocade with Phoenixes', NULL, '中亚与丝路', 'archive', NULL, '["鸟兽鱼虫","吉祥与礼仪","边饰与织锦"]', '["Central Asia, Jin dynasty (1115–1234)"]', '1100s–1200s', 'tabby, brocaded; silk and gold thread', 'assets/patterns/archive-CMA-157414.webp', 'assets/patterns/archive-CMA-157414-thumb.webp', 'c322c82e421ab328573085079f837c4596f736487eff75e78509ffac6d9d8b16', NULL, 1355, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1994.27', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1994.27', NULL, NULL, 'This elegant brocade of phoenixes, seen almost frontally, is woven with gold thread made from flat strips of gilded paper instead of the usual strips of gilded parchment. This suggests that the textile was woven in the southern part of the Jin state that had been annexed from the Chinese. Although probably intended to serve as secular clothing, this textile ended up in a Buddhist institution. The end was folded and stamped in red ink with a seated Buddha flanked by two Bodhisattvas (now faint and upside down). Two Tibetan inscriptions were also stamped (translation: "The Bhagavan, the Tathagata, the Arhat, the completely perfect Buddha," and "Salutations to Blo gnas.") Above, an isolated letter ka indicates that the textile was used to cover the first volume of a set of books.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '凤鸟 · 织锦 中亚与丝路  鸟兽鱼虫 吉祥与礼仪 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-152509', '织物', 'Textile with Tiny Leaves', NULL, '中亚与丝路', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Central Asia, Il-khanid (Mongol) period"]', '1275–1350', 'Silk and gold thread; tabby with supplementary weft', 'assets/patterns/archive-CMA-152509.webp', 'assets/patterns/archive-CMA-152509-thumb.webp', 'cab522041a7cca52ce47329912a6e5197030821f636ffe4f04c3033bd7901023', NULL, 3400, 3143, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1985.33', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1985.33', NULL, NULL, 'The shimmering gold of the tiny scattered leaves in this silk perfectly suited the taste of the Mongol court. Showing no Chinese or eastern Iranian influence, this type of pattern appears to have been indigenous to eastern Central Asia. The closest parallels to the tiny leaves densely strewn across the surface are found among the silk tapestries of the Uyghurs.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 中亚与丝路  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-156983', '几何纹 · 织物', 'Textile with Diamonds', NULL, '中亚与丝路', 'archive', NULL, '["几何与团花","边饰与织锦"]', '["Central Asia"]', '1000s', 'silk, cotton, and silver thread: tabby with supplementary weft', 'assets/patterns/archive-CMA-156983.webp', 'assets/patterns/archive-CMA-156983-thumb.webp', 'cb8f4f741ffb130b0c008945f0075c247468f6608b5b73ecf44916612e9ec3b9', NULL, 2083, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1993.139', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1993.139', NULL, NULL, 'Few Central Asian luxury silks dating from the 900s–1000s have survived. Here the cotton wefts, together with thin, widely spaced silk warps, identify this example as Central Asian. Its date has been determined by comparing it with two related textiles that are securely dated. At this time Chinese silks with small-scale diamond patterns were usually reserved for undergarments or linings. The use of silver thread for the tiny diamonds in this example, however, may indicate that in Central Asia the design had greater importance. Over time, this textile made its way to Europe, where it was preserved in a church treasury. Because such textiles were expensive, rare, and sometimes associated with saints, they were highly valued regardless of their condition.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '几何纹 · 织物 中亚与丝路  几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-157123', '织物', 'Textile with Palmettes', NULL, '中亚与丝路', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Central Asia, Il-khanid (Mongol) period"]', '1200s–1300s', 'Silk and gold thread; tabby with supplementary weft', 'assets/patterns/archive-CMA-157123.webp', 'assets/patterns/archive-CMA-157123-thumb.webp', '63b851647a89e85827e9374f546383cc785c23c5a0765956e1f3f82027ed4daf', NULL, 847, 2048, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1993.253', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1993.253', NULL, NULL, 'Designs of repeated ogives were popular in Central Asia and survive in a number of variations. Usually, the ogival frame encloses a floral motif, as in this example. Sometimes paired animals occur instead. Silks with this type of pattern were exported to Western Asia and to Europe, where they inspired textile designs woven locally. Mongol silks with exotic floral and animal patterns were acquired for use as clothing and furnishings by the clergy and nobility. They were also used by painters as models for hangings or garments.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 中亚与丝路  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95709', '边饰与织锦', 'Man''s surcoat (khalat)', NULL, '中亚与丝路', 'archive', NULL, '["边饰与织锦"]', '["Uzbekistan, Shahr-i Sabz"]', 'late 1800s', 'Silk: embroidery, cross-stitch', 'assets/patterns/archive-CMA-95709.webp', 'assets/patterns/archive-CMA-95709-thumb.webp', '2b916d3e8d51b1786a1391299352e92fbe674fd9a8d4853adfaf5261539b5022', NULL, 3400, 2550, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1412', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1412', NULL, NULL, 'Prestigious men’s surcoats embellished with designs such as this dramatic decoration in cross-stitch were among the most elaborate silk-thread embroidered garments in Central Asia. In a flamboyant style, large palmettes framed by split palmette leaves dominate with quartered rosettes and smaller flora on a brilliant yellow ground. Foliate vines enhance the edge along the front center opening, hemline, and cuffs. It is lined with an ikat of cypress trees and finger-looped trim. The style and technique represent professional work from Shahr-i Sabz, south of Samarkand. The pattern was drawn on the cotton ground cloth of the surcoat, then disassembled for stitching, and finally reassembled—revealed by severed and misaligned motifs plus mismatched colors.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中亚与丝路  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95777', '边饰与织锦', 'Woman''s cloak (chyrpy)', NULL, '中亚与丝路', 'archive', NULL, '["边饰与织锦"]', '["Uzbekistan, Bukhara"]', '1800s', 'Cotton; silk: embroidery', 'assets/patterns/archive-CMA-95777.webp', 'assets/patterns/archive-CMA-95777-thumb.webp', '0e20a0e1198dcd4ee3437fe7e2564e86677f296bcc6dcf10c1ba41b8e10f4191', NULL, 2521, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1468', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1468', NULL, NULL, 'This yellow silk is richly embroidered in the button-hole stitch. The pattern of this woman''s cloak resembles one of the patterns on the so-called Bokhara stripes used for fixing tents. The garment is lined with printed cotton fabric, which seems to be a product of India or Persia, and very crude block-printed cotton fabric with simple allover patterns of red and black dots and circular medallions.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中亚与丝路  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-119771', '边饰与织锦', 'Wall Hanging', NULL, '中亚与丝路', 'archive', NULL, '["边饰与织锦"]', '["Uzbekistan, Bukhara or Shahr-i Sabz, 19th century"]', '1850–1899', 'Silk, cotton; plain weave, embroidery, tambour chain stitch', 'assets/patterns/archive-CMA-119771.webp', 'assets/patterns/archive-CMA-119771-thumb.webp', 'f24a9ab31aae92a0997d3ca2e06c46ba0689c3690fa21dd1959d12131320ae92', NULL, 2322, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1940.602', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1940.602', NULL, NULL, 'Embroideries known as suzani, after the Persian and Tajik word for needle (suzan), feature bold floral and foliate motifs enriched with several shades of red and crimson silk thread. This example suggests a lush garden enriched with single flowering plants alternating with a bird’s-eye view of blossoms in a foliate diamond trellis. Either a skilled family member or a professional drew the pattern in black ink (still visible) on five loosely joined cotton cloths; female family members disassembled them for stitching and reassembled them upon completion. Suzanis were made in many towns, generally with distinctive artistic and technical characteristics.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中亚与丝路  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-135579', '团形纹', 'Roundels with Hunters', NULL, '中亚与丝路', 'archive', NULL, '["几何与团花"]', '["Eastern Iran or Central Asia"]', '800s', 'Silk: samite weave', 'assets/patterns/archive-CMA-135579.webp', 'assets/patterns/archive-CMA-135579-thumb.webp', 'f263643ad1afcac82e576307c771a8a7eeedf74db399257af1391af1b1d42802', NULL, 3400, 1808, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1959.124', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1959.124', NULL, NULL, 'This textile consists of two fragments mounted together. They are woven with floral roundels that enclose horsemen hunting lions. The theme of riders hunting with lances, the floral frames of the roundels, and the costumes of the hunters were all inspired by silks from the Byzantine world. The stiff, abstracted style, however, is characteristic of Sogdian silks, woven in Sogdiana in Central Asia and often traded to distant markets. These fragments were preserved in a grave in Egypt where they were found sewn as ornaments onto a tunic.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '团形纹 中亚与丝路  几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-148006', '织物', 'Samite fragment with hunters', NULL, '中亚与丝路', 'archive', NULL, '["边饰与织锦"]', '["Eastern Iran or Central Asia"]', '800s', 'Silk: compound twill', 'assets/patterns/archive-CMA-148006.webp', 'assets/patterns/archive-CMA-148006-thumb.webp', '69b76bde63ef8978027796bc2ac3a4a2333b9c8d869edff1fb0aec0bd1072632', NULL, 3400, 1847, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1974.98', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1974.98', NULL, NULL, 'This silk depicts pairs of horsemen hunting ibexes (mountain goats). The ibexes and two pairs of rabbits originally filled the spaces between rows of large floral roundels. Portions of the roundels are preserved at the top and bottom. Although the design was greatly influenced by silks from Egypt and Syria, the abstract style is typically Sogdian, from an area in Central Asia. This is one of many Sogdian silks that were traded to Europe and eventually preserved in church treasuries.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 中亚与丝路  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-153617', '人物故事', 'Celestial Musician', NULL, '中亚与丝路', 'archive', NULL, '["人物故事"]', '["Central Asia"]', '1300s', 'silk and gold thread over two layers of cotton, embroidery', 'assets/patterns/archive-CMA-153617.webp', 'assets/patterns/archive-CMA-153617-thumb.webp', '0fff9102431d5d26f3b013c7c6b805335c26f352659674ee513ae7c2c67c4ab0', NULL, 1407, 2048, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1987.145', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1987.145', NULL, NULL, 'Although a number of Buddhist textiles produced in the Sino-Tibetan style survive, Central Asian embroideries from the same period are exceedingly rare. Here, a goddess standing on a lotus support and playing a bowed lute may be the personification of the sense of hearing. In Buddhism, the five senses were represented as female deities, each a different color (in this case, blue). The style of the figure, her hair, the form of her crown, the nervously ruffled hem, the scrolling scarves, and the rainbow halo with rays are Central Asian. This figure originally was part of a large hanging.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物故事 中亚与丝路  人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-154940', '狮纹', 'Cloth of gold with winged lions and griffins', NULL, '中亚与丝路', 'archive', NULL, '["鸟兽鱼虫"]', '["Central Asia"]', '1225–75', 'Silk and gold thread: lampas', 'assets/patterns/archive-CMA-154940.webp', 'assets/patterns/archive-CMA-154940-thumb.webp', 'c8c2484956a5c51584c44494da5bc1d3c7185943c32e03cbfb86cac6bc213fd9', NULL, 1438, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1989.50', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1989.50', NULL, NULL, 'The Mongols created exceptionally sumptuous cloths of gold to symbolize their imperial authority and legitimacy, this being the most resplendent example known. Opulent expanses of gold thread enrich the roundels, lions, and griffins in striking contrast with the intricate brown silk foliate ground. The pattern integrates motifs from Iran—paired lions in roundels and paired griffins—and from China, cloud ornaments on the lions’ wings. They suggest it was woven in an imperial workshop in Central Asia where Iranian and Chinese craftsmen worked together with local artisans. The gold is on a paper substrate associated with Asia, whereas animal skin substrates were used in Islamic lands. It is woven in a new technique developed by Iranian weavers, a combination of two weaves known as lampas, which was adopted internationally.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '狮纹 中亚与丝路  鸟兽鱼虫');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-159534', '边饰与织锦', 'Cloth of Gold: Displayed Falcons', NULL, '中亚与丝路', 'archive', NULL, '["边饰与织锦"]', '["Central Asia"]', 'mid-1200s', 'Silk and gold thread, lampas', 'assets/patterns/archive-CMA-159534.webp', 'assets/patterns/archive-CMA-159534-thumb.webp', '0dc60f2f04b6bc8948b50c00b6ea448010c9a9adf3f979070736ce66414918e3', NULL, 1157, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1996.297', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1996.297', NULL, NULL, 'Mongol ceremonial robes, known as zhisun, were made from textiles woven with gold and silk of one color. These were given by Mongol emperors to members of the court to be worn during festivals and on important occasions that usually included lavish banquets. Like the Winged Lions and Griffins (CMA 1989.50), the design of this silk is a uniquely Central Asian synthesis of eastern Iranian and Chinese elements. Motifs and technical details shared by the two silks, moreover, leave no doubt that they were produced in the same city.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中亚与丝路  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-164664', '边饰与织锦', 'Wall Hanging (pardah)', NULL, '中亚与丝路', 'archive', NULL, '["边饰与织锦"]', '["Uzbekistan, Bukhara"]', '1800–1850', 'Silk: warp-faced plain weave, warp-ikat; cotton weft', 'assets/patterns/archive-CMA-164664.webp', 'assets/patterns/archive-CMA-164664-thumb.webp', '03355a325443baf9f57bb6d753bc8e13779d8377fc11c572d775fed974865a9c', NULL, 2344, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2006.150', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2006.150', NULL, NULL, 'Dazzling patterns with saturated colors in the ikat technique provided vibrant wall hangings in reception rooms of the urban elite in Central Asia. In this splendid example composed of five loom widths, the three central lengths display a precise design of amulets complemented by palmettes in the two outer lengths. The irregular contours, telltale indicators of ikat, are masterfully controlled with five rich colors, illustrating the high quality of the earliest known examples in Central Asia from the first half of the 1800s. In the ikat technique, the design was dyed on the warp before it was woven in a resist-dye process. Thread was tightly wrapped around the warp to resist dye penetration for each area of color. This labor-intensive process created hangings and garments cherished for their vibrant colors with "fuzzy" contours.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中亚与丝路  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-164666', '边饰与织锦', 'Wall hanging (pardah)', NULL, '中亚与丝路', 'archive', NULL, '["边饰与织锦"]', '["Uzbekistan, Bukhara"]', '1850–75', 'warp ikat, warp-faced plain weave; silk warp; cotton weft; 5 panels./ lining: printed cotton, plain weave; 2 panels', 'assets/patterns/archive-CMA-164666.webp', 'assets/patterns/archive-CMA-164666-thumb.webp', 'c510ac530358cc7c67ba6eb55ac60514ffea95a442b3b0d1bb93cf5261d77950', NULL, 2537, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2006.152', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2006.152', NULL, NULL, 'Eye-dazzling patterns with saturated colors demonstrating the ikat technique provided vibrant wall hangings for the reception rooms of the urban elite in Central Asia. In this splendid example comprising five loom widths, three lengths display popular amulet designs while the two inner lengths are precursors to the bold chevron designs of the late 19th century. The irregular contours—telltale indicators of ikat—are masterfully controlled with five rich colors. In the ikat technique, designs are dyed on the warp (vertical thread) in a resist-dye process before being woven. Thread is tightly wrapped around the warp to prevent dye penetration in each area of color, beginning with the lightest shades to the darkest. This labor-intensive process produces vivid colors and fuzzy contours.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中亚与丝路  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-167454', '袍服', 'Woman’s Robe (munisak)', NULL, '中亚与丝路', 'archive', NULL, '["边饰与织锦"]', '["Uzbekistan, Bukhara"]', '1850–75', 'Silk: velvet ikat', 'assets/patterns/archive-CMA-167454.webp', 'assets/patterns/archive-CMA-167454-thumb.webp', '750370536cd8e7e208e4f4dbd6cb8d13fedaf38f6f0fc527c41538b8c668d59c', NULL, 3400, 2294, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2009.267', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2009.267', NULL, NULL, 'Dazzling ikat velvet robes, the most sumptuous, expensive, and prestigious type of ikat, were worn throughout Central Asia by men and women. This resplendent robe with a V-shaped neckline, fitted torso, and slightly flaring skirt features stylized blossoming plants, pomegranates, and auspicious curved ram’s horns, all with irregular contours of the resist-dye ikat technique. Such female robes were culturally significant in Central Asia. Made for wedding dowries with fabric from the groom’s family, women wore munisaks for rites of passage throughout their lives, as a bride, at family festivals, and funerals.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '袍服 中亚与丝路  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-168369', '边饰与织锦', 'Woman’s Mantle (Chyrpy)', NULL, '中亚与丝路', 'archive', NULL, '["边饰与织锦"]', '["Central Asia, Turkmenistan, Tekke tribe"]', 'late 1800s–early 1900s', 'Exterior: silk; plain weave; embroidery: chain stitch; Trim: silk; tablet-woven with fringe; Lining: cotton; plain weave, block printed', 'assets/patterns/archive-CMA-168369.webp', 'assets/patterns/archive-CMA-168369-thumb.webp', '6fd32acba9172424355565b7b2e0fe50d0b5f9071e688d728dee135e93362e46', NULL, 3400, 2442, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2010.192', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2010.192', NULL, NULL, 'Traditional costumes in central Asia have distinctive characteristics that indicate ethnicity, age, and class. One of the oldest examples is a woman’s coat with false sleeves attached on the back and worn over the head. This silk coat in yellow, the color worn by middle-aged women, is elaborately decorated with popular stylized tulips embroidered in chain stitch. Worn consistently by a newlywed, the coat was later only used on special occasions. Although women made and embroidered garments at home, this expensive luxury mantle was professionally made and sold in the marketplace.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 中亚与丝路  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-287526', '花卉', 'Suzani with floral sprays', NULL, '中亚与丝路', 'archive', NULL, '["花草藤蔓"]', '["Central Asia, South West Uzbekistan, Shakhrisyabz"]', '1800–1850', 'Cotton: plain weave, 6 strips; silk: embroidery; filling stitch: kanda xajol, occasionally bosma; outlining stitch: ilmoq', 'assets/patterns/archive-CMA-287526.webp', 'assets/patterns/archive-CMA-287526-thumb.webp', 'ddfffe283101abc69f8bcaccdd48a9145b831c08a2275e28f95b043c2b90edf2', NULL, 2614, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2016.89', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2016.89', NULL, NULL, 'Embroidered textiles were essential items in dowries. This type, known as a suzani after the Persian and Tajik word for needle, suzan, were created by mothers and daughters who proudly displayed them during wedding festivities and special occasions. This is an especially striking example, probably embroidered in Shakhrisyabz, located south of Samarkand in Uzbekistan, during 1800–1850. Suzani were made for numerous functions including the nuptial bed, curtains for storage niches, and wrappers for various dry goods. Floral and foliate motifs generally dominate as seen here, enriched with several shades of red and enhanced by the varied light reflections and colors of the silk thread. Possibly the motifs conveyed cosmological, apotropaic, medicinal, or fertility associations especially for married life. Patterns were drawn in black ink on several loosely joined cotton cloths by a skilled family member or a professional. The cloths were then separated, embroidered individually, and reattached, confirmed by mismatched motifs where the lengths are joined. They are generally attributed to nineteenth-century production after sericulture was introduced in the Merv area around 1800.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 中亚与丝路  花草藤蔓');
