INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-106696', '狮纹 · 团形纹 · 织锦', 'Brocaded silk with foliate medallions from a kaftan', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","几何与团花","边饰与织锦"]', '["Turkey, Istanbul, Ottoman period"]', '1525–75', 'Silk: lampas weave, silver-metal thread', 'assets/patterns/archive-CMA-106696.webp', 'assets/patterns/archive-CMA-106696-thumb.webp', '007f58873453c143252f5bdcc7928327df4e972534416e1d003451e94266d024', NULL, 1645, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1924.741', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1924.741', NULL, NULL, 'Medallions enriched with floral and foliate decoration were signature Ottoman patterns during the height of silk textile production in the second half of the 1500s. Imperial kaftans with related patterns are preserved in the Topkapi Palace Museum in Istanbul along with those worn by young princes. In this splendid length from a kaftan, abundant silver-thread flora and overlapping leaves on vines enliven medallions in the densely woven fabric. It is a combination of two weaves, called lampas, which creates two contrasting surfaces composed of vertical warps and horizontal wefts.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '狮纹 · 团形纹 · 织锦 波斯与西亚  花草藤蔓 鸟兽鱼虫 几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95795', '孔雀 · 狮纹 · 团形纹', 'Wall cover with flora, peacocks, and portrait medallions', NULL, '波斯与西亚', 'archive', NULL, '["鸟兽鱼虫","人物故事","几何与团花"]', '["Iran, Qajar period (1779-1925)"]', '1800s', 'taffeta, hand-painted, block-printed: silk and pigments', 'assets/patterns/archive-CMA-95795.webp', 'assets/patterns/archive-CMA-95795-thumb.webp', '67a0fa4dff044241713514e8adc672df0f352efc4660f6243de46bcdd706cc67', NULL, 3400, 1467, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1483', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1483', NULL, NULL, 'The European fashion of installing Chinese export silks with painted decoration as luxurious wall coverings may have inspired this exceptional Iranian silk. European engravings, which had flooded the Iranian market by the 19th century, most likely inspired the pattern. This rare silk fabric with painted figural and foliate decoration may have been a luxurious wall covering in a palace or grand mansion in the city of Kashan where mural paintings display similar 19th-century designs. Glistening silver pigment originally formed the palmette-leaf compartment outlines (now mostly deep yellow) that display colorful blossoming plants enlivened with now tarnished silver peacocks. At their junctures, portrait medallions of Iranian princesses are distinctly Qajar in attire and style, as are the composite blossoming plants.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '孔雀 · 狮纹 · 团形纹 波斯与西亚  鸟兽鱼虫 人物故事 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-124971', '花卉 · 狮纹 · 团形纹', 'Lampas with floral medallions in ogival lattice', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","几何与团花"]', '["Turkey, Istanbul or Bursa"]', '1550–75', 'Silk and gilt-metal thread; lampas', 'assets/patterns/archive-CMA-124971.webp', 'assets/patterns/archive-CMA-124971-thumb.webp', '5f535bea011a298f12ab34683205cdf34d2b63e6ce4217eeb94c82944a63dad5', NULL, 2204, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1946.419', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1946.419', NULL, NULL, 'This signature Turkish brocaded silk has a classic elegance associated with the artistic height of the 1500s. The prominent golden medallions and ogival (curved) lattice contrast with exceptionally delicate Turkish flowers—tulips, roses, carnations, and hyacinths—which all grow on a single vine. The symmetrical design and two complete medallions with lattices across the width are typical Turkish features of fine brocaded silks. Its original function is uncertain. Possibly it was intended for an imperial kaftan, a garment consisting of a long gown with sleeves reaching below the hands, examples of which are preserved in the Topkapi Palace in Istanbul, the imperial center of the vast and wealthy Ottoman Empire.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 狮纹 · 团形纹 波斯与西亚  花草藤蔓 鸟兽鱼虫 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-125977', '龙纹 · 织物', 'Tent panel of a dragon slayer', NULL, '波斯与西亚', 'archive', NULL, '["鸟兽鱼虫","吉祥与礼仪","边饰与织锦"]', '["Iran, Yazd[?], reign  of Shah Tahmasp, Safavid period (1501-1736)"]', '1550–99', 'velvet, cut, voided, brocaded, and pile-warp substitution: silk and gilt-metal strips', 'assets/patterns/archive-CMA-125977.webp', 'assets/patterns/archive-CMA-125977-thumb.webp', 'fdc9d86459f6659dcd122107d566fa68ad7c277889b22c8678c1bdf2a1a21fcc', NULL, 2734, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1948.205', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1948.205', NULL, NULL, 'Iranian luxury textiles of the 16th and 17th centuries are renowned for representing human figures and for creating the most colorful velvets ever woven. Here, a dragon slayer dressed in 16th-century court attire is poised to hurl a boulder at a snarling dragon in a landscape with blossoming fruit trees and perched fowl. Even with faded silk pile this velvet contains many nuanced tones. As many as 12 colors of velvet pile were achieved by weavers who skillfully replaced colored pile warp during weaving.This velvet medallion decorated the interior of an imperial tent, possibly donated by Shah Tahmasp to an Ottoman Turkish sultan. Captured after the Ottoman siege of Vienna in 1683, the medallion was claimed as war booty by the European commander-in-chief Prince Sanguszko of Poland by whose name this and other panels are known.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '龙纹 · 织物 波斯与西亚  鸟兽鱼虫 吉祥与礼仪 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-128065', '狮纹 · 动物 · 团形纹', 'Fragment with confronted animal medallions and kufic bands', NULL, '波斯与西亚', 'archive', NULL, '["鸟兽鱼虫","几何与团花","边饰与织锦"]', '["Iran"]', '1480–1649 (radiocarbon date, 95% probability)', 'Silk: diasper, tabby weave', 'assets/patterns/archive-CMA-128065.webp', 'assets/patterns/archive-CMA-128065-thumb.webp', '8e3dc1e17dc8225b80b4dff60d3784df053bf83b1b2b1d777311d3c31512c943', NULL, 3400, 2941, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1950.84', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1950.84', NULL, NULL, 'The fragment preserves a wide central band flanked by narrower inscription bands. The narrower bands contain, on a dark blue background, a continuous inscription in elaborate Kufic, the ivory-colored lettering oriented at right angles to the warp. On the wider ivory panel there appear ovals enclosing a frieze of running animals within which are hexagons enclosing stars. The ovals alternate vertically with cartouches containing an inscription in simple Kufic, the design appearing in blue, pink, and ivory.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '狮纹 · 动物 · 团形纹 波斯与西亚  鸟兽鱼虫 几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-129826', '动物 · 团形纹 · 边饰', 'Embroidered border and field of animals in large roundels', NULL, '波斯与西亚', 'archive', NULL, '["鸟兽鱼虫","几何与团花","边饰与织锦"]', '["Iraq, probably Baghdad, Seljuk period"]', '1000s–1100s', 'plain weave: silk warp and cotton weft (mulham): plain weave; silk and gold thread: embroidery, couched, split, running, and outline stitches:', 'assets/patterns/archive-CMA-129826.webp', 'assets/patterns/archive-CMA-129826-thumb.webp', '49ac473f843cd379d18da685169d0bf6168c272833fb65e2954bc64fcce4663a', NULL, 2116, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1952.257', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1952.257', NULL, NULL, 'This fragment preserves part of the main field and border of a large textile. At the top is a small segment of a roundel frame with fragments of a pair of confronted animals; at the lower right is part of a smaller roundel in which only the hind part of a lion or griffin remains. Below the roundels is a section of a wide border with a large bird wearing Sasanian flying ribbons about its neck. It is framed in a roundel formed by the tendrils of a scrolling vine. A narrow band at the bottom has a badly garbled Kufic inscription, which is upside down in relation to the rest of the pattern. Only the word "Allah" repeated twice can be deciphered.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '动物 · 团形纹 · 边饰 波斯与西亚  鸟兽鱼虫 几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-152587', '藤蔓 · 凤鸟', 'Lampas with phoenixes amid undulating vines', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","吉祥与礼仪"]', '["Eastern Iran, Ilkhanid period"]', 'late 1200s-1300s', 'lampas: silk, cotton, and gold thread', 'assets/patterns/archive-CMA-152587.webp', 'assets/patterns/archive-CMA-152587-thumb.webp', 'a8b5056fc9d6604d7b2cfaf8d95b81a59af4008d0a7dd7bb88a6a25adb91de55', NULL, 3331, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1985.4', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1985.4', NULL, NULL, 'The elegant design of standing or diving phoenixes among parallel, curving floral vines is based on Chinese textiles. The phoenixes are actually of two types (notice the difference in their tails). Their combination, probably an innovation of Yuan China (1279-1368), also appears on the embroidered canopy (cat. no. 60) in this exhibition. In the eastern Iranian world, Chinese motifs and patterns were incorporated into local designs beginning in the 1270s.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '藤蔓 · 凤鸟 波斯与西亚  花草藤蔓 鸟兽鱼虫 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-162075', '狮纹 · 团形纹 · 几何纹', 'Brocaded velvet with medallions in ogival lattice', NULL, '波斯与西亚', 'archive', NULL, '["鸟兽鱼虫","几何与团花","边饰与织锦"]', '["Turkey, Istanbul or Bursa"]', 'late 1500s', 'Silk: velvet, brocaded; gilt- and silver-metal thread', 'assets/patterns/archive-CMA-162075.webp', 'assets/patterns/archive-CMA-162075-thumb.webp', 'be03d714d6a29f5f395f343fdd8a468b65c178972d59e736eb3546d3228f6b07', NULL, 1411, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2001.3', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2001.3', NULL, NULL, 'This luxurious velvet is similar to fabrics worn by Turkish sultans on elaborate ceremonial occasions at the imperial Topkapi Palace in Istanbul during the 1500s. Such bold patterns and high quality served to symbolize the immense power and unfathomable wealth of the Ottoman Empire. The design in this velvet was adapted from Ottoman court art and assembled to create lively contrasts between large motifs seen from a distance—medallion and lattice—and small designs that can only be admired up close—flowers and crowns.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '狮纹 · 团形纹 · 几何纹 波斯与西亚  鸟兽鱼虫 几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-124144', '凤鸟', 'Lampas with phoenixes and palmettes', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","吉祥与礼仪"]', '["Iran, Ilkhanid period"]', 'late 1200s or 1300s', 'lampas: silk and silver thread', 'assets/patterns/archive-CMA-124144.webp', 'assets/patterns/archive-CMA-124144-thumb.webp', '9890ffb5489da4244bb5c73cb45fc4d9e063565a7c019f13eb4c663f540fca6a', NULL, 2677, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1945.14', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1945.14', NULL, NULL, NULL, NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '凤鸟 波斯与西亚  花草藤蔓 鸟兽鱼虫 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-127897', '藤蔓 · 鸟纹 · 刺绣', 'Embroidered fragment with bird among vines', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","边饰与织锦"]', '["Iraq, Baghdad, Seljuq period"]', '1100s', 'plain weave: silk warp and cotton weft (mulham); embroidery, couched and split stitches: silk and metallic thread', 'assets/patterns/archive-CMA-127897.webp', 'assets/patterns/archive-CMA-127897-thumb.webp', '9a6a1c2b18ad9ea9a5e603b6b5a8aae17019208b9d2744557bea217e0875c1ff', NULL, 3400, 1438, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1950.533', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1950.533', NULL, NULL, NULL, NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '藤蔓 · 鸟纹 · 刺绣 波斯与西亚  花草藤蔓 鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-129187', '团形纹 · 织物', 'Silk fragment with roundels of ducks', NULL, '波斯与西亚', 'archive', NULL, '["鸟兽鱼虫","几何与团花","边饰与织锦"]', '["Iran"]', '600s', 'samite: silk', 'assets/patterns/archive-CMA-129187.webp', 'assets/patterns/archive-CMA-129187-thumb.webp', '6183a85ab88ed904d41bf573f9b742e5498b58878ce478d8f508f8f169ab66d1', NULL, 3400, 2591, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1951.88', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1951.88', NULL, NULL, NULL, NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '团形纹 · 织物 波斯与西亚  鸟兽鱼虫 几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95152', '花卉 · 几何纹 · 织物', 'Lampas fragment with blossoms in ogival lattice', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","几何与团花"]', '["Iran, Safavid period (1501–1722)"]', '1600s', 'Silk and silver-metal thread: lampas', 'assets/patterns/archive-CMA-95152.webp', 'assets/patterns/archive-CMA-95152-thumb.webp', 'fdf8f1b81fd730655d5a4548928c98b64234c98b369cf1bedcd193f472677d30', NULL, 2155, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1915.666', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1915.666', NULL, NULL, 'The Iranian love of gardens was celebrated in poetry, yet textile patterns composed of blossoming plants only became fashionable in the 1630s, most likely inspired by European botanical engravings, and they dominated for the next 200 years. This design of composite plants within a curving ogival lattice is typically Iranian in the combination of blossoms with a prominent iris, range of colors, and technique with wefts floating, rather than bound in, across the back. However, the lattice layout framing blossoms were, on a larger scale, a hallmark of Ottoman Turkey.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 几何纹 · 织物 波斯与西亚  花草藤蔓 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95579', '石榴 · 郁金香 · 刺绣', 'Embroidered quilt with pomegranates and tulips', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Turkey"]', '1600s-1700s', 'plain weave: linen; embroidery, running stitch: silk', 'assets/patterns/archive-CMA-95579.webp', 'assets/patterns/archive-CMA-95579-thumb.webp', '3b44a5b41e5f0c126f8add9166e1180f96361f93159a1c7a12a1881c169195de', NULL, 2373, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1300', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1300', NULL, NULL, 'In Turkey, embroidered motifs were often adapted from Ottoman court art, especially luxury silks. Even the same six colors of silk thread were used: crimson or red, blue, green, and brown/black, plus yellow and white that replaced costly gilt- and silver-metal thread. In a typically bold style, pomegranates are framed by serrated leaves. Most of the original dark brown silk thread of the floral stems has disintegrated, revealing black ink outlines on the linen ground.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '石榴 · 郁金香 · 刺绣 波斯与西亚  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95647', '树木 · 刺绣 · 织物', 'Silk hanging with embroidered tree of life', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Turkey, Ottoman period"]', '1800s', 'Silk: plain weave; embroidery, chain stitch', 'assets/patterns/archive-CMA-95647.webp', 'assets/patterns/archive-CMA-95647-thumb.webp', '41501deb4bbbc0cd17e469aee7d2e92572dfa9e5367f6d0f7d62beba014f6348', NULL, 2568, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1358', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1358', NULL, NULL, 'This resplendent tree of life embroidery integrates Turkish traditions with new European styles that became increasingly fashionable during the mid-18th century. The fanciful tree projects lavish bouquets of Turkish flowers while the tree trunk is wrapped with an elaborate European-style bow, as are the meandering vines in the floral border. A professional draftsman drew the pattern with ink on the radiant yellow silk taffeta embroidered with at least 12 vibrant colors in chain stitch. It was most likely made in a professional workshop as a hanging for special occasions, a conspicuous symbol of beauty and wealth.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '树木 · 刺绣 · 织物 波斯与西亚  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-113436', '花卉 · 丝绒 · 织物', 'Velvet panel with four youths smelling flowers', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Iran, Isfahan or Yazd, Safavid period (1501-1722)"]', '1625–50', 'Silk: velvet, brocaded, and pile-warp substitution; gilt- and silver-metal thread', 'assets/patterns/archive-CMA-113436.webp', 'assets/patterns/archive-CMA-113436-thumb.webp', 'd4dbf91925fce30b7bdfa7695d8cad297e3dd2d2b07eec73b7a8c0f64f3900de', NULL, 1557, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1932.42', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1932.42', NULL, NULL, 'A new style depicting single figures with limited modeling and European artistic influence was spearheaded by the Iranian painter Riza ‘Abbasi and adopted by textile designers in sumptuous brocaded velvets. Even with faded colors, this grand length retains ten colors of velvet pile, a feat that Iranian velvet weavers achieved by skillfully replacing colored pile warp during weaving, and thereby creating the most colorful velvets in the world. Elegant youths dominate the simplified outdoor setting here with diminutive cypresses and silver ponds on a ground originally covered with gold thread. Fashionably dressed young men wear wide-brimmed hats, silver robes, stole-like scarves, and knotted sashes that are symbols of status and rank.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 丝绒 · 织物 波斯与西亚  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-118292', '动物 · 人物', 'Lampas with scenes of wild animals', NULL, '波斯与西亚', 'archive', NULL, '["鸟兽鱼虫","人物故事"]', '["Iran, Safavid period (1501–1722)"]', 'late 1500s–early 1600s', 'Silk and gilt-metal thread: lampas, brocaded', 'assets/patterns/archive-CMA-118292.webp', 'assets/patterns/archive-CMA-118292-thumb.webp', '3d8802c62d1125947db91b0816afd1f8c0ef5ba55c5ca83ffb7c679544028b74', NULL, 1868, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1939.38', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1939.38', NULL, NULL, 'Amidst small floral motifs, deer, and antelopes, cheetahs in one row attack deer, while in the alternating row lions seize wild asses.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '动物 · 人物 波斯与西亚  鸟兽鱼虫 人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-120469', '织物', 'Fragment with star pattern and griffins', NULL, '波斯与西亚', 'archive', NULL, '["鸟兽鱼虫","几何与团花"]', '["Iraq or Iran, Buyid period"]', '950–1050', 'silk: plain weave variation with supplementary weft', 'assets/patterns/archive-CMA-120469.webp', 'assets/patterns/archive-CMA-120469-thumb.webp', 'ef2f3803cd0bc4306cab8abac70e3b4d960068759fed12b6f78f82a96e6e9195', NULL, 2632, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1941.292', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1941.292', NULL, NULL, 'This fragment''s design consists of interlaced bands, bordered with inner band of foliate ornament, forming an eight-pointed star with center of floriated cross and flanked in four corner compartments by winged griffins. It was woven in green and white silk. The warp in green silk has two wefts, one of green silk and one of white silk floss for the design.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 波斯与西亚  鸟兽鱼虫 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-123491', '蔷薇 · 织物', 'Fragment of Silk Taffeta with “Rose and Nightingale” Motif', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Iran, Safavid period (1501–1722)"]', '1700s', 'Silk and metallic thread: taffeta, brocaded', 'assets/patterns/archive-CMA-123491.webp', 'assets/patterns/archive-CMA-123491-thumb.webp', '7bd7651ff05b7f574224ea8b321ff936e78a6de9b85ccff6496188807cb5d881', NULL, 3400, 3292, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1943.91', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1943.91', NULL, NULL, 'A luxurious textile like this would have been used for courtly robes or coats in Safavid Iran. The bird-and-flower motif is known as gul-u-bulbul in Persian, meaning “rose and nightingale.” The motif references the poetic image of a nightingale plaintively singing to an indifferent rose as a metaphor for unrequited human love as well as the soul’s desire for mystical union with the divine.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '蔷薇 · 织物 波斯与西亚  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-123707', '几何纹 · 袍服 · 织物', 'Fragment with falconer and attendant in animated lattice, from a robe', NULL, '波斯与西亚', 'archive', NULL, '["几何与团花","边饰与织锦"]', '["Iran, Kashan, Safavid period (1501–1722)"]', 'mid-1500s', 'Silk: velvet, brocaded, pile-warp substitution; gilt-metal thread', 'assets/patterns/archive-CMA-123707.webp', 'assets/patterns/archive-CMA-123707-thumb.webp', 'eab32ec351235ad9636f2eb81023bae601e5bfb3e16c50421a62391ab5f99539', NULL, 2767, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1944.239', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1944.239', NULL, NULL, 'This velvet of Iran’s Safavid period (1501–1722) displaying a falconry scene is celebrated for its refined beauty and meticulous draftsmanship. A falconer and attendant flank a blossoming plant on a golden ground of lobed medallions. Animated vines display leaves bearing lion’s masks and dragons coiled around larger leaves on the crimson ground. Instead of two or three colors of velvet, Iranian weavers wove with as many as 14 colors, the most colorful velvets ever woven.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '几何纹 · 袍服 · 织物 波斯与西亚  几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-127145', '蔷薇 · 织物', 'Section of Silk Fabric with Falconers Amid Rose Bushes', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Iran, Safavid period (1501–1722)"]', 'c. 1675', 'Silk and silver-metal thread: twill weave with complementary and discontinuous weft', 'assets/patterns/archive-CMA-127145.webp', 'assets/patterns/archive-CMA-127145-thumb.webp', '4fa4d44d0571f0dbbc1a064c599bd41b65fda4bf2ad059e244661e292c419a94', NULL, 3400, 3302, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1949.467', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1949.467', NULL, NULL, 'Twill-weave fabrics were used to make garments, especially jackets, during the Safavid period. It was not until after the 1570s that Iranian textiles began to regularly feature the human figure as a decorative motif. Weavers drew from Persian paintings for their subject matter, such as the favorite princely pastime of falconing. Trained falcons were brought on royal hunts to locate and retrieve the prey; close relationships developed between the falcon and the falconer.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '蔷薇 · 织物 波斯与西亚  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-127878', '蔷薇 · 团形纹', 'Samite with roundels of rosettes', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","几何与团花"]', '["Iran"]', '700s-800s', 'samite: silk', 'assets/patterns/archive-CMA-127878.webp', 'assets/patterns/archive-CMA-127878-thumb.webp', '9d4a5b13b2f246c1064acab314401c05dc237f4c4944911ee1b65b1e733768b7', NULL, 1634, 1536, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1950.514', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1950.514', NULL, NULL, 'This is one of a large number of silks woven with geometric designs that have traditionally been attributed to Sogdiana. However, the untwisted warps and light weight of the silk indicate that it was woven farther east in Central Asia where Sogdian influence was strong. Similar geometric patterns occur on clothing depicted in paintings found in the Khotan oasis. That region maintained close cultural and economic ties with Sogdiana. Whether this silk was woven in the Khotan oasis or elsewhere in Central Asia is not known.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '蔷薇 · 团形纹 波斯与西亚  花草藤蔓 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-127889', '织物', 'Quilted cap with star-patterned silk', NULL, '波斯与西亚', 'archive', NULL, '["几何与团花","边饰与织锦"]', '["Iran or Iraq, Buyid or Seljuq period"]', '1000s', 'lampas: silk', 'assets/patterns/archive-CMA-127889.webp', 'assets/patterns/archive-CMA-127889-thumb.webp', '0a612fad21185f5abe9b7a7f0ddfc86f94b7f7394d1c4420a86f1e47e2e613b9', NULL, 3055, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1950.525', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1950.525', NULL, NULL, 'This quilted hat is one of a number of hats that have been recovered from Egyptian graves. It consists of silk sewn to a heavily quilted form, the top part of which is ribbed. The design of the silk is based on an eight-pointed star with paired birds above and stylized palmettes in the interspaces. Such hats were worn with or without a turban by persons of ranks.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 波斯与西亚  几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-128944', '鸟纹', 'Palmettes and Birds from a Tunic or Curtain', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫"]', '["Egypt or Syria, Byzantine or Islamic period"]', '500s–600s', 'Silk; complementary weft-faced twill weave with inner warps (samite)', 'assets/patterns/archive-CMA-128944.webp', 'assets/patterns/archive-CMA-128944-thumb.webp', 'bd6321a5dde88ee4399229144a374b6c8716073d0a6673b3f38259d3c6705bf4', NULL, 1698, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1951.535', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1951.535', NULL, NULL, 'The symmetrical pattern displays back-to-back green parrots with branches in their beaks and two speckled birds perched on the leaves of a long-stemmed palmette.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '鸟纹 波斯与西亚  花草藤蔓 鸟兽鱼虫');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-129191', '花卉 · 织物', 'Silk Fragments with Palmette Blossoms', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Egypt or Syria, Umayyad period (661–750) or Abbasid period (750–1258)"]', '700s', 'Silk: complementary weft-faced twill with inner warps (samit)', 'assets/patterns/archive-CMA-129191.webp', 'assets/patterns/archive-CMA-129191-thumb.webp', '96802b791cdd7b0c46253f9cf7194ba5b1cbbad11aaf160224ed63597dcca8de', NULL, 3400, 2575, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1951.91', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1951.91', NULL, NULL, 'The stunning pattern of palmettes within diamond-shaped compartments is still visible in this rare four-color silk, despite its fragile state. Small human faces within circles appear at the points of the diamonds.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 织物 波斯与西亚  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-129203', '树木 · 团形纹', 'Roundel from a Tunic with Palmette Tree', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","几何与团花"]', '["Egypt or Syria(?)"]', '650–850', 'Silk; complementary weft-faced twill weave with inner warps (samite)', 'assets/patterns/archive-CMA-129203.webp', 'assets/patterns/archive-CMA-129203-thumb.webp', '1aba7538074112a8bd56c2020301f37a2f276918c9af94a7554899122b8d1a55', NULL, 3308, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1952.101', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1952.101', NULL, NULL, 'Four or six squares of this luxurious two-color silk were originally sewn on a linen tunic, two positioned above the hemline in the front and two in the back, and possibly two more at the shoulder. The folded edges are still visible, including a silk sewing thread on the right side. The brittle condition is evident in the numerous crisp breaks.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '树木 · 团形纹 波斯与西亚  花草藤蔓 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-129204', '树木 · 团形纹', 'Roundel with curvilinear palmette tree, from a tunic', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","几何与团花"]', '["Egypt or Syria(?)"]', '600–850', 'Silk; complementary weft-faced twill weave with inner warps (samite)', 'assets/patterns/archive-CMA-129204.webp', 'assets/patterns/archive-CMA-129204-thumb.webp', '8216284081ee1603743f640831cb815c0d1e2375e02072bbe457a41d92227d3f', NULL, 3319, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1952.102', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1952.102', NULL, NULL, 'Originally, roundels like this were cut and sewn onto the front and back of a tunic, probably linen, in Egypt. They belong to a sizeable group of comparable silk decorations found in Akhmim, Egypt. In each roundel, a stylized palmette tree is enclosed within a simplified lotus border that evolved from an ancient Egyptian lotus motif.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '树木 · 团形纹 波斯与西亚  花草藤蔓 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-150875', '树木 · 动物', 'Busts and Animals Under Tree of Life', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫"]', '["Egypt, Islamic period, Abbasid, 8th - 9th century"]', 'late 700s - 800s', 'Plain weave and slit-tapestry weave; undyed linen, dyed wool', 'assets/patterns/archive-CMA-150875.webp', 'assets/patterns/archive-CMA-150875-thumb.webp', 'de121bbcae71224e91e29d67f391be2dc49c6051049668f1ac0da0d62e1f9786', NULL, 3024, 2880, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1982.272', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1982.272', NULL, NULL, 'This elegant symmetrical roundel, probably from a tunic, features a central tree of life with leaves enclosing the bust of a woman on each side. Animals above the bowl and birds toward the top flank the tree which is framed by a sinuous vine.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '树木 · 动物 波斯与西亚  花草藤蔓 鸟兽鱼虫');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-150910', '树木 · 团形纹', 'Roundel from a Tunic with Palmette Tree', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","几何与团花"]', '["Egypt or Syria"]', '700s–800s', 'Silk; complementary weft-faced twill weave with inner warps (samite)', 'assets/patterns/archive-CMA-150910.webp', 'assets/patterns/archive-CMA-150910-thumb.webp', 'f567326fed6918d1273fbcdbe07d22cba49fd4d200f752278daf06d8da5e687f', NULL, 3400, 3361, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1982.296', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1982.296', NULL, NULL, 'Four or six squares of this luxurious two-color silk were originally sewn on a linen tunic, two positioned above the hemline in the front and two in the back, and possibly two more at the shoulder. The folded edges are still visible, including a silk sewing thread on the right side. The brittle condition is evident in the numerous crisp breaks.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '树木 · 团形纹 波斯与西亚  花草藤蔓 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-163101', '花卉 · 织物', 'Floral striped silk on a golden ground', NULL, '波斯与西亚', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Iran, Safavid period (1501–1722)"]', '1600–1650', 'silk, gilt- and silver-metal thread: samite', 'assets/patterns/archive-CMA-163101.webp', 'assets/patterns/archive-CMA-163101-thumb.webp', 'b14198fcc9495c37a48de7956da0fd290febda4326dc8e7c4af4d11ba1f99026', NULL, 1921, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2003.96', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2003.96', NULL, NULL, 'Twelve jewel-like colors of silk thread illustrate the vivacity of colors extolled in Iranian flowers on gilt- and silver-metal thread grounds. In a simplified seminaturalistic style, swaying branches support an exuberant array of blossoms in the Safavid tradition while the botanical accuracy of European prints inspired flora in varied angles and stages of maturity. Although celebrated in Iranian poetry for centuries, flowers were not featured in paintings and textiles until the 1640s, inspired by European herbals. This sturdy silk retains its radiant colors in contrast with many silks that have faded from excessive light exposure, especially the reds and pinks that were dyed with light-sensitive safflower dyestuff.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 织物 波斯与西亚  花草藤蔓 边饰与织锦');
