INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95495', '刺绣', 'Embroidered Table Cover', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Turkey"]', '1700s–1800s', 'Silk and metallic threads on silk tabby ground; embroidery', 'assets/patterns/archive-CMA-95495.webp', 'assets/patterns/archive-CMA-95495-thumb.webp', 'e99ae1582155912dbce8b02aa054f3acbf38df8340c46aa247ebb36c3b8f65a6', NULL, 3219, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1230', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1230', NULL, NULL, 'This embroidered table cover has a central medallion containing geometric motifs, which resemble closely clustered tents and trees. This is surrounded on all sides by individual tents and trees.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '刺绣 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95518', '刺绣', 'Embroidered towel', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Turkey"]', '1800s', 'plain weave: linen; embroidery, double-running stitch: silk, gilt-metal strips and thread', 'assets/patterns/archive-CMA-95518.webp', 'assets/patterns/archive-CMA-95518-thumb.webp', '659b8971fb9bf21df1a4d1bbaab2546d07e83a85915189136883a6e03ae86f40', NULL, 2605, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1251', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1251', NULL, NULL, 'Fine Turkish towels with beautiful floral decoration embroidered across each end are often reversible, and their quality revealed the owner’s wealth and status. A lady was required by Turkish etiquette to use a napkin “daintily over the tips of her fingers,” lest she lose her social standing. Towels were not only essential components of everyday life but also gifts, prizes, and decorations. Embroideries could also depict images of daily life. Colorful tents and buildings in floral landscapes, here enriched with shiny gilt-metal strips, adorn the four sides of a head scarf that was worn either folded or unfolded and fastened beneath the chin. Square embroideries also served to wrap gifts, letters, and objects; the 19th-century English traveler Charles White commented that “no present is made . . . unless folded in a handkerchief, embroidered cloth, or piece of gauze. The more rich the envelope, the higher the compliment to the receiver.”', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '刺绣 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95521', '刺绣', 'Embroidered head scarf', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Turkey"]', '1800s', 'plain weave: linen; embroidery, double-running stitch: silk, gilt-metal strips and thread', 'assets/patterns/archive-CMA-95521.webp', 'assets/patterns/archive-CMA-95521-thumb.webp', '4aa66343195cbb9398214dc30a5e13fae42dbd56cb905b9321f0d7e3c7ca9f0c', NULL, 3400, 3394, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1254', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1254', NULL, NULL, 'The edges of this headscarf are embroidered with landscape: a mosque alternates with a Turkish tent with a flowering plant between. In each corner is a medallion formed by a flowering plant surrounding a Turkish tent.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '刺绣 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95553', '刺绣', 'Embroidered tray cover', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Turkey"]', '1800s', 'plain weave: linen; embroidery, chain stitch: silk and gilt-metal thread', 'assets/patterns/archive-CMA-95553.webp', 'assets/patterns/archive-CMA-95553-thumb.webp', 'f1d6ff9e4f98f9421aa99e33854890944657a6721f9432e83357381241b924dc', NULL, 3354, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1276', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1276', NULL, NULL, 'Elaborately embellished round embroideries often covered the metal trays that accompanied traditionally gracious Turkish hospitality and cuisine. Here, exuberant floral displays and garlands bearing large blossoms with shaded petals enrich the circular designs that feature extravagant gilt-metal thread and many lush colors of silk thread. The embroidered stitches almost conceal the linen ground in a spectacular tour-de-force.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '刺绣 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95565', '刺绣', 'Gold-Thread Embroidered Cover', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Turkey, Ottoman period"]', '1800s', 'silk, gilt-metal, silver-metal, paper, cotton padding; satin weave, embroidery', 'assets/patterns/archive-CMA-95565.webp', 'assets/patterns/archive-CMA-95565-thumb.webp', '41935666244f536c273f11e652915113b4813ee6257bab5b2c064a4e94bc62cd', NULL, 3400, 2750, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1288', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1288', NULL, NULL, 'Silk fabrics embroidered with gold thread appear to have ranked second only to gemstone-embellished textiles. Both were more prestigious than brocaded silks, which are more numerous. Embroidery was an essential component of daily life because it served innumerable covering functions. In this vibrant example with European influence, blossoming plants and foliate motifs embellish the field and border. Gold, silver, and silk thread cover paper templates which are secured with thread raised from underneath, called couching. The padded blossoms are covered with several types of silver thread for dazzling effects in a style popular during the 18th and 19th centuries at the imperial Topkapi Palace in Istanbul as well as provincial centers.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '刺绣 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95575', '织物', 'Tent Wall Panel(?)', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Iran, Rasht, Qajar period (1779-1925)"]', '1800s', 'Wool: inlaid work; silk: embroidery, chain stitch', 'assets/patterns/archive-CMA-95575.webp', 'assets/patterns/archive-CMA-95575-thumb.webp', '2b48121e7f7124dc9f3fe46b098d2d261d1144649c0edaf10ae1025b7bfd02f9', NULL, 2383, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1297', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1297', NULL, NULL, 'Elaborate arched panels with multiple borders similar to this textile formed the mosaic-like interior walls of imperial tents. Here, the field is dominated by a richly decorated cypress tree above peacocks and dragon heads on an ornate foliate ground. We look upon the gardenscape through a niche (mihrab) formed by this foliage. Bright white silk “pearl” outlines, vines, and ringlets in chain-stitch embroidery enliven the pattern on contrasting colors of fulled wool. Internationally fashionable botehs, or paisleys, decorate the outer red borders.This technique has been referred to by many different names including: Rasht work, Resht work, Rashti-duzi, Rachti-douzi, embroidery applique, mosaic embroidery, piecework, patchwork, embroidery brocade, and inlaid patchwork. Many of these terms are to various degrees inaccurate descriptions of this technique. Perhaps the most practical term is Rasht work, named for the town in Iran where the technique was popularized. It begins as a ground of felted plain weave wool. Desired shapes are then punched out of the ground with a metal die and hammer. The same is done with wool of an alternating color. The edges of the different cut pieces are then embroidered together into various designs using a silk chain stitch (golab-duzi). Although this piecework technique was recorded in Iran in the 1670s, most examples survive from the 19th century, when foreigners praised them as “really [the] most beautiful embroidery.” The technique appears in furnishing fabrics, and horse covers, as well as imperial portraits, including one depicting the Qajar monarch Fath ‘Ali Shah, who ruled in 1797–1837. Sometime after leaving the workshop this panel experienced moth damage; small patches can be seen throughout.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95580', '刺绣', 'Embroidered Cover or Curtain', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Turkey, 17th-18th century"]', '17th-18th century', 'embroidery: silk on linen tabby ground', 'assets/patterns/archive-CMA-95580.webp', 'assets/patterns/archive-CMA-95580-thumb.webp', '089ed62c60414a3b8dbd7298f304bc30622ae1bd4f8d3859e11cefebdfc32c88', NULL, 2426, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1301', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1301', NULL, NULL, 'This exuberant pattern of spiraling roundels enlivens a ground of isolated vegetation, despite disintegrated dark brown–black silk thread outlines. Professional draftsmen would have drawn the pattern in ink on the reverse side of several loosely attached, plain linen cloths. They were separated for embroiderers to follow and then reassembled; frequently, the designs do not match perfectly at the seams.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '刺绣 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95721', '团形纹', 'Lampas with roundels of the image of Christ in benedictory pose', NULL, '波斯与西亚', 'archive', NULL, '["几何与团花"]', '["Turkey, Bursa, Ottoman period"]', '1550–1650', 'Silk and gilt-metal thread: lampas', 'assets/patterns/archive-CMA-95721.webp', 'assets/patterns/archive-CMA-95721-thumb.webp', '2f21d44e310827f9166f3c3c270cb473f352f8042d6d4881d19696bccf0460d8', NULL, 3119, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1423', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1423', NULL, NULL, 'Ottoman manufacturers also wove luxury silks with Christian images for the largest markets outside of the reigning sultans, whose need for luxury fabrics was voracious, targeting the Balkans, Eastern Europe, and the state of Muscovy (Moscow), which lacked silk industries. Worn as majestic church vestments, they were prized signifiers of the power and wealth of the Eastern Orthodox church. Christian imagery is often displayed in small medallion patterns, as seen here, woven in the standard Ottoman lampas technique. In this highest grade lampas with extensive gilt-metal thread, small medallions enclose half-length images of Christ in a benedictory pose alternating with crosses. The abbreviated inscription in the roundel, IC XC, translates as "Jesus Christ."', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '团形纹 波斯与西亚  几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95793', '边饰与织锦', 'Turban cover', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Turkey"]', '1700s-early 1800s', 'plain weave: silk; embroidery, double-running stitch: silk, gilt- and silver-metal thread', 'assets/patterns/archive-CMA-95793.webp', 'assets/patterns/archive-CMA-95793-thumb.webp', '8e1fbef40812de2057606c481ad6476804450cd6a6881ea8a81a2f6ce8f713be', NULL, 3400, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1481', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1481', NULL, NULL, 'This exceptionally fine, diaphanous silk turban cover represents the highest quality professional embroidery. Shiny gilt- and silver-metal thread and at least ten colors of silk thread—including newly fashionable pastel tones—create three-dimensional blossoms in the central roundel and multicolored cornucopias on the lavender silk ground. In Turkey, square cloths embroidered with one or two concentric circles in the center of floral fields were generally used to cover stored turbans, a function well served by this elegant cover with weighted golden borders.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95941', '几何纹', 'Ogival lattice with horizontal design', NULL, '波斯与西亚', 'archive', NULL, '["几何与团花"]', '["Turkey, Bursa"]', '1600–1650', 'Silk and gilt-metal thread: lampas weave', 'assets/patterns/archive-CMA-95941.webp', 'assets/patterns/archive-CMA-95941-thumb.webp', 'adf79360316c99c4dbd187718572c6f306f13b0913ea14f22a07266eed01f476', NULL, 1647, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1679', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1679', NULL, NULL, 'There is a pomegranate design in each ogee (pointed arch) of this silk brocade fragment. The pomegranate is a small tree originating in Persia (today’s Iran) bearing fruit of deep red flesh filled with hundreds of seeds. The pomegranate has been revered as a symbol for health and fertility by many civilizations. In Islam the pomegranate is associated with paradise as described in the Qur’an.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '几何纹 波斯与西亚  几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-98504', '丝绒', 'Velvet with gold discs', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Iran, probably Tabriz, Ilkhanid period"]', 'late 1200s or earlier', 'silk, gilt-metal thread; brocaded velvet', 'assets/patterns/archive-CMA-98504.webp', 'assets/patterns/archive-CMA-98504-thumb.webp', 'b0a89fd2de50adbf9d79bc3c095d0fa2b0c2fce489195373b7db186cb9297f0d', NULL, 3400, 2392, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1918.225', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1918.225', NULL, NULL, 'Silk velvet with rich pile is one of the most opulent and prestigious fabrics, especially when embellished with gold thread. This is one of the earliest known velvets. A 1295 inventory of Pope Boniface VIII includes "a piece of red Tartar velvet with gold discs," which probably refers to this velvet pattern. It is attributed to Iran, possibly in Tabriz where Italian agents resided and could have provided the transfer of silk-velvet technology to Italy. Although the origin of velvet is uncertain, silk velvet with an extra silk pile warp was probably developed in a silk weaving country such as Iran. Inventive Iranian weavers may have developed it during the 1200s or earlier; they are acclaimed for producing the most colorful velvets ever during the 1500s and 1600s.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '丝绒 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-108512', '织物', 'Textile with field of poppies on a golden ground', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Iran, Safavid period (1501–1722)"]', '1600–1750', 'silk and gilt-metal thread: twill weave with supplementary weft, stamped', 'assets/patterns/archive-CMA-108512.webp', 'assets/patterns/archive-CMA-108512-thumb.webp', 'f21a87aa8fbb371c395b8246cef65f989ff1eee816750e470b2268d75186786b', NULL, 2854, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1926.22', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1926.22', NULL, NULL, 'Trade in textiles flourished between India and Iran. Courtly consumers from the neighboring Mughal and Safavid dynasties admired the products of both regions. The subtle chevrons set off rows of poppies that sway in alternating directions, lending a gentle liveliness to the overall pattern. Peach and green silk threads interlace to create each poppy in a technique that uses discontinuous wefts and allows for a smooth surface finish to this lightweight textile.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-108857', '地毯 · 织物', 'Royal Carpet with Silk and Metal Thread', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Iran, Isfahan, Safavid period (1501-1722)"]', '1600–1625', 'Cotton: warp; cotton and silk: wefts; silk: pile, asymmetrical knot; gilt- and silver-metal thread: brocaded', 'assets/patterns/archive-CMA-108857.webp', 'assets/patterns/archive-CMA-108857-thumb.webp', '89e5bf57933287b90e1bd838972aefd74cddb16de6a23619ef8aef6bca066b12', NULL, 2239, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1926.533', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1926.533', NULL, NULL, 'The Safavid dynasty was the greatest dynasty from Iran in the Islamic period. Similarly, woven textiles and carpets from this period are some of the best produced in the region. Royal workshops produced luxurious textiles, like this one, to furnish the royal court. Expertly woven silks were highly prized by the Iranian elite but were also produced for export to the European aristocracy.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '地毯 · 织物 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-116641', '织物', 'Silk fragment', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Egypt or Iran, Ayyubid period, 1100s"]', '1100s', 'lampas: silk', 'assets/patterns/archive-CMA-116641.webp', 'assets/patterns/archive-CMA-116641-thumb.webp', '376670dffba3e3c9e304aed5031200f8550b4e93cfe6fa35ba3b4112bc6aa5f8', NULL, 2285, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1937.23', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1937.23', NULL, NULL, 'Silk of double cloth weave with design of lengthwise bands of ornament between bands of inscription.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-117656', '孔雀 · 织物', 'Fragment with peacocks and inscription', NULL, '波斯与西亚', 'archive', NULL, '["鸟兽鱼虫"]', '["Iraq, probably Baghdad, Seljuq period"]', '1000–1100s', 'Silk warp and cotton weft (mulham): plain weave; silk, gilt, and silver thread: embroidery, couched and split stitches', 'assets/patterns/archive-CMA-117656.webp', 'assets/patterns/archive-CMA-117656-thumb.webp', '726ca823e90503f43ad97698c0b0a008a7289ac2fe4457d468344e502c3d32e9', NULL, 3400, 2887, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1938.300', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1938.300', NULL, NULL, 'One of the stories in "The Thousand and One Nights" is of a slave girl named Zumurud who lived in Khurasan and embroidered curtains with designs of animals and birds in colored silk and gold threads. Sumptuous embroideries were not only commissioned by rulers, caliphs, and court officials but also widely exported. Today, less than a dozen fragments of these rich embroideries survive. All are worked on "mulham," a fabric having silk warps and cotton wefts that was a specialty of Iran and Iraq. With the exception of the Cleveland Museum of Art''s fragment CMA 1952.257, which was found in Baghdad, all of the known examples were preserved until the 1900s in Egyptian graves and refuse heaps.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '孔雀 · 织物 波斯与西亚  鸟兽鱼虫');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-118426', '织物', 'Fragment', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Iran or Iraq"]', '1000s–1100s', 'Silk: soumak, or twisted tapestry', 'assets/patterns/archive-CMA-118426.webp', 'assets/patterns/archive-CMA-118426-thumb.webp', '1ab8ae40380285ac00434d7aaa85a5a33f57169754920656e7141356f71b4a2f', NULL, 2619, 3000, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1939.47', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1939.47', NULL, NULL, 'The fragment preserves a winged quadruped in blue on a gray-beige background with the details of the animal in the ground color. Below the animal are foliate sprigs in blue.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-118469', '织物', 'Silk Decorative Tunic Band with a Hunter', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Egypt or Syria, Umayyad period (661–750) or Abbasid period (750–1258)"]', '700s', 'Silk: complementary weft-faced twill with inner warps (samit)', 'assets/patterns/archive-CMA-118469.webp', 'assets/patterns/archive-CMA-118469-thumb.webp', 'f4eae89414365b7461a51365a794b91097cf138d299d985429468048046b5d41', NULL, 1099, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1939.505', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1939.505', NULL, NULL, 'This prestigious silk band displays a stylized palmette leaf above a hunter who holds a sword and a shield and pursues a lion and a rabbit. Another fragment with Arabic script indicates Islamic manufacture. Green and ivory silk wefts (horizontal threads) dominate, interlaced by warps (vertical threads) in a diagonal twill weave. A second inner warp does not come to the surface. Such compound structures were woven on large looms with automatic pattern repetition, called drawlooms.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-118470', '孔雀 · 织物', 'Fragment with peacocks in ogival pattern', NULL, '波斯与西亚', 'archive', NULL, '["鸟兽鱼虫"]', '["Iran or Iraq, possibly Rayy"]', '1004–1260 (radiocarbon date, 95% probability)', 'Silk: plain weave with supplementary weft', 'assets/patterns/archive-CMA-118470.webp', 'assets/patterns/archive-CMA-118470-thumb.webp', '83d2d4e69fc1e44098ac5426f1e5266ab39c637fdfa82bd474e42cca3d9718e2', NULL, 3047, 3112, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1939.506', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1939.506', NULL, NULL, 'Neither the design nor the technique of this silk provides clues to whether it was woven in Iran or Syria. As Iran and Iraq fell to the Mongol armies during the second quarter of the 1200s, many artisans fled to Syria, taking with them the techniques and patterns with which they were familiar. The inscriptions are purely decorative.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '孔雀 · 织物 波斯与西亚  鸟兽鱼虫');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-123061', '织锦 · 丝绒', 'Brocaded velvet with chintamani design', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Turkey, Bursa"]', 'late 1400s', 'velvet, brocaded: silk and silver-metal thread', 'assets/patterns/archive-CMA-123061.webp', 'assets/patterns/archive-CMA-123061-thumb.webp', 'ba0e27ea81eb54c8f5fe84b0ba2163ec5117ca655ac1f98ede501dabc6ec40cc', NULL, 1449, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1943.313', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1943.313', NULL, NULL, 'This early Ottoman brocaded velvet was woven in an imperial workshop in the prosperous city of Bursa, the silk capital and major commercial center of the Ottoman Empire. It has exceptionally rich crimson silk pile, almost twice as dense as later monochrome velvets. The brocaded pattern of three balls and paired wavy bands is known as chintamani, derived from the Sanskrit word for a popular Buddhist motif, “the three jewels,” shown surrounded by flames or foliage in Buddhist art across Asia. Based on the high frequency of its use in art for the Islamic court of the Ottoman Turks, it appears to have been a favored motif and possibly even an unofficial imperial emblem.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织锦 · 丝绒 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-124013', '边饰与织锦', 'Khusrau Surprising Shirin While Bathing', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Iran, Kashan, Safavid period (1501-1722)"]', '1550–99', 'Silk: velvet, pile-warp substitution', 'assets/patterns/archive-CMA-124013.webp', 'assets/patterns/archive-CMA-124013-thumb.webp', 'bfdd6e6ce092151228520fd2258c1ee70178793131c7e3e1b81372aa72c73235', NULL, 2694, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1944.499', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1944.499', NULL, NULL, 'These velvet fragments depict an episode from the Khamsa (Quintet) of Nizami (1141–1209), in which the lovers Khusrau and Shirin first see each other. A pre-Islamic king of Iran, Khusrau has fallen in love with Shirin after seeing her portrait and is traveling to meet her when he happens across her bathing in a stream. Not yet realizing that she is Shirin, Khusrau is transfixed by the woman’s beauty and covets both her and her magnificent black horse. The horse’s mane is just visible here, and she has placed her crown and tunic atop a branch.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-124366', '织物', 'Fragment', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Iran or Iraq ?, Mongol period, 14th century"]', '1300s', 'Silk and gold thread; lampas', 'assets/patterns/archive-CMA-124366.webp', 'assets/patterns/archive-CMA-124366-thumb.webp', 'cb292aee61b1ea70caccb8b9c1f4faec7b0b4de7292488731f6a60647f085878', NULL, 3000, 1923, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1945.34', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1945.34', NULL, NULL, 'On this textile fragment, a pair of phoenixes, affronted and nonregardant, flanking a floral motif are framed in an ogive formed by a vine with trifoliate leaves. This, in turn, is framed with a scrolling vine with leaves and pairs of small birds. The design is in Cyprian gold on a coral ground.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-125229', '几何与团花', 'Square Ornament from a Tunic', NULL, '波斯与西亚', 'archive', NULL, '["几何与团花"]', '["Egypt or Syria, Umayyad period (661–750) or Abbasid period (750–1258)"]', '700s', 'Silk; complementary weft-faced twill weave with inner warps (samite)', 'assets/patterns/archive-CMA-125229.webp', 'assets/patterns/archive-CMA-125229-thumb.webp', '4d4d3491c112018e808e4abc1a776c181ffbfb389064caf9e9ccf3ed6a828ae1', NULL, 3400, 3318, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1947.192', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1947.192', NULL, NULL, 'The folded edges on all four sides of this luxury silk fragment indicate that it decorated a unisex linen tunic. The symmetrical deer with suckling fawn flanking a simplified central tree of life continues an ancient theme in a naturalistic style. The roundel is connected on all four sides and displays heart-shaped floral borders. This fragment is said to have been found in Akhmim, Egypt, south of Cairo, where, during the 1880s, numerous related silk fragments were excavated.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '几何与团花 波斯与西亚  几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-125230', '织物', 'Silk Sleeve Decoration with Hunters', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Egypt or Syria, Umayyad period (661–750) or Abbasid period (750–1258)"]', '700s', 'Silk: complementary weft-faced twill with inner warps (samit)', 'assets/patterns/archive-CMA-125230.webp', 'assets/patterns/archive-CMA-125230-thumb.webp', 'be27acf902d7435f614096faf5f16519193bed21011da6d2088ae66374e34335', NULL, 2599, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1947.193', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1947.193', NULL, NULL, 'This silk sleeve blends technical and stylistic elements that occurred in early Islamic art. The sides of the sleeve are decorated with a lotus flower design, an ancient Egyptian motif that was absorbed into Hellenistic and Byzantine art. The upper panel displays a large medallion composed of leaves and palmettes, common vegetal motifs in Islamic art of this period. Below, the mace-wielding horseman is identified in Coptic inscriptions as Joseph, father of Jesus and saint within the Coptic faith. The image is likely derived from the Byzantine representation of the victorious emperor.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-127871', '织物', 'Hanging fragment with boar head', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Iran"]', '600s–early 700s', 'Wool and linen: tapestry weave', 'assets/patterns/archive-CMA-127871.webp', 'assets/patterns/archive-CMA-127871-thumb.webp', '05b40731741412b2cd1c21691ab9e01f95fd50689a3aff06135981eb34c35b28', NULL, 3000, 2427, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1950.509', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1950.509', NULL, NULL, 'This fragment preserves parts of two distinct designs. In the lower section, a boar''s head is framed by a pearl roundel; to left and right are fragments of two other roundels, and in the spandrels are segments of stylized flowers. In the field above are four feet of what must have been a rather large-scale horse standing in a meadow of flowers of which only fragments remain. A fifth hoof, turned in the opposite direction, indicates that originally the composition included a pair of horses addorsed. A double row of pearls occupies the spaces beneath the horses'' feet, and a narrow plain band separates this field from the one below.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-127890', '织物', 'Fragment with jewel-like silk', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Iraq, probably Baghdad"]', '800s', 'Silk: plain weave, brocaded', 'assets/patterns/archive-CMA-127890.webp', 'assets/patterns/archive-CMA-127890-thumb.webp', '8f410885e1c4fe4d4624ce2df7c906c831141c44fab12fce1efff1dacd2028a3', NULL, 1686, 2275, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1950.526', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1950.526', NULL, NULL, 'This fragment is brocaded in a jewel-toned silks: red, rose, turquoise, salmon pink, pale pink, golden tan, green, dark blue, and dark brown. Flat strips of gold foil were wound on tan silk strands to create gold thread adding to the luxuriousness of the brocade.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-127915', '织物', 'Fragment with tripartite band', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Iran or Iraq, Seljuq period"]', '1000s–1100s', 'Silk warp and cotton weft (mulham): plain weave; gold leaf and ink', 'assets/patterns/archive-CMA-127915.webp', 'assets/patterns/archive-CMA-127915-thumb.webp', 'ca238b54ea16fefcac1c2c3bc02ae975a5a5790426cf9a3d2b0a7a878e895917', NULL, 3400, 2242, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1950.551', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1950.551', NULL, NULL, 'This three-part band consists of two opposing bands of inscriptions flanking an ornamental band of winged griffins within eight-pointed stars, separated by various creatures—a rabbit, a cheetah, and possibly a sphinx. The inscriptions in the band are in simple Kufic against a floriated background. They, as well as the single band of inscription above, repeat in various combinations as benedictions, "endurance and good fortune, blessing, peace." The patches forming the background are gold, the design is drawn in black, and the background of only one star is blue.This textile probably reflects the international fashion or may have been made for export to Egypt, where this fragment likely survived.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-129206', '团形纹', 'Roundel with Amazons, from a tunic', NULL, '波斯与西亚', 'archive', NULL, '["几何与团花"]', '["Egypt or Syria(?)"]', '600s–800s', 'samite: silk', 'assets/patterns/archive-CMA-129206.webp', 'assets/patterns/archive-CMA-129206-thumb.webp', '51dc39a4147255094ab27e37036498b3c96ab72b3ed1f5b2ff155a216cb9fe3f', NULL, 2400, 2296, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1952.104', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1952.104', NULL, NULL, 'Within a roundel are a pair of mounted Amazons (women warriors) shooting backward at lions, which attack their running horses. The roundel frame is filled with stylized floral motifs and is bordered on the inside by a band of tiny hearts.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '团形纹 波斯与西亚  几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-130408', '人物故事', 'Lampas with dancers and musicians', NULL, '波斯与西亚', 'archive', NULL, '["人物故事"]', '["Iran, Safavid period (1501–1722)"]', '1600–1650', 'silk and silver-metal thread: lampas, brocaded', 'assets/patterns/archive-CMA-130408.webp', 'assets/patterns/archive-CMA-130408-thumb.webp', '3e0477b1ceb5b44d1bbb416a549a85fdd32e99c3e2e27ae53bb556e717b7aaa3', NULL, 1804, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1953.17', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1953.17', NULL, NULL, 'This sturdy silk with extensive silver-metal thread displays a dancer and musicians in varied Iranian and European attire, including curved-brim Portuguese or Dutch hats, that reflect the cosmopolitanism initiated by Shah ‘Abbas (reigned 1587–1629). The figures in this landscape are about the same size and equally spaced with minimal interaction, yet they create movement that disguises the repeat of the design. Although the history of textiles is replete with anonymity, signed silks were woven in Iran around 1600. The name of the presumed designer, Abdallah, appears in cursive script on the tambourines. The rise of signed textiles followed a shift away from royal manuscript patronage, causing artists to sign their work to sell in the marketplace. European influence, a new distinguishing hallmark, was transmitted through engravings by traveling European artists.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物故事 波斯与西亚  人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-130611', '人物故事', 'Nude Female Dancers from a Tunic', NULL, '波斯与西亚', 'archive', NULL, '["人物故事"]', '["Egypt or Syria, Umayyad period (661–750) or Abbasid period (750–1258)"]', '700s', 'Silk; complementary weft-faced twill weave with inner warps (samite)', 'assets/patterns/archive-CMA-130611.webp', 'assets/patterns/archive-CMA-130611-thumb.webp', 'acd8b974198186acbb3221ac475261a6d649149efbc2a59c02adf0f8bb8368b4', NULL, 3105, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1953.332', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1953.332', NULL, NULL, 'Voluptuous females in sheer attire were not only depicted in contemporary wall paintings but also woven in lengths of silk fabric that were cut into squares to decorate linen tunics. These symmetrical female dancers, with anklets and long scarves draped around their shoulders, hold branches and pomegranates.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物故事 波斯与西亚  人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-134192', '刺绣', 'Embroidered Sash (Uckur)', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Turkey"]', '1700s', 'embroidery: silk and silver filé on linen tabby ground', 'assets/patterns/archive-CMA-134192.webp', 'assets/patterns/archive-CMA-134192-thumb.webp', '48c5726fae1a37627649a604570ab76f952b312b0868b5a1b9271cb59fa802e2', NULL, 2231, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1956.679', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1956.679', NULL, NULL, 'Each end of the sash is embroidered with a single motif of large-scale flowering plants. Below the main motif is a stylized foliate device forming a narrow border.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '刺绣 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-135577', '织物', 'Fragment, probably from a large hanging', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Iran or Iraq"]', '900s–1000s', 'Wool: tapestry weave', 'assets/patterns/archive-CMA-135577.webp', 'assets/patterns/archive-CMA-135577-thumb.webp', '5e3e7afce21186075bf2db7cbe6aaf63cd9a09914004e971a05da30873681e6a', NULL, 3400, 3130, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1959.122', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1959.122', NULL, NULL, 'This fragment preserves the forepaws of what must have been a very large-scale lion. Beneath it is a bit of another motif which can no longer be identified. The ground is a soft grayish-blue, the design pale yellow and white, and the leaflike projections on the lower motif are aqua. The design is oriented in the warp direction.The technique is the usual tapestry weave with slit and dovetail joins. The weave is very fine; the wefts are tightly beaten up. There is limited use of eccentric weaving.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-136408', '边饰与织锦', 'Decorated Band from a Tunic or Curtain', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Egypt, late Byzantine or early Islamic period, 7th Century"]', '600s', 'tapestry weave with supplementary weft wrapping; undyed linen and dyed wool', 'assets/patterns/archive-CMA-136408.webp', 'assets/patterns/archive-CMA-136408-thumb.webp', '6773d000534bb4469cdf65822e8aa14730cca645c9c392cc769148b28bc9bcaa', NULL, 2048, 795, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1960.275', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1960.275', NULL, NULL, 'This colorful and finely woven band combines motifs of the Byzantine period, such as the bird and flanking palmettes (fan-shaped leaves), with new fashions that emerged with the spread of Islam, such as the roundel with a pearl border.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-137340', '地毯', 'Carpet', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Iran, Herat, 16th century"]', '1500s', 'senna knot: wool and cotton', 'assets/patterns/archive-CMA-137340.webp', 'assets/patterns/archive-CMA-137340-thumb.webp', '7a4c2dfeedc93a5c5d1d4d1cc147b99225ffa463aaee9688e119b7e7b5ab782c', NULL, 3400, 1425, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1962.263', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1962.263', NULL, NULL, 'The Mughals, with their nomadic Central Asian roots, were constantly on the move. They were adept at transporting the trappings of their residences and bases of operation from place to place. Fine carpets and canopies demarcated places of importance, and could be rolled up and moved when the ruler was ready to consolidate his power at a new location. When they settled in stone palaces in India, the interiors were covered with carpets, lending a warmth to the spaces that cannot be felt at the sites today. This carpet is of the type that the Mughals would have acquired for their residences. Mughal paintings are filled with depictions of carpets and textiles, many ornamented, like this one, with delicate and complex palmette-dominated arabesque patterns that evoke a paradisiacal setting.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '地毯 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-142301', '地毯 · 织物', 'Two-faced Carpet Fragment', NULL, '波斯与西亚', 'archive', NULL, '["边饰与织锦"]', '["Iran ?, Seljuq period (1037–1194)"]', '1100s', 'senna knot', 'assets/patterns/archive-CMA-142301.webp', 'assets/patterns/archive-CMA-142301-thumb.webp', '5680a313e65c233216c51b60acb22c9dde4276bd52db59d7009267a7fcf9c2e5', NULL, 1623, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1966.132', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1966.132', NULL, NULL, 'This fragment preserves portions of designs of two faces of a carpet. One design depicts a stylized tulip with part of its mirror image. The opposite side depicts a pair of winged ibexes oriented at right angles to the "tulip" design.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '地毯 · 织物 波斯与西亚  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-143802', '织物', 'Fragment with Rows of Confronted Rabbits', NULL, '波斯与西亚', 'archive', NULL, '["鸟兽鱼虫"]', '["Iran or Iraq ?, Buyid period, 10th century"]', '900s', 'Silk: compound twill', 'assets/patterns/archive-CMA-143802.webp', 'assets/patterns/archive-CMA-143802-thumb.webp', '68dc04fa297ae50c43d0dcc40a9d4e54e20880bcf98747c5bc89e745f1dc488a', NULL, 3400, 2386, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1968.229', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1968.229', NULL, NULL, 'This fragment includes pairs of confronted rabbits(?) arranged in staggered horizontal rows. The right border preserves parts of a selvage and an inscription, which is orthograde to the right and retrograde to the left. The rabbits are woven in dark blue on a tan ground; the inscription is tan on a dark blue ground.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 波斯与西亚  鸟兽鱼虫');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-149027', '几何与团花', 'Star and Cross Pattern from a Tomb Cover(?)', NULL, '波斯与西亚', 'archive', NULL, '["几何与团花"]', '["Byzantium, Islamic or Byzantine periods, 9th -10th Century"]', '800s–900s', 'complementary weft-faced plain weave with inner warps (samit); silk', 'assets/patterns/archive-CMA-149027.webp', 'assets/patterns/archive-CMA-149027-thumb.webp', 'e9dd5fcb728993e9089ad5ca92580dd229d8332b04bfdb565a955d7a97f227d2', NULL, 3400, 1323, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1977.17', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1977.17', NULL, NULL, 'This fragment is one of several that may have come from a tomb in the Caucasus (the region between the Black and Caspian seas). The design displays rows of eight-pointed stars, here with a rooster on a blue ground, alternating with striped pointed crosses.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '几何与团花 波斯与西亚  几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-150576', '马纹', 'Hunters on Horseback', NULL, '波斯与西亚', 'archive', NULL, '["鸟兽鱼虫"]', '["Egypt, Islamic Abbasid period, late 8th to 9th century"]', 'late 700s–800s', 'Plain weave and tapestry weave; undyed linen, dyed wool', 'assets/patterns/archive-CMA-150576.webp', 'assets/patterns/archive-CMA-150576-thumb.webp', '07ed94a9e477abbf8a348cc2cae766e2b17a11a591b14da1685c6ac7f81ee557', NULL, 1982, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1982.102', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1982.102', NULL, NULL, 'The Byzantine theme of the hunt is depicted with archers on horseback. They face each other because the design was based on costlier Byzantine silks with mirror-image symmetry.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '马纹 波斯与西亚  鸟兽鱼虫');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-157403', '莲花 · 狮纹 · 团形纹', 'Fragment with geese circling lotus medallions', NULL, '南亚织绣', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","几何与团花","吉祥与礼仪"]', '["India"]', '1400s', 'plain weave: cotton, stamped mordant resist and dyed', 'assets/patterns/archive-CMA-157403.webp', 'assets/patterns/archive-CMA-157403-thumb.webp', 'ba28ba960f720f7a12c6346c1e52f88be01db78a3d920ae7ebe768e8ef877e66', NULL, 3400, 1793, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1994.26', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1994.26', NULL, NULL, NULL, NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '莲花 · 狮纹 · 团形纹 南亚织绣  花草藤蔓 鸟兽鱼虫 几何与团花 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95648', '花卉 · 狮纹 · 团形纹', 'Spread with floral medallion pattern', NULL, '南亚织绣', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","几何与团花"]', '["Mughal India, Deccan, probably Goa"]', '1700s', 'Cotton: plain weave, quilted; silk and gilt-metal thread: embroidery, couched laid work', 'assets/patterns/archive-CMA-95648.webp', 'assets/patterns/archive-CMA-95648-thumb.webp', 'edc6b0bd838ca430844b1332761127c4f87cc9a9bdfd2937a626f73bd5064740', NULL, 2593, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1359', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1359', NULL, NULL, 'This textile could have been used as a covering for seating on the floor or as a bedspread in either an Indian or European setting. In any case, it was not meant to be walked on. Its material and imagery testify to flourishing international relationships. The arabesque designs, consisting of swirling vines with large and small flowers, recall a radiant paradise and have roots in Persian, Chinese, and Mediterranean sources. The use of gold-wrapped thread had been widespread in Spain and Portugal before it was adopted in India, probably first in Goa, a Portuguese colony on the southwestern coast of India from 1510 to 1961. The vibrant colors are distinctive to this region of India.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 狮纹 · 团形纹 南亚织绣  花草藤蔓 鸟兽鱼虫 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-164834', '动物 · 人物 · 披肩', 'Long shawl with woven figures and animals', NULL, '南亚织绣', 'archive', NULL, '["鸟兽鱼虫","人物故事","边饰与织锦"]', '["India, Kashmir"]', 'c. 1885', '2/2 twill tapestry weave, double interlocked and pieced: wool (possibly pashmina)', 'assets/patterns/archive-CMA-164834.webp', 'assets/patterns/archive-CMA-164834-thumb.webp', 'd5a0fa574a543352838893027a31140855b18ac01edb35165c6efc033656347a', NULL, 3400, 1527, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2006.200', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2006.200', NULL, NULL, 'Kashmir shawls from India were status symbols in Europe during the 1800s, and few are as rare as this woven example. Over 200 human figures take part in drinking, smoking, dancing, and falconry in the Indian princely scenes that enliven the shawl’s borders and four dark stripes. The stripes alternate with large elongated boteh, or paisley, motifs that intertwine with blossoming stems in a European style adapted by Kashmiri textile artists. This extraordinary woven shawl was probably made to dazzle the jury at one of the European expositions of industrial products, as almost all other figural shawls were embroidered. It was woven in many pieces and then skillfully joined with colorful harlequin end borders.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '动物 · 人物 · 披肩 南亚织绣  鸟兽鱼虫 人物故事 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-108533', '披肩', 'Square Shawl ("amli")', NULL, '南亚织绣', 'archive', NULL, '["几何与团花","边饰与织锦"]', '["India, Kashmir"]', 'mid-1800s', 'Wool: embroidery (large-pieced areas)', 'assets/patterns/archive-CMA-108533.webp', 'assets/patterns/archive-CMA-108533-thumb.webp', 'd2219169b85a2d9776e56193041a00a791ab4b2a3e3e2d9e5902707dbafb6922', NULL, 2953, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1926.239', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1926.239', NULL, NULL, 'The central white medallion radiates into a swirling pattern of rosettes and teardrop-shaped “tree-of-life” motifs, also known as paisley, that spread over the entire surface. In the border is an undulating vine and a row of gate-like elements filled with individual trees. Kashmiri shawls were signs of high social status in India. Beginning in the late 1700s, the shawls were also coveted throughout Europe and America, until they began to fall out of fashion during the 1870s.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '披肩 南亚织绣  几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-119769', '披肩', 'Square Shawl', NULL, '南亚织绣', 'archive', NULL, '["几何与团花","边饰与织锦"]', '["India, Kashmir"]', 'c. 1850–70', 'Silk and silver filé, wool: chain stitch embroidery', 'assets/patterns/archive-CMA-119769.webp', 'assets/patterns/archive-CMA-119769-thumb.webp', '9cf4ca9bf5a54ae96132b7849d1bd55fe836a1d86b2de5a6bf674a1fe087f15b', NULL, 3400, 3388, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1940.600', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1940.600', NULL, NULL, 'By the 1800s, the Himalayan foothill region of Kashmir was renowned for distinctive embroideries, and Kashmiri shawls were coveted by women throughout the British Empire. The center of this square shawl is in the form of an eight-petaled lotus, a symbol for the sun, and around it are the elongated forms of slender cypress trees, which became the inspiration for paisley. Every space is populated with figures: seated, standing, male, female, or playing musical instruments. Others are winged heavenly figures called peri. Birds are the only animals in these central spaces, suggesting a heavenly realm. In the next concentric ring riders in an equestrian procession alternate with flying birds. In the spandrels, the triangular sections between the circle and the square, are gatherings under a tent with animals. Some local Himalayan animals can be identified, such as the spotted snow leopard and the snake-eating markhor goat.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '披肩 南亚织绣  几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-164627', '莲花 · 花卉', 'Lotus-blossom petal canopy', NULL, '南亚织绣', 'archive', NULL, '["花草藤蔓","吉祥与礼仪"]', '["Northern India"]', 'c. 1600', 'silk: lampas', 'assets/patterns/archive-CMA-164627.webp', 'assets/patterns/archive-CMA-164627-thumb.webp', '42cd7201ffce52ad6898021bd4313d1ff21074edb5f03ef07ecdb666defa94dc', NULL, 3243, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2006.136', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2006.136', NULL, NULL, 'The ceilings of sacred spaces throughout India were carved or painted with concentric circular lotus patterns; many also included textile canopies with the same designs. This exceptionally large example was woven in one complete section on a single loom.  In India, the full-blown lotus flower bears solar connotations. It projects the radiance of a sacred or royal presence below. The motif of a dragon bearing down on a winged lion in each of the four corners indicates the designer’s recognition of a motif popular across Islamic Asia, from Turkey to Iran and Mughal India.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '莲花 · 花卉 南亚织绣  花草藤蔓 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-97769', '披肩', 'Square Shawl', NULL, '南亚织绣', 'archive', NULL, '["几何与团花","边饰与织锦"]', '["India, Kashmir, late 19th century"]', '1880s', 'twill tapestry and embroidery; large pieced areas: wool', 'assets/patterns/archive-CMA-97769.webp', 'assets/patterns/archive-CMA-97769-thumb.webp', '2f55f589ccc76a8674db6021b855381ed2a53ed4e9596c45c54b89fa649b22a3', NULL, 3358, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1917.40', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1917.40', NULL, NULL, NULL, NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '披肩 南亚织绣  几何与团花 边饰与织锦');
