INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95470', '边饰与织锦', 'Rumal with Vishnu temple and subsidiary shrines', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Northern India, Pahari Kingdom of Chamba"]', '1700s', 'Silk and silver embroidery on cotton tabby ground', 'assets/patterns/archive-CMA-95470.webp', 'assets/patterns/archive-CMA-95470-thumb.webp', '3ffb3fb5e6d494015e7350a2ea4a67625608298ad360fbcc987d0a78cc045c58', NULL, 3400, 3344, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1208', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1208', NULL, NULL, 'Two women bring gifts of pure water in a golden pot along with a flower garland to the four-armed blue Vishnu, whose favorite plant, the Tulsi basil, grows in an altar in front of the temple. Ten more shrines round out the sacred complex. To the upper right, the temple of Shiva with his trident stands next to that of his red, elephant-headed son, Ganesha. To the lower left, there appears to be temples to the sun and moon. Silver threads used to denote jewelry have tarnished and appear black. The unfinished border reveals that outlines and stitches for the vines were sewn last.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95788', '边饰与织锦', 'Cap', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["India"]', '1800s', 'Velvet embroidered with gilt-silver–wrapped silk thread (zari); silk: lining; rubies, pearls, and spinels', 'assets/patterns/archive-CMA-95788.webp', 'assets/patterns/archive-CMA-95788-thumb.webp', 'c11b33d9c13ad6100b11dc055b77ed63e38f448c3478b82a31e13946a7f25196', NULL, 3400, 2246, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1477', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1477', NULL, NULL, 'Historically in India, head coverings were worn in outdoor and formal contexts and can signal age, allegiance, and status among Indian men and boys. A low round cap such as this was worn primarily by the well-educated aristocratic boys in the king’s circle. The painstaking process of creating the ornament involved wrapping gilt-silver wire of various dimensions around a silk thread core to create a textured appearance for the flowers and vines.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-107191', '边饰与织锦', 'Loin Cloth "Pha nung" or Cloth for Wrapped Garment', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["India, East Coast, late 19th - early 20th century"]', 'late 1800s-early 1900s', 'tabby weave, mordant resist and batik; cotton', 'assets/patterns/archive-CMA-107191.webp', 'assets/patterns/archive-CMA-107191-thumb.webp', 'fd9051e15089cc2d3150543bd5526f682436121c44eb7f892c3c233df46932f7', NULL, 1748, 1536, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1925.119', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1925.119', NULL, NULL, 'Indian craftsmen developed great skill in resist dyeing using both mordants (chemicals that fix dyes) and wax, or some other resist. When mordants were selectively drawn, painted, or printed onto cotton, only those portions of the fabric would accept the dye. In this textile, this technique has been combined with wax resist batik that prevented dyes from penetrating treated portions of the fabric. Indian textiles made for export were patterned with designs and colors that suited the tastes of the markets for which they were produced. This cloth was made for export to Thailand where lattice designs were preferred. While this particular textile would have been used as a wrapped garment, Indian textiles in Thailand served also as room dividers, coverings for floors, and hangings.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-107865', '边饰与织锦', 'Cover for a Jain Manuscript', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Western India, Gujarat"]', 'c. 1800', 'Silk: satin weave; embroidery, polychrome silk, gold filé, flat metal strip', 'assets/patterns/archive-CMA-107865.webp', 'assets/patterns/archive-CMA-107865-thumb.webp', 'b6ec5575b5fec8f5d0e8de5badf049df150b38fc589e8fc5d9dc3130c82fd566', NULL, 3400, 1789, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1925.494', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1925.494', NULL, NULL, 'When closed, the horizontal stack of Jain manuscript pages is protected by firm covers on the top and bottom. A donor may commission a luxurious textile to place over or wrap the sacred text to honor it. Textiles with repeated floral plant patterns—these appear to be roses—were popularized at the imperial Mughal court during the mid-1600s, after which they spread throughout India.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-107873', '边饰 · 披肩', 'Border of a Shawl', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["India, Kashmir"]', 'c. 1825–30', 'wool: tapestry twill', 'assets/patterns/archive-CMA-107873.webp', 'assets/patterns/archive-CMA-107873-thumb.webp', '3244d1654a4ff0e670cb7dedd238262bbedc3c37381fb3e99dd4c6ffcc8167e4', NULL, 3400, 2705, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1925.500', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1925.500', NULL, NULL, 'Kashmiri shawls were extremely popular in the early 1800s, especially among foreigners to the Indian subcontinent. Made in the mountainous region of northwest India from wool from mountain goats from nearby Ladakh, the fabrics were especially prized for their softness and their beautiful symmetrical designs, often called paisley in English. This textile fragment was once owned by Ananda Coomaraswamy (1877–1947), a Ceylonese (Sri Lankan) art historian and collector who is credited with introducing South Asian art to museums in the United States.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰 · 披肩 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-108046', '边饰与织锦', 'Part of a sari', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["India, Mughal, Aurangabad, 18th-19th century"]', '1700s–1800s', 'central panel plain weave (paired weft): silk and metal thread; tapestry weave border', 'assets/patterns/archive-CMA-108046.webp', 'assets/patterns/archive-CMA-108046-thumb.webp', '481519077bbcd856370fb0639b045446977d72707f18e813575a3d7cc7dd34b5', NULL, 3400, 1788, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1925.670', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1925.670', NULL, NULL, 'This section of an upper garment has been cut down from its original length, with borders applied to the short ends. The rose-colored threads in one direction lend an underlying warmth to the metallic thread woven in the opposite direction that changes hue and sheen as the wearer moves. The border is a flowering vine pattern with alternating pink and orange blossoms.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-108075', '织物', 'Fragment', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["India, Gulbarga(?)"]', '1800s', 'Silk and metal: brocade', 'assets/patterns/archive-CMA-108075.webp', 'assets/patterns/archive-CMA-108075-thumb.webp', 'bdace2f47c7fee299b76578727e1bb9f7c1f4fc6bc419894e5242b5f9f34d197', NULL, 2063, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1925.695', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1925.695', NULL, NULL, 'This fragment and CMA 1925.714 both have a crimson satin ground embellished with a floral motif in metal thread and green silk within a framework of gold metal thread.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-108097', '织物', 'Fragment', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["India, Gulbarga ?, 19th century"]', '1800s', 'brocade; silk and metal', 'assets/patterns/archive-CMA-108097.webp', 'assets/patterns/archive-CMA-108097-thumb.webp', 'bcecd259417b5df3021e2cd77bc3590357ecdf890595e42121a565dcb9abd9c9', NULL, 3400, 1216, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1925.714', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1925.714', NULL, NULL, 'This fragment and CMA 1925.695 both have a crimson satin ground embellished with a floral motif in metal thread and green silk within a framework of gold metal thread.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-108172', '边饰与织锦', 'Part of a Skirt (Ghaghara)', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Western India, Gujarat, possibly Kutch"]', 'early 1800s', 'silk satin embroidered with silk in "ari" chain stitch', 'assets/patterns/archive-CMA-108172.webp', 'assets/patterns/archive-CMA-108172-thumb.webp', '5d969cbb1cba5e30c6f73cb9755a68534fe4bbbf24c6e61d30147bf1fd69bd25', NULL, 1610, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1925.794', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1925.794', NULL, NULL, 'Brightly colored floral vine patterns were embroidered using fine chain stitches. Since there are continuous, unbroken lines of stitches on the back side of the cloth, they were created using a hooked awl, which is a much faster process than embroidering with a straight needle. This type of embroidery is known as ari work, which flourished in Gujarat during the 19th century.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-109226', '马纹', 'Shaped horse trapping', NULL, '南亚织绣', 'archive', NULL, '["鸟兽鱼虫"]', '["India"]', '1600s', 'velvet, brocaded and pile warp substitution: silk and gilt-metal thread', 'assets/patterns/archive-CMA-109226.webp', 'assets/patterns/archive-CMA-109226-thumb.webp', '84f01aef7a09652d82be1a69876f5b8b2a590f5fad30b1ef6030c05181d59de6', NULL, 3400, 3083, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1927.376', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1927.376', NULL, NULL, 'The scrolling floral vines in the border and the combination of gold with imperial crimson resonate with the painted depiction of the textiles that accompany portraits of the emperor. The poppy plant in the center can be identified by the leaves with multiple lacy points and may reference the opium in which Emperor Jahangir indulged daily.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '马纹 南亚织绣  鸟兽鱼虫');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-114576', '边饰 · 披肩 · 织物', 'Border Fragment of a Shawl', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Kashmir"]', 'early 1800s', 'wool: tapestry twill', 'assets/patterns/archive-CMA-114576.webp', 'assets/patterns/archive-CMA-114576-thumb.webp', '676b4dd3b3d671bd9ad48969ca4c55459e2e21d64af194972ce6866187425da6', NULL, 3400, 2150, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1934.199', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1934.199', NULL, NULL, 'Green, yellow, red, blue, and white woolen threads were woven to create the instantly recognizable Kashmiri teardrop flower patterns on this shawl border. Such a work was part of a larger textile, which would have entranced the viewer with its complexity and vibrancy, especially as it moved with the wearer and contrasted with other articles of clothing.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰 · 披肩 · 织物 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-114729', '边饰 · 披肩 · 织物', 'Fragment of a Shawl Border', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Kashmir"]', 'c. 1815–25', 'wool and silk: tapestry twill', 'assets/patterns/archive-CMA-114729.webp', 'assets/patterns/archive-CMA-114729-thumb.webp', 'ef61ac99fbff717a1bd7dc646059483111836942f91e0016430ac596d59a6060', NULL, 3400, 3072, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1934.330', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1934.330', NULL, NULL, 'Many Kashmiri textiles, even those from the early 1800s, come down to us in fragments. This shawl border was once a part of a larger piece, which could have simply been draped over the body or stitched to the hem of a garment (as many European women did). Owning and wearing such luxury textiles would have been part of indicating one’s social status. Although incomplete, this work still shows the general pattern of the larger shawl, and it retains its vibrant and hypnotizing original color. Dyes were plant-based and are liable to wash out.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰 · 披肩 · 织物 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-115383', '地毯', 'Woolen carpet with millefleurs decoration', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["India, Kashmir"]', 'early 1600s', 'Pashmina (wool): asymmetrical knot', 'assets/patterns/archive-CMA-115383.webp', 'assets/patterns/archive-CMA-115383-thumb.webp', '08529e8fbf04ee82857936e0cc05c0e29fdf164dfde9c00957df2eb0d18ce123', NULL, 2947, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1936.17', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1936.17', NULL, NULL, 'Pashmina, a very fine fiber made from the fleece of Himalayan goats, was a material highly valued at the Mughal courts. Luxury rugs functioned in several ways, including as insulators for palatial and ceremonial spaces and as framing devices for important figures. In a biography of the Mughal emperor Akbar (reigned 1556–1605), called the Ain-i-Akbari, the court historian Abu’l Fazl (1551–1602) poetically wrote that such textiles created “a beautiful flowerbed.” The description is apt, as this carpet features an impressively symmetrical floral design known as millefleurs, or “thousand flowers” in French. Viewing several of these carpets and other hangings at once would have been visually impressive for court attendees.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '地毯 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-115730', '边饰与织锦', 'Man''s Morning Coat', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["India, Mughal"]', '1700–1750', 'cotton: tabby weave, resist-dyed (mordant resist and batik); applied gold leaf', 'assets/patterns/archive-CMA-115730.webp', 'assets/patterns/archive-CMA-115730-thumb.webp', '582742f5bee2070f6ae21fc444a667d25c537776c4a9da1b6e8e25ce4ae0a263', NULL, 3400, 3060, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1936.443', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1936.443', NULL, NULL, 'Much of the Mughals’ wealth derived from the international export of textiles, which became increasingly fashionable throughout Europe and America during the 18th century. This garment was made in India for the aristocratic French market. The floral designs inspired by the southern Indian dyed fabrics known as palampore have been enlivened by labor-intensive gilding and burnishing.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-128915', '织物', 'Fragment', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["India"]', '1100s–1300s', 'cotton: plain cloth, resist dyed', 'assets/patterns/archive-CMA-128915.webp', 'assets/patterns/archive-CMA-128915-thumb.webp', 'cdcba5d124538c84fc2958b2a8154b32be8a5d8c81a711cabefb8f3362242c91', NULL, 3400, 2019, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1951.510', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1951.510', NULL, NULL, 'This fragment has a pattern of stylized plant forms. The design was achieved by applying wax to design areas and then dipping it in red madder dye with use of mordant. The brown color was produced by the presence of iron in the mordant used for those areas.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-144672', '边饰与织锦', 'Bedspread', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["India, Goa"]', '1600s–1700s', 'Silk on cotton; embroidery', 'assets/patterns/archive-CMA-144672.webp', 'assets/patterns/archive-CMA-144672-thumb.webp', '9ea2673305a788463aad791eb5730f4bd2b307dc6979b943252afb5972725625', NULL, 3400, 2785, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1969.295', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1969.295', NULL, NULL, 'The design features biblical scenes with Indian mythological characters and Portuguese-costumed figures embroidered in chain stitch.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-159635', '人物', 'Rumal with Rama and Krishna scenes', NULL, '南亚织绣', 'archive', NULL, '["人物故事"]', '["Northern India, Pahari Kingdom of Chamba"]', '1700s', 'Silk and silver wire on cotton; embroidery', 'assets/patterns/archive-CMA-159635.webp', 'assets/patterns/archive-CMA-159635-thumb.webp', '5868170b4a1b6163d39a8cd2761743c1d6c8e92bfc5d1d19a99fc08b1c0a04db', NULL, 3400, 1986, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1996.349', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1996.349', NULL, NULL, 'Rumal refers to a double-sided embroidery technique perfected by women in the Pahari region of the northwest Himalayas. Unlike other forms of embroidery, no knots or loose strings are visible. Rumals were intended to look like paintings on cloth. An artist who was skilled in making Pahari paintings drew outlines of the composition with a brush on hand-loomed cotton muslin fabric and noted the colors to be used. Women then used a type of stitch called “double satin stitch” to create flat planes of color on both sides of the fabric. Girls were responsible for winding the silk threads into multistrand embroidery floss. Rumals were treasured as objects of wealth and given as gifts during weddings or state ceremonies. Many rumals depict subjects drawn from Hindu devotional literature. In the center, the semidivine monkey general Hanuman pays his respects to his lord Rama, Rama’s wife Sita, and Rama’s brother Lakshmana. Surrounding them above and to the right are bucolic rural scenes from the life of Krishna, another human incarnation of the god Vishnu. Krishna with his flute serenades the gopis (women of the cow herding community) and entertains his friends the cowherd boys (gopas). Flowering plants, vines, and wild animals populate the remaining space and borders. With such scenes, the painstaking act of double-sided embroidery becomes a devotional endeavor that generates religious merit.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物 南亚织绣  人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-161650', '边饰与织锦', 'Oversize Hip Wrapper (tapis)', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["India, Coromandel Coast, mid-18th Century"]', 'mid-1700s', 'cotton; plain weave; drawn resist, painted mordants, dyed', 'assets/patterns/archive-CMA-161650.webp', 'assets/patterns/archive-CMA-161650-thumb.webp', 'a10bd6cb0709bc01e2c021bddadc9f902f75ebbe19169cb234b76cd2ee49687d', NULL, 2048, 892, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2000.28', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2000.28', NULL, NULL, 'This colorful, elegantly patterned cloth was made in India for export to Indonesia in the East-West spice trade of the Dutch United East India Company. On the island of Sumatra such cloths, worn by both men and women, acquired ceremonial status, sometimes with magical and religious connotations. The pattern influenced local textile production, especially the heading at each end with triangles (kepala) on the deep red ground. The rich colors were a renowned hallmark of Indian cotton textiles, coveted in both Europe and the East. The Indian expertise in mordant patterning and dyeing was based on centuries of experience that foreigners sought in vain to duplicate. In 1734 a Frenchman, M. de Beaulieu, documented 11 stages of the labor-intensive process. It included applications of mordants (chemicals that fix dyes) that reacted in dye baths to produce specific colors; wax to keep desired areas white and dyed areas protected in subsequent dye baths; and bleaching in dung baths to lighten the ground.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-168275', '披肩', 'Long Shawl with Black Center and Exotic Four-Sided Gallery in Chinoiserie Style', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["India, Kashmir"]', '1840s', 'wool; 2/2 twill tapestry (S), double interlocked, pieced, refreshed', 'assets/patterns/archive-CMA-168275.webp', 'assets/patterns/archive-CMA-168275-thumb.webp', '7b38efa602d8f708316f91ea31d7eef74bebf3316018dc764227d4c99944e1d5', NULL, 1602, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2010.141', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2010.141', NULL, NULL, 'This expensive woven shawl has been refreshed—that is, its outdated designs have been replaced with beautiful new decoration. Overlapping pairs of botehs, or paisleys, enliven the original end panels (pallava) whereas the area around the central black rectangle was updated with an exotic four-sided gallery featuring ships, buildings, and flags that suggest Chinese influence. This stunning shawl is composed of seven almost invisibly joined pieces. One large section contains both ends and the continuous side borders while six pieces create the space in the middle. When the shawl was refreshed with the new chic gallery, black pigment—hardly visible—was applied along the edges of the central black section. The inscription may identify the textile’s quality or material content.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '披肩 南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95153', '边饰与织锦', 'Hanging with niche design', NULL, '南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["India, late 18th - early 19th century"]', 'late 18th - early 19th century', '2 1/2 twill tapestry weave [S] with double interlock, pieced:wool', 'assets/patterns/archive-CMA-95153.webp', 'assets/patterns/archive-CMA-95153-thumb.webp', '6956b137fc184d93c81f96cc53d551881aac907c124372e44613ec67c49df0b8', NULL, 2048, 1244, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1915.667', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1915.667', NULL, NULL, NULL, NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 南亚织绣  边饰与织锦');
