INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95332', '边饰与织锦', 'Sumibōshi', NULL, '东亚邻邦', 'archive', NULL, '["边饰与织锦"]', '["Japan, Edo period (1615–1868)"]', '1800–1850', 'silksatin weave; metal thread weft', 'assets/patterns/archive-CMA-95332.webp', 'assets/patterns/archive-CMA-95332-thumb.webp', 'b89ed63fd1b0d1f26a9a9d137c4ffe516db267da2b52c962fce484416bb1e98d', NULL, 1427, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.11', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.11', NULL, NULL, 'Sumibōshi literally means "hat with corners" in Japanese, and refers to the square shape made when this textile hat is tied on the head. Actors playing the roles of religious figures in Nō theater often wear this kind of cap. It derives from Buddhist vestments.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东亚邻邦  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95599', '人物故事', 'Gift Cover (Fukusa) with Tale of Genji Shell-Matching Game', NULL, '东亚邻邦', 'archive', NULL, '["人物故事"]', '["Japan, Meiji period (1868–1912)"]', '1868–1912', 'Silk: embroidered; metallic thread', 'assets/patterns/archive-CMA-95599.webp', 'assets/patterns/archive-CMA-95599-thumb.webp', 'f6e3c59b2b9815344a60ad28703ded8fbb7285b5b670de0921231fc58de580dc', NULL, 2953, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1319', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1319', NULL, NULL, 'Japanese elites once presented gifts in boxes with gift covers (fukusa) draped over them. The decorated covers were typically lined with a monochrome backing, but this one’s borders are exposed. Its design is a Tale of Genji shell-matching game. Two clamshells shown in close-up are painted with scenes from two chapters of the novel. The one on the bottom is an episode from the “Kochō” (Butterflies) chapter, in which Genji’s beloved Murasaki sends her young attendants to dance for the empress. The one on the top may depict Genji writing a poem in the “Suzumushi” (Bell Cricket) chapter.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物故事 东亚邻邦  人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95605', '边饰与织锦', 'Gift Cover (Fukusa) with Carp in Waves', NULL, '东亚邻邦', 'archive', NULL, '["边饰与织锦"]', '["Japan, Meiji period (1868–1912)"]', '1868–1912', 'Silk: embroidered; metallic thread', 'assets/patterns/archive-CMA-95605.webp', 'assets/patterns/archive-CMA-95605-thumb.webp', 'e1383bb2d3bfeee4254122d98a59f4e863774bd5b664cafea30d11b4ee4ab9c4', NULL, 2905, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1324', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1324', NULL, NULL, 'The motif of carp in rough water originated in China. The expression “carp jumping over the Dragon Gate” (liyu tiao longmen) refers to attaining success in life, or, historically, to passing the imperial examinations for civil service. Dragon Gate is a steep gorge of the Yellow River at Hejing in Shanxi province, and it was once said that if a carp swimming upstream could surmount the gorge, it would instantly transform into a dragon and fly into the sky. In Japan, therefore, a gift cover (fukusa) like this would have been appropriate to celebrate the recipient’s achievements.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东亚邻邦  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95622', '边饰与织锦', 'Buddhist Surplice (Kesa)', NULL, '东亚邻邦', 'archive', NULL, '["边饰与织锦"]', '["Japan, Meiji period (1868–1912)"]', 'early 1900s', 'silk with supplementary weft, brocaded; metal thread', 'assets/patterns/archive-CMA-95622.webp', 'assets/patterns/archive-CMA-95622-thumb.webp', '7935ae7d134450e049de6bacac02d0f631ae5c4b8f3a6bb4d30db1633f93bfac', NULL, 3400, 2062, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1338', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1338', NULL, NULL, 'The kesa is a Buddhist monk’s vestment worn folded and draped over one shoulder, and fastened over the chest. In keeping with the austere conditions of monastic life, kesa were traditionally fashioned from remainders of donated garments sewn together into a series of columns. The wider, central column symbolizes the Buddha. The squares with golden roundels in each corner represent the deities who guard the four directions, while the two at the top on either side of the central column symbolize attendant bodhisattvas, or the Nio, guardians who protect the Buddhist Law. This kesa is sewn from a textile with a butterfly and "eight bridges" (yatsuhashi) pattern.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东亚邻邦  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95625', '边饰与织锦', 'Buddhist Vestment (Kesa)', NULL, '东亚邻邦', 'archive', NULL, '["边饰与织锦"]', '["Japan, Meiji period (1868–1912)"]', 'early 1900s', 'silk with supplementary weft, brocaded; metal thread', 'assets/patterns/archive-CMA-95625.webp', 'assets/patterns/archive-CMA-95625-thumb.webp', '24ec42ff3ba3675b4359faacbaa882c7317b13d6b0e8dd1295a4e88e60853695', NULL, 3400, 1980, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1340', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1340', NULL, NULL, 'Kesa are Buddhist monastic robes that originated in India. The robes are named after the brown or saffron dye originally used in their production. The primary motif on this seven-paneled kesa is a long-tailed bird with a flower in its mouth. This motif was imported from Persia (present-day Iran) through China during the Nara period (710–794)and is interpreted as a positive symbol. The bird delivers happiness in its mouth.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东亚邻邦  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95630', '边饰与织锦', 'Buddhist Surplice (Kesa)', NULL, '东亚邻邦', 'archive', NULL, '["边饰与织锦"]', '["Japan, Meiji period (1868–1912)"]', 'early 1900s', 'silk with supplementary weft, brocaded; metal thread', 'assets/patterns/archive-CMA-95630.webp', 'assets/patterns/archive-CMA-95630-thumb.webp', 'b00c4bcab513675f3fc087fb71259df3f99b2918c8bd2e891a4535ef603ae171', NULL, 3400, 1897, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1345', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1345', NULL, NULL, 'The kesa is a Buddhist monk’s vestment worn folded and draped over one shoulder, and fastened over the chest. In keeping with the austere conditions of monastic life, kesa were traditionally fashioned from remainders of donated garments sewn together into a series of columns. The wider, central column symbolizes the Buddha. The orange squares with a phoenix and flower pattern in each corner represent the deities who guard the four directions, while the two at the top on either side of the central column symbolize attendant bodhisattvas, or the Nio, guardians who protect the Buddhist Law. This kesa is sewn from a textile with bold roundels with dragon and phoenix motifs.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东亚邻邦  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-98874', '袍服', 'Bridal Robe (Hwarot)', NULL, '东亚邻邦', 'archive', NULL, '["边饰与织锦"]', '["Korea, Joseon dynasty (1392–1910)"]', '1850–1910', 'Satin weave silk; silk embroidery; paper edging on neck and sleeves', 'assets/patterns/archive-CMA-98874.webp', 'assets/patterns/archive-CMA-98874-thumb.webp', 'e06da958e6ac6a991524af3f21f6ce8cd1ffdc1a99498277dcd912bf9485b8ad', NULL, 3400, 2545, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1918.549', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1918.549', NULL, NULL, 'This bride''s robe is exquisitely embroidered with various symbols of happiness in colorful silk threads. Butterflies stand for marital happiness; the phoenix, numerous offspring; and lotus flowers and white cranes, longevity. Yet, the bridal robe does not attest to the life of luxury. To the contrary, many traces of repairs, trimmings, and patchwork reflect Joseon period women’s commitment to value neo-Confucian aesthetics of frugality and modesty. Substantial repairs and patching reveal that this robe served as an important communal resource to be shared and passed down through several generations. Its collar and sleeves are covered in thick white paper; this paper is replaced with new paper for each bride, while the robe itself was reused for decades.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '袍服 东亚邻邦  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-98875', '袍服', 'Bridal Robe (Hwarot)', NULL, '东亚邻邦', 'archive', NULL, '["边饰与织锦"]', '["Korea, Joseon dynasty (1392–1910)"]', '1700s', 'Satin weave silk; silk embroidery; paper edging on neck and sleeves', 'assets/patterns/archive-CMA-98875.webp', 'assets/patterns/archive-CMA-98875-thumb.webp', 'a6e71a3f93b27f1add50b9f8f0b91bc57cfebf66a27c9e967058a23365b9ae40', NULL, 3400, 2545, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1918.550', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1918.550', NULL, NULL, 'This bride''s robe is exquisitely embroidered with various symbols of happiness in colorful silk threads. Butterflies stand for marital happiness; the phoenix, numerous offspring; and lotus flowers and white cranes, longevity. Yet, the bridal robe does not attest to the life of luxury. To the contrary, many traces of repairs, trimmings, and patchwork reflect Joseon period women’s commitment to value neo-Confucian aesthetics of frugality and modesty. Substantial repairs and patching reveal that this robe served as an important communal resource to be shared and passed down through several generations. Its collar and sleeves are covered in thick white paper; this paper is replaced with new paper for each bride, while the robe itself was reused for decades.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '袍服 东亚邻邦  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-98880', '袍服', 'Back Apron for the Royal Ceremonial Robe', NULL, '东亚邻邦', 'archive', NULL, '["边饰与织锦"]', '["Korea, Joseon dynasty (1392–1910)"]', 'late 1800s–early 1900s', 'red pile weave, wool or silk, embroidered with silk (polychromatic); red silk, gauze weave; white silk, gauze weave; green silk fringe; metal ring embellishments', 'assets/patterns/archive-CMA-98880.webp', 'assets/patterns/archive-CMA-98880-thumb.webp', '1130760ea89cae82daf488829777316d98bd2c9bddd28d06bf25cd32656329ab', NULL, 3372, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1918.551.d', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1918.551.d', NULL, NULL, 'This is a set of royal ceremonial robe and accessories worn by a high-ranking court official for attending special state ceremonies. The set consists of an inner coat, an outer coat, a skirt, a back apron, a crown, a pair of jade tassels, a tablet, and a belt.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '袍服 东亚邻邦  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-98884', '袍服', 'Bridal Robe (Hwarot)', NULL, '东亚邻邦', 'archive', NULL, '["边饰与织锦"]', '["Korea, Joseon dynasty (1392–1910)"]', 'late 1800s', 'Silk: satin weave; embroidery; paper edging on neck and sleeves', 'assets/patterns/archive-CMA-98884.webp', 'assets/patterns/archive-CMA-98884-thumb.webp', '80651b8fa799cd6a20ad963ce3237472944dc1354eba72202f615990a7c2e4ff', NULL, 3400, 2545, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1918.552', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1918.552', NULL, NULL, 'This bride''s robe is exquisitely embroidered with various symbols of happiness in colorful silk threads. Butterflies stand for marital happiness; the phoenix, numerous offspring; and lotus flowers and white cranes, longevity. Yet, the bridal robe does not attest to the life of luxury. To the contrary, many traces of repairs, trimmings, and patchwork, reflect Joseon period women’s commitment to value neo-Confucian aesthetics of frugality and modesty. Substantial repairs and patching reveal that this robe served as an important communal resource to be shared and passed down through several generations. Its collar and sleeves are covered in thick white paper; this paper is replaced with new paper for each bride, while the robe itself was reused for decades.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '袍服 东亚邻邦  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-147935', '树木 · 花卉', 'Nō Costume (Nuihaku) with  Blossoming Trees and Flowers', NULL, '东亚邻邦', 'archive', NULL, '["花草藤蔓"]', '["Japan, Edo period (1615–1868)"]', '1675–99', 'embroidery, silk and applied gold leaf on silk ground', 'assets/patterns/archive-CMA-147935.webp', 'assets/patterns/archive-CMA-147935-thumb.webp', 'a3134cd5de9a4ed6083e445d1cf92f625984f75f893eee6559a8341a0b3a05c5', NULL, 1714, 1536, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1974.36', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1974.36', NULL, NULL, 'This magnificent robe was a costume specifically designed for performances of Noh theater in Japan. Originating during the 1300s from simple folk plays, Noh drama evolved into formal presentations of ritual, theater, dance, and music performed in the courts and shrines of the nobility. Stories were derived from a variety of sources—myths, legends, poetry, and prose—many dating back to the medieval period. Because great importance was placed on subtlety and elegance, plots tended to be minimal. Whether male or female all roles were played by men. Central to these performances were the masks and costumes worn by the actors. The brilliance and elegance of this robe are characteristic of costumes made solely for Noh theater. Its date in the first half of the 1700s is indicated by the proportions of the robe, the choice of embroidery stitches (satin, couching, and outline), and the absence of decoration at the hips, a fashion also reflected in kimonos at that time. The design of weeping cherry trees and irises in the snow was very likely inspired by a medieval Japanese poem. Robes decorated with embroidery against a gold ground were reserved for female roles. These robes were worn under the external garment and were only partially visible.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '树木 · 花卉 东亚邻邦  花草藤蔓');
