INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-101162', '织物', 'Textile Fragment', NULL, '东亚邻邦', 'archive', NULL, '["边饰与织锦"]', '["Japan"]', '1800s', 'silk', 'assets/patterns/archive-CMA-101162.webp', 'assets/patterns/archive-CMA-101162-thumb.webp', 'a4819500367e90d8b665b9ae8478ee7c8a6584ace21049ed82d1d8c3e9ab4b70', NULL, 3400, 2545, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1508', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1508', NULL, NULL, NULL, NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 东亚邻邦  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-97613', '边饰与织锦', 'Sarong', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Indonesia, Java, North Coast, mid-19th century"]', 'mid-1800s', 'Cotton: plain weave, wax-resist dyed (batik)', 'assets/patterns/archive-CMA-97613.webp', 'assets/patterns/archive-CMA-97613-thumb.webp', '77c2217460ba0c1ba27cc832932da3114a9f6c04b8ca74fb1d239cdc90db8ee8', NULL, 3400, 1892, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1917.26', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1917.26', NULL, NULL, 'Batiks made in the North Coast region of Java, specifically in Pekalongan, were influenced by both Indian and European motifs due to the Dutch presence in Indonesia. In this sarong we see a mixture of Indian and European flowers including jasmine, lilac, and daffodil. Batik is a wax-resist dyeing technique used throughout Java. Hot wax is applied with a tool known as a canting and a design is hand drawn with incredible skill. This sarong was then dyed with indigo, a well sought after and culturally important natural dye. Areas on the fabric with wax will not accept the indigo dye, hence the term wax-resist.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-97626', '边饰与织锦', 'Sarong', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Indonesia, Java, North Coast, Indramaju ?, early 20th century"]', 'early 1900s', 'batik; cotton', 'assets/patterns/archive-CMA-97626.webp', 'assets/patterns/archive-CMA-97626-thumb.webp', '02801b001e761bbd63f010e4aa2fdbbd0ae211c61e56ab9d442a6b820fe222e8', NULL, 3400, 1892, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1917.27', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1917.27', NULL, NULL, 'Batiks made along the northern coast of Java were influenced not only by Chinese motifs and designs but also European, as a result of the Dutch presence in Indonesia from the sixteenth to the twentieth centuries. In this sarong, European influence is clearly evident in the sprays of flowers and types of birds represented. Batiks dyed only in indigo were a specialty of Indramaju. Shading and contrast are skillfully achieved through different intensities of blue, through the character and thickness of line, and by the use of tiny dots.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-97668', '边饰与织锦', 'Slendang (Shoulder Cloth)', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Indonesia, Central Java, 19th - early 20th century"]', '1800s–early 1900s', 'tabby weave, batik; cotton', 'assets/patterns/archive-CMA-97668.webp', 'assets/patterns/archive-CMA-97668-thumb.webp', 'da877c19fda2d88d5b539ca677c37dc67009df0152e0fd953005dc3e852eae3e', NULL, 861, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1917.31', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1917.31', NULL, NULL, 'Batik is an ancient technique that was practiced in India and throughout much of Southeast Asia. With the invention of the "canting" (a tool used to apply hot wax to fabric) in the 17th - 18th centuries, however, batik bacame a particular speciality of Java. This batik was produced in the central regions of Java where cloths were resist-dyed with traditional designs in white, indigo blue, and dark brown. The stylized wing and tail of the mythical bird Garuda and the sacred mountains seen here had cosmic significance and were reserved for textiles worn by nobility for ceremonial occasions or for dance costumes. The white, elongated diamond-shaped center is unique to batik shoulder cloths.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-98129', '边饰与织锦', 'Headcloth (Yakan seputangan)', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Philippines"]', 'c. early 1900s', 'plain weave with paired weft: cotton; supplementary weft: silk', 'assets/patterns/archive-CMA-98129.webp', 'assets/patterns/archive-CMA-98129-thumb.webp', '4ba9e9585b003424df5a844503fcaedb2897c43c1708c811ffa581448f7606de', NULL, 3400, 3297, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1917.746', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1917.746', NULL, NULL, 'This seputangan (headcloth) was produced by the Yakan people of Basilan, and worn by men in ceremonial, formal, and dress contexts. The cloth was woven on a back-strap loom with a cotton warp and patterned using supplementary-weft silk, which produces the characteristic lustrous motifs across the surface. The vivid, high-contrast color combinations are characteristic of Yakan ceremonial textiles.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-98130', '织物', 'Mandaya textile (composite dagmay)', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Philippines, Mindanao"]', 'c. early 1900s', 'plain weave hemp, dyed', 'assets/patterns/archive-CMA-98130.webp', 'assets/patterns/archive-CMA-98130-thumb.webp', '798867d6bf06a9dd58af9703e63d3d2679610fbdc398c0d2f0b71ae9953e480d', NULL, 1031, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1917.747', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1917.747', NULL, NULL, 'This textile strikingly fuses two different weaving traditions and materials: abacá ikat (dagmay) for the patterned sections, and commercially or locally dyed cotton for the plain-weave intervals. This combination is an inventive Mandaya solution for creating a cloth that retains ritual meaning through its abacá ikat components, while achieving comfort, flexibility, and drape through the inclusion of cotton.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-98131', '织物', 'Mandaya ikat textile (dagmay)', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Philippines, Mindanao"]', 'c. early 1900s', 'plain weave hemp, dyed', 'assets/patterns/archive-CMA-98131.webp', 'assets/patterns/archive-CMA-98131-thumb.webp', 'ccbb58165a00191d7c520562445f58d9130136b0272649690642931d9e05685e', NULL, 1760, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1917.748', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1917.748', NULL, NULL, 'This textile is a Mandaya abacá ikat cloth woven in southeastern Mindanao. It is made from hand-stripped abacá fibers that are resist-dyed using the Mandaya ikat technique, in which selected warp threads are tightly bound before dyeing to produced patterned sections during weaving. The designs embody Mandaya cosmology and are traditionally associated with protection, fertility, and the presence of umagad (ancestral spirits).', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-98146', '边饰与织锦', 'Backpack (Bagobo people)', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Philippines"]', 'early 1900s', 'Handwoven abacá cloth, printed cotton cloth, abacá fiber (braided/plaited cordage), glass beads, metal sequins, metal rings, fiber tassels', 'assets/patterns/archive-CMA-98146.webp', 'assets/patterns/archive-CMA-98146-thumb.webp', '3aceb436d243ca430af9a462dd8d9446f89271ef043ed6a2c42bf8c72391df2c', NULL, 3070, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1917.770', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1917.770', NULL, NULL, 'This backpack for men is constructed from a single length of handwoven abacá cloth, woven in a warp-faced plain weave with supplementary weft patterning. The beadwork uses glass beads of various colors arranged in geometric bands and diamond motifs characteristic of the Bagobo people. Two shoulder straps, constructed from braided abacá fibers overlaid with cotton cloth and embellished with beads and metal sequins, are attached through metal rings.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-98147', '边饰与织锦', 'Shoulder basket (Bagobo people)', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Philippines, Davao"]', 'c. 1875–1917', 'natural fibers, cloth, glass beads, metal', 'assets/patterns/archive-CMA-98147.webp', 'assets/patterns/archive-CMA-98147-thumb.webp', '84aa4fdd566392e4861e5b2c8c83aca266d6aad72f1cb4ebc46c5e3c63f53ac1', NULL, 1939, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1917.771', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1917.771', NULL, NULL, 'This shoulder bag is built on a rigid, flat-bottomed rattan basket. A rough, red-dyed cotton cloth has been shaped to the basket and secured with abacá fiber stitching. The strap features small metal sequins sewn along the strap and at the hem. Additional beaded strands hang from the strap junction and rim, each terminating in small fiber-wrapped tassels.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-102980', '织物', 'Textile fragment (Binakol)', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Philippines, Ilokos, Norte Province, Luzon, 20th century(?)"]', 'c. early 1900s(?)', 'woven cotton; extended tabby weave', 'assets/patterns/archive-CMA-102980.webp', 'assets/patterns/archive-CMA-102980-thumb.webp', '76b00a200eeadd4ce24ea1994b73b704b8c8726ebdc131c73beffcffbac91aa2', NULL, 2377, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1921.1596', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1921.1596', NULL, NULL, 'This intricate, hand-woven textile was likely produced on a back-strap or upright loom. The binakol block pattern creates a strong optical effect, organized in vertical registers separated by broad, dark stripes with narrow, red accents. The central design is a variant of the whirlpool motif known as kusikos, in which alternating light and dark squares appear to spiral or recede.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-107179', '边饰与织锦', 'Wall Hanging or Ceiling Canopy', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Cambodia, Khmer People, early 20th century"]', 'early 1900s', 'tabby weave, weft ikat; silk', 'assets/patterns/archive-CMA-107179.webp', 'assets/patterns/archive-CMA-107179-thumb.webp', '42095439714c77ee448c34b7698606309f11a65d114b02fa95526d3d74d5c6a4', NULL, 3400, 1548, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1925.118', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1925.118', NULL, NULL, 'The silk wefts of this textile were resist dyed with a design of elephants, temples, large tigers (?), sacred trees, and humans before the textile was woven. Both the weft-ikat technique and the motifs reveal the influence of Indian textiles, particularly patola. The dark reddish-maroon color of the ground, however, was not produced by over-dyeing, as in India and Bali, but by the combination of red wefts with black warps. This silk was made to serve as a wall hanging or ceiling canopy in a Buddhist temple.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-107205', '边饰与织锦', 'Half of a "Sampot" (Skirt Cloth)', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Cambodia, 19th -  early 20th century"]', '1800s–early 1900s', 'tabby weave, weft ikat; silk', 'assets/patterns/archive-CMA-107205.webp', 'assets/patterns/archive-CMA-107205-thumb.webp', 'e1ae9d8869f41cb2877cc2f41a7de12a948a32d867d4aaa27f9343be05e5b60f', NULL, 3400, 790, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1925.120', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1925.120', NULL, NULL, 'Ikat-dyed silks from Southeast Asia are weft ikats. Both the technique and the use of silk originated in India and spread to those parts of Southeast Asia that were accessible to international trade. There, it gradually replaced the earlier technique of warp ikat using cotton. The antiquity of this technique in Cambodia is indicated by weft-ikat designs that are preserved on sculptures of the Ankor period (9th-13th centuries). The diagonal lattice pattern in the central field of this textile was common throughout Southeast Asia. Because the textile was inteded to be a skirt cloth, there is little figural representation in its design.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-107858', '边饰与织锦', 'Waist Cloth (Kain Panjeng)', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Indonesia, Central Java, 19th century - early 20th century"]', '1800s-early 1900s', 'cotton: batik', 'assets/patterns/archive-CMA-107858.webp', 'assets/patterns/archive-CMA-107858-thumb.webp', '21de52558af472c287514a05250bd2583dbc9e4c3b74e452c218c05ad6548acc', NULL, 3400, 1455, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1925.488', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1925.488', NULL, NULL, 'Unlike the Chinese and sometimes European motifs of northern Javanese batiks, the motifs represented on the batiks of central Java are indigenous. However, due to the influence of Islam, they are represented in a very abstract, stylized fashion. In this batik, a celestial scene—probably signifying the ritual renewal of community life and prosperity—is repeated against a background of small filling motifs. The scene consists of a ship (represented as a divided bow and stern) bearing a Tree of Life, which signifies the community''s passage to renewed life; on either side of the ship is a winged pavilion; and above is a sacred mountain, the abode of the gods, with a shrine.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-107861', '边饰与织锦', 'Hinggi', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Indonesia, Sumba, 19th century"]', '1800s', 'warp ikat; cotton', 'assets/patterns/archive-CMA-107861.webp', 'assets/patterns/archive-CMA-107861-thumb.webp', '885ce157b4f1b50b812baccd274ef798f1d0db1957f1ab0b4edc1c6f1b742f82', NULL, 3400, 1506, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1925.490', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1925.490', NULL, NULL, 'Hinggi are large mantles woven in identical pairs, one worn around the waist and the other draped over the shoulder. As is characteristic of Sumbanese "hinggi," the design of this mantle relates to the traditional animistic religious and social structure of Sumba: the division of the cloth into horizontal bands reflects the layout of the traditional Sumbanese village, the rampant lions denote royal power, the trees of life between the cockatoos are symbols of fertility, and the geometric figure repeated across the center of the cloth is a symbol of royalty.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-110055', '边饰与织锦', 'Sarong', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Indonesia, Java, North Coast, 19th century"]', '1800s', 'batik and applied gold, cotton', 'assets/patterns/archive-CMA-110055.webp', 'assets/patterns/archive-CMA-110055-thumb.webp', 'cc867f97381ecfa49c78e43ccab08b144c170d00d8244e1728003de17cb43083', NULL, 3400, 1434, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1928.656', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1928.656', NULL, NULL, 'This sarong, overlaid with gold leaf (or gold dust), would have been worn for high ceremonial occasions and festivals. The gold has been applied only to the parts of the sarong that would show when draped, and on one side only. The delicate, linear design with Chinese phoenixes, butterflies, and leafy tendrils is one of the characteristic styles of batiks made in cities along the north coast of Java. The "tumpal" (triangle) design of the wide end border (a pan-Southeast Asian motif that commonly occurs on northern Javanese batiks) seems to have symbolized growth and fertility as well as the sacred mountain, Meru.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-110356', '刺绣 · 织物', 'Embroidered Textile', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Philippines"]', '1800s', 'Plain weave piña cloth: needle lace and embroidery', 'assets/patterns/archive-CMA-110356.webp', 'assets/patterns/archive-CMA-110356-thumb.webp', '581346c0d2e4f47e6a9738f473128573be2c45d85d222e9ba68826901e1305c7', NULL, 3400, 1656, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1928.9', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1928.9', NULL, NULL, 'This rectangular textile is composed of a fine, translucent ground fabric with a scattered pattern of small embroidered floral sprigs. Along the lower edge is a continuous band of oval medallions framed by embroidered scrolling elements, each enclosing a central floral motif executed in calado or another openwork technique. Vertical floral panels separate the medallions, and the edge terminates in a scalloped openwork border.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '刺绣 · 织物 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-110569', '边饰与织锦', 'Slendang (Shoulder Cloth)', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Indonesia, Java, North Coast, 19th - early 20th century"]', '1800s-early 1900s', 'tabby weave, batik; silk', 'assets/patterns/archive-CMA-110569.webp', 'assets/patterns/archive-CMA-110569-thumb.webp', '65fc802d3d515aba5bdd998b196cbe4fe2490261295b5544026e76e03f6c29cf', NULL, 876, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1929.136', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1929.136', NULL, NULL, 'Chinese people living in the coastal cities of northern Java made and traded silk batiks like this one. The silk was imported from China, and the motifs were always Chinese. The "luk wan" bird, a variation of the Chinese phoenix that occurs on this shoulder cloth, was one of the most common motifs on silk batiks, as is the greenish color of the background. The striped border was meant to simulate fringe even though each end is actually finished with fringe. Silk batiks were made for export, particularly to Bali where they were worn at festivals by wealthy people.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-113697', '边饰与织锦', 'Pair of Shoes', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Philippines"]', '1850–1932', 'Abacá fiber: macramé knotted lace', 'assets/patterns/archive-CMA-113697.webp', 'assets/patterns/archive-CMA-113697-thumb.webp', 'bb440aa124985f44e2e9e93181d0bb55250a54a65bb5db8e0f9f67fbec4d0312', NULL, 3400, 2590, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1932.650', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1932.650', NULL, NULL, 'Finely knotted abacá fibers form intricate geometric patterns in this small pair of shoes, likely created for display rather than for wear. Some sections are dyed, adding subtle tonal variation to the design. The macramé technique combined with local abacá suggests a colonial-era or early-20th-century hybrid craft, likely taught in a convent or school setting.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-116068', '刺绣', 'Embroidered Handkerchief', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Philippines"]', '1880–99', 'Plain weave piña, silk embroidery', 'assets/patterns/archive-CMA-116068.webp', 'assets/patterns/archive-CMA-116068-thumb.webp', 'e7f585a76f95b65037852a1b722053e11f25609a46b078076fe5a9f24370671c', NULL, 3376, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1936.739', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1936.739', NULL, NULL, 'This square handkerchief is made of piña fiber cloth in plain weave. All four edges are finished with a hand-embroidered cotton border of small repeating floral motifs. One corner bears the embroidered monogram “L. C. H.,” the initials of its first owner, Lilian Converse Hanna.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '刺绣 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-123152', '边饰与织锦', 'Blouse in four pieces', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Philippines"]', '1800s', 'Plain weave piña; needle lace (drawnwork) and white cotton embroidery', 'assets/patterns/archive-CMA-123152.webp', 'assets/patterns/archive-CMA-123152-thumb.webp', '5806e7419c47ad2b38149dbd708a5ddbdf3b0dc2756bdb4e4f347b6da27e00ce', NULL, 3400, 3286, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1943.380', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1943.380', NULL, NULL, 'This group consists of coordinated clothing components made of fine piña cloth in plain weave, all worked in matching hand-embroidered cotton motifs. The set includes a fichu, an unsewn blouse front (pechera), and two unsewn sleeve panels. All four pieces share the same ground material, embroidery thread, and design vocabulary, indicating that they were intended as elements of a single baro-camisa ensemble.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-123764', '边饰与织锦', 'Piña cloth', NULL, '东南亚织绣', 'archive', NULL, '["边饰与织锦"]', '["Philippines"]', 'mid-1800s', 'piña fiber, silk', 'assets/patterns/archive-CMA-123764.webp', 'assets/patterns/archive-CMA-123764-thumb.webp', 'a82057b72a3be98dc332a0ea91cc97ed6df82989d7e3bf6c489d1d16289b1723', NULL, 3400, 1962, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1944.280', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1944.280', NULL, NULL, 'This fabric is woven in plain weave using a piña ground with vertical bands of closely spaced silk warp stripes arranged in a repeating pattern. The stripes run the full length of the cloth.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 东南亚织绣  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-118330', '莲花 · 花卉 · 狮纹', 'Mantle for a Statue of the Virgin with Lotus Blossoms and Medallions', NULL, '埃及与地中海', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","人物故事","几何与团花","吉祥与礼仪"]', '["Egypt and Spain","Egypt"]', 'c. 1430', 'Silk and gilt-metal thread: lampas weave', 'assets/patterns/archive-CMA-118330.webp', 'assets/patterns/archive-CMA-118330-thumb.webp', '455d942dcb95ec49bcf1c59c80d4c1af778298a2980f9009fe87ca0fd30fc41a', NULL, 3400, 2219, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1939.40', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1939.40', NULL, NULL, 'This costly royal silk with extensive gold thread was woven in Egypt and gifted or exported to Spain, where it was pieced into this mantle for a statue of the Virgin, probably to be worn during festivals and processions. The sturdy silk brocade foundation cloth was also woven with a lighter weight silk damask with a repeating mirror image. Therefore, the Arabic inscription in the medallions reads both forward and backward: Glory to our master, the sultan, the king. The inscribed lobed roundels say The sultan, the king.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '莲花 · 花卉 · 狮纹 埃及与地中海  花草藤蔓 鸟兽鱼虫 人物故事 几何与团花 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-129188', '狮纹 · 动物 · 团形纹', 'Tapestry with lattice of animals in medallions', NULL, '埃及与地中海', 'archive', NULL, '["鸟兽鱼虫","几何与团花","边饰与织锦"]', '["Egypt"]', '600s–700s', 'wool and linen: tapestry weave', 'assets/patterns/archive-CMA-129188.webp', 'assets/patterns/archive-CMA-129188-thumb.webp', 'c729273f8ce636e73ee03b2ef9ed12a1779505fc6e1d2be50876bf8d02900914', NULL, 3286, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1951.89', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1951.89', NULL, NULL, 'This is a fragment from an horizontal band that was woven to be applied as a decoration to a garment. It has diamond compartments containing floral, geometric, and animal motifs.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '狮纹 · 动物 · 团形纹 埃及与地中海  鸟兽鱼虫 几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-98460', '狮纹 · 团形纹 · 几何纹', 'Lampas with foliate medallions in ogival lattice', NULL, '埃及与地中海', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","几何与团花"]', '["Egypt"]', '1400s', 'lampas: silk', 'assets/patterns/archive-CMA-98460.webp', 'assets/patterns/archive-CMA-98460-thumb.webp', '3aab97eef1ee4871b2367efe6bb131d2c772377df8d68e1528a53d6432c39beb', NULL, 3400, 3250, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1918.189', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1918.189', NULL, NULL, NULL, NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '狮纹 · 团形纹 · 几何纹 埃及与地中海  花草藤蔓 鸟兽鱼虫 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-124774', '团形纹 · 织物', 'Fragmentary roundel with eagle in gold ground', NULL, '埃及与地中海', 'archive', NULL, '["鸟兽鱼虫","几何与团花"]', '["Egypt, Fatimid period"]', '1000s', 'linen, silk, and gold filé: plain weave with inwoven tapestry weave', 'assets/patterns/archive-CMA-124774.webp', 'assets/patterns/archive-CMA-124774-thumb.webp', '487753e239448470b4c98f6fc5dae002fc60bf358233614d99301be96c371007', NULL, 3400, 2750, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1946.258', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1946.258', NULL, NULL, 'This plain weave fragment contains an ornamental bird with outstretched wings encircled by a pearled frame.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '团形纹 · 织物 埃及与地中海  鸟兽鱼虫 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-129824', '人物 · 团形纹', 'Roundel with figure', NULL, '埃及与地中海', 'archive', NULL, '["人物故事","几何与团花"]', '["Egypt, Fatimid period"]', '1000s', 'Linen and silk: plain weave with inwoven tapestry weave', 'assets/patterns/archive-CMA-129824.webp', 'assets/patterns/archive-CMA-129824-thumb.webp', '35daaf9ee1a32d8c336ce8c8341ef54ea2b0373646c85f57bd74abfa23c8b59f', NULL, 3400, 3344, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1952.255', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1952.255', NULL, NULL, 'A running figure clad in a short tunic, turban, and low boots is portrayed in this roundel. The figure holds in his right hand a string attached to a falcon which stands in the space beneath his outstretched left hand. In the upper background are foliate forms on long curving stems. The roundel is framed with a border decorated with a pseudo-inscription in deformed Kufic letters against a floriate background.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物 · 团形纹 埃及与地中海  人物故事 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-136406', '边饰', 'Border of Heads and Palmettes from a Large Hanging', NULL, '埃及与地中海', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Egypt, Antinoë, Byzantine period"]', '500s CE', 'Dyed wool, undyed linen; slit-tapestry weave', 'assets/patterns/archive-CMA-136406.webp', 'assets/patterns/archive-CMA-136406-thumb.webp', '4a2dc2b504b1d9066524c78a2625a1eac426d270193fdb9cc57266660a050f10', NULL, 1290, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1960.273', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1960.273', NULL, NULL, 'Heads with caps facing front alternate with palmette (fan-shaped) leaves on a rich blue ground—a popular border design for luxurious woolen hangings whose field patterns often incorporated Iranian artistic features. An alternating red and white foliate (leaflike) design forms the secondary border.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰 埃及与地中海  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-147015', '团形纹', 'Luxurious Woolen Tunic with Decorated Bands and Roundels', NULL, '埃及与地中海', 'archive', NULL, '["几何与团花","边饰与织锦"]', '["Egypt, Umayyad period (661–750)"]', '600s–700s', 'undyed linen, dyed wool: weft-faced plain weave with slit- and dovetailed-tapestry weave, supplementary weft wrapping, embroidery', 'assets/patterns/archive-CMA-147015.webp', 'assets/patterns/archive-CMA-147015-thumb.webp', '76c9f6c5accba2d421d9eb4858adddf88ba4d7b9305abc325bc490b644e13782', NULL, 3400, 2208, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1972.46', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1972.46', NULL, NULL, 'Since the mid-200s CE tunics were the main garments worn in Egypt. This unisex tunic is decorated on the front and back with the same geometric and figural motifs, including men on horseback hunting and geometric braided knots that were believed to protect the wearer from harm. A red background was favored in the early Islamic period. Made of thick wool for cooler weather, it was woven in one complete piece with the front, back, and sleeves in this exact shape and size. The tunic’s owner repaired it on the left side and shortened it nearly two inches by sewing a fold around the waist. The discoloration and deterioration indicate the garment may have been used in a burial.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '团形纹 埃及与地中海  几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-149666', '人物 · 边饰', 'Two Figures Framed by a Jeweled Border', NULL, '埃及与地中海', 'archive', NULL, '["人物故事","边饰与织锦"]', '["Byzantine Empire (Egypt)"]', '450–550 CE', 'wool, linen, and dye', 'assets/patterns/archive-CMA-149666.webp', 'assets/patterns/archive-CMA-149666-thumb.webp', 'fb7c16a55a1b847a1434b306027e51fbccb5e142889ff1a82ed0134c4f5cea22', NULL, 3400, 3040, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1979.58', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1979.58', NULL, NULL, 'This weaving depicts a haloed man and woman. However, it once had a third figure at left. The textile was damaged before its 1979 acquisition; only the third figure’s partial halo and shoes remained. Staff decided to “close the gap” around the missing area and remove the shoes. While creating a “complete” image, that removal affects our ability to understand the weaving’s subject. Many questions remain: Who are the man and woman? His red cap may identify him as an “Easterner” or a freeman. Who was their missing companion? Continuing research will consider biblical and Greek mythological stories in which threads play a role.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物 · 边饰 埃及与地中海  人物故事 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-151275', '织物', 'Panel from a Large Curtain, Overlapping Leaves', NULL, '埃及与地中海', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Egypt, Byzantine period"]', '300s–400s CE', 'Undyed linen and dyed wool: tapestry weave sewn on plain weave ground', 'assets/patterns/archive-CMA-151275.webp', 'assets/patterns/archive-CMA-151275-thumb.webp', 'a68addb162b943d8217da8c54792c8f41bc3678d7b91ca3f06a19ed1029d69c6', NULL, 3400, 625, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1983.145', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1983.145', NULL, NULL, 'These colorful overlapping leaves with interspersed buds along the sides originally formed a decorative panel in a large curtain. Together with several similar designs, they alternated with areas of undyed linen decorated with scattered wool and linen tapestry-woven motifs. Although decorative motifs were often woven into the ground fabric, this panel was sewn on afterwards. During the late Roman and early Christian period curtains with woven or applied decoration were used in churches and Christian meeting rooms to separate the clergy from the congregation. They were also hung in doorways and between columns both inside and outside. Their importance is evident in numerous portraits of religious figures and laymen represented between curtained arches.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 埃及与地中海  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-161684', '人物 · 织物', 'Curtain Panel with Scenes of Merrymaking', NULL, '埃及与地中海', 'archive', NULL, '["人物故事","边饰与织锦"]', '["Egypt, Byzantine period"]', '500s', 'Linen, undyed; wool: dyed; tapestry weave with supplementary weft wrapping', 'assets/patterns/archive-CMA-161684.webp', 'assets/patterns/archive-CMA-161684-thumb.webp', '8bc242c13a068a1ddba97d3512bf06206e3e265d0670cd72cc0d9c8a906fab0b', NULL, 1431, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/2000.5', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '2000.5', NULL, NULL, 'This large panel conveys merrymaking, wealth, and power through its symbolic imagery and deep purple color. It was originally part of a luxurious wide curtain with similar panels alternating with plain linen panels. Although woven in Christian Egypt, the panel is dominated by pagan subjects. A nude male stands beside a dancing female in transparent clothing in each of the three squares, alternating with centaurs (half-man, half-horse creatures) in roundels. In the central square, Dionysus, the god of wine, holds a grapevine and a weary Hercules leans on his club below. The lively animal imagery conveys wealth because few could afford animals such as lions, bulls, and hares.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物 · 织物 埃及与地中海  人物故事 边饰与织锦');
