INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95782', '边饰与织锦', 'Garment', NULL, '埃及与地中海', 'archive', NULL, '["边饰与织锦"]', '["Africa, North Africa, Egypt, Aswan, unidentified makers"]', 'c. 1890s', 'Silk, mirrored glass', 'assets/patterns/archive-CMA-95782.webp', 'assets/patterns/archive-CMA-95782-thumb.webp', '1d5833ceab42d528ed8ee70bd55aae86c78218acaf0f68f33a465e555cca25c4', NULL, 2265, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1472', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1472', NULL, NULL, 'Covered with symbolic decorations, this multitone silk garment beautified and protected its wearer. The khamsah (خمسة)—an open five-fingered hand—figures prominently as a cream-colored appliqué. The khamsah deflected or absorbed al-''ayn (العين‎)—the evil eye—as did the appliquéd mirrors, shielding the wearer from many varieties of harm. New research connects this garment to an entry in museum founder J. H. Wade’s 1881–1900 travel purchase notebook: “Kalifa’s gown emb[roidered] on purple silk.” A caliph (or khalifah) is a leader of a Caliphate (Islamic state) or an Islamic religious group. Whether this was indeed a caliph’s gown is a point of future research.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 埃及与地中海  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-96266', '几何与团花', 'Ornamental Square from a Tunic', NULL, '埃及与地中海', 'archive', NULL, '["几何与团花"]', '["Egypt, Byzantine period"]', '400s CE', 'Linen, undyed; wool, dyed; tapestry weave with supplementary weft wrapping', 'assets/patterns/archive-CMA-96266.webp', 'assets/patterns/archive-CMA-96266-thumb.webp', '296266c6c75c24df5e4eea6ade281d3c8a5d317ecacaa4c0de16b00085022868', NULL, 3396, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1980', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1980', NULL, NULL, 'Riders dressed in hunting clothes and boots hurl rocks at fleeing lions. The man wears a short tunic and the woman has a fluttering skirt. The border consists of curved acanthus leaves that enclose a chase of alternating lions and hares. This square was sewn onto a tunic rather than woven in. Hunting was a popular artistic theme in pre-Islamic traditions, including Byzantine art, and was then adopted into Islamic art.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '几何与团花 埃及与地中海  几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-99630', '边饰与织锦', 'Ornament from a Garment', NULL, '埃及与地中海', 'archive', NULL, '["边饰与织锦"]', '["Egypt, Byzantine period"]', '400s–600s CE', 'Linen, undyed; wool, dyed; tapestry weave with supplementary weft wrapping', 'assets/patterns/archive-CMA-99630.webp', 'assets/patterns/archive-CMA-99630-thumb.webp', '0567dd526b240c65fa796b0402e9e02ff87eef9ce5f9d6fa080c4f0938f50208', NULL, 3400, 3245, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1919.21', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1919.21', NULL, NULL, 'Six different designs of leaves and interlacing lines are organized harmoniously here within circles, triangles, and squares. Originally part of a garment, interlacing knot designs were thought to symbolically protect the wearer from harm.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 埃及与地中海  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-99661', '边饰与织锦', 'Ornamental Shoulder Band from a Tunic', NULL, '埃及与地中海', 'archive', NULL, '["边饰与织锦"]', '["Egypt, Byzantine period"]', '600–650', 'tapestry weave with supplementary weft wrapping; undyed linen and dyed wool', 'assets/patterns/archive-CMA-99661.webp', 'assets/patterns/archive-CMA-99661-thumb.webp', 'a5d38f7c4615a067b59c134a2357f9808b823bcdd3292393e46461956b918b21', NULL, 738, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1919.24', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1919.24', NULL, NULL, 'On this tunic decoration, human figures appear to dance amid leafy plants. The first and third figures are shepherds, each wearing spotted animal–skin garments and holding wooden staffs. The second and fourth figures are dancers; the upper one wears a short draped garment (peplos), and the lower one appears nude except for a scarf draped over her shoulders. The brown-purple wool was dyed with kermes, a bluish-red dye from dried insects, and indigo in an unsuccessful attempt to imitate purple.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '边饰与织锦 埃及与地中海  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-108411', '团形纹', 'Roundel from a Blanket or Cover', NULL, '埃及与地中海', 'archive', NULL, '["几何与团花"]', '["Egypt, Byzantine period"]', '300s–400s CE', 'tapestry weave with supplementary weft wrapping; undyed linen and dyed wool', 'assets/patterns/archive-CMA-108411.webp', 'assets/patterns/archive-CMA-108411-thumb.webp', '9df6d022ac127e0f64763e72212f11b764fdba7fd73f24c84a93b4fdaebf15c7', NULL, 3400, 3043, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1926.141', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1926.141', NULL, NULL, 'Since pharaohs ruled ancient Egypt, linen cloth was woven with woolen loops for increased warmth and used as blankets and covers. Monochrome or single-color decoration as seen here dates this piece to the AD 300s. Polychrome or multicolor designs came later. Formed with deep purple wool and natural linen, the design consists of an outer circle with a knotted square inside.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '团形纹 埃及与地中海  几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-108415', '织物', 'Fragment of a Tunic', NULL, '埃及与地中海', 'archive', NULL, '["边饰与织锦"]', '["Egypt, Byzantine period"]', '400s–600s CE', 'wool: tabby ground, inwoven tapestry ornament', 'assets/patterns/archive-CMA-108415.webp', 'assets/patterns/archive-CMA-108415-thumb.webp', '4edf0f0c2eb7a46ee6f3f99593bbeab5fcedcdee1ae4f4554b48fb64b8bc5bcb', NULL, 1512, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1926.143', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1926.143', NULL, NULL, 'Tunics with decoration on the front and back were worn by both men and women. These long bands, called clavi, feature pairs of stylized haloed figures gesturing, possibly in dance, and wearing short skirts with scarves across their chests. They alternate with pairs of foxes (?) and fish. The ancient repair in the lower center of this woolen winter tunic reveals that decorated cloth was expensive, and thus often mended and reused.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '织物 埃及与地中海  边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100735', '树木 · 鸟纹 · 织物', 'Fragment of a Band with Birds and Trees', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","边饰与织锦"]', '["Italy, Sicily, 1500s"]', '1500s', 'Bleached linen (est.): needle lace, burato (twined ground and darned in one direction)', 'assets/patterns/archive-CMA-100735.webp', 'assets/patterns/archive-CMA-100735-thumb.webp', 'e1b523e46802c0d35fcd9773f3e970ccd319945c79b9fafcd223bb0e16694fe8', NULL, 3400, 1012, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1121', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1121', NULL, NULL, 'This lace, made in Sicily, shows a close relationship to a pattern in a model book published in Lyon, France, a commercial center of printing and luxury textile trade with strong ties to Italy. The designs were based on a grid, making it easier for the lace maker to translate the printed image into needlework.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '树木 · 鸟纹 · 织物 欧洲与其他传统  花草藤蔓 鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100760', '树木 · 鸟纹 · 动物', 'Fragment of a Band with Confronted Birds, a Formal Tree, and Smaller Animals', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","边饰与织锦"]', '["Italy"]', '1500s', 'Bleached linen (est.): needle lace, burato (twined ground and darned in one direction)', 'assets/patterns/archive-CMA-100760.webp', 'assets/patterns/archive-CMA-100760-thumb.webp', 'deebb8c8bc00a8caff1ea386f54f43285cbac6e08674e1e5db4e32acfe1e18bb', NULL, 3400, 3023, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1142', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1142', NULL, NULL, 'Birds, perhaps eagles, confront each other on this corner fragment. Of particular interest is how they are surrounded by smaller animals and framed by a geometric structure. This could reference a family’s heraldry, or show the lace maker’s skill in rendering figural and geometric motifs.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '树木 · 鸟纹 · 动物 欧洲与其他传统  花草藤蔓 鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100761', '龙纹 · 织物', 'Fragment of a Band with Dragon, Castle, and Vegetation', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","吉祥与礼仪","边饰与织锦"]', '["Italy"]', '1500s', 'Bleached linen (est.): needle lace, burato (twined ground and darned in one direction)', 'assets/patterns/archive-CMA-100761.webp', 'assets/patterns/archive-CMA-100761-thumb.webp', '5a95334dc3314a5421ccdbfee518a8dab5b8ce16c40d4b77db0a080549905136', NULL, 3256, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1143', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1143', NULL, NULL, 'The detailed and elegant craftsmanship of this piece of lace clearly delineates the dragon, with its extended tongue, pointy scales along its neck and tail, and clawed feet. To its right is an architectural element, most likely a castle.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '龙纹 · 织物 欧洲与其他传统  鸟兽鱼虫 吉祥与礼仪 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100778', '藤蔓 · 狮纹 · 动物', 'Fragment of a Band with Vines Surrounding a Monkey, Lion, and an Unidentified Four-Legged Animal', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","边饰与织锦"]', '["Italy"]', '1500s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in two directions)', 'assets/patterns/archive-CMA-100778.webp', 'assets/patterns/archive-CMA-100778-thumb.webp', '7f9f5a699d2182ee3985e2488218e64f8891f30a280abee2680f8683979d5973', NULL, 976, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1159', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1159', NULL, NULL, 'Most surviving pieces of figural lace are horizontal, making the vertical orientation of this band unique. The monkey, lion, and perhaps lioness or other feline are not native to Italy and represent exoticism and the notion of increasing international exchange at the time.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '藤蔓 · 狮纹 · 动物 欧洲与其他传统  花草藤蔓 鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100780', '花卉 · 鸟纹 · 织物', 'Panel with Birds, Flowers, and Suns', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","边饰与织锦"]', '["Italy"]', '1500s–1600s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in two directions)', 'assets/patterns/archive-CMA-100780.webp', 'assets/patterns/archive-CMA-100780-thumb.webp', 'b4fff44ccf913bdc620ede5fffeef53f4683b78a1c9b0a7fca56c5bd654a22ba', NULL, 3400, 1056, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1160', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1160', NULL, NULL, 'The repeated sun and cross motifs, representing Christ and the Crucifixion, suggest this lace panel may have been used to ornament a Christian vestment, perhaps worn by a clergy member.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 鸟纹 · 织物 欧洲与其他传统  花草藤蔓 鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100885', '动物 · 边饰 · 织物', 'Fragment of a Border with Repeated Pattern of Fantastic Winged Animals', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","几何与团花","边饰与织锦"]', '["Italy"]', '1500s–1600s', 'Bleached linen: needle lace, burato (twined ground and darned in two directions) and fringe', 'assets/patterns/archive-CMA-100885.webp', 'assets/patterns/archive-CMA-100885-thumb.webp', 'eb6f4c69ec9fc5011f6ebf397daa0db203990078522874f0d301cd9295118394', NULL, 3400, 769, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1245', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1245', NULL, NULL, 'A four-legged animal pattern repeats in the top register, and winged birds appear in the central and bottom register. The birds, which are significantly larger in the central panel, may be peacocks.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '动物 · 边饰 · 织物 欧洲与其他传统  鸟兽鱼虫 几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100909', '藤蔓 · 花卉 · 几何纹', 'Fragment of a Border with Floral Vine and Geometric Patterns', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","几何与团花","边饰与织锦"]', '["Italy"]', '1500s', 'Bleached linen (est.): needle lace, burato (twined ground and darned in two directions) and reticella', 'assets/patterns/archive-CMA-100909.webp', 'assets/patterns/archive-CMA-100909-thumb.webp', '77b6b6a7df171a8afb5235aee61820e6b0f94abd9e6d93e250142987afe85b41', NULL, 3400, 1862, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1267', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1267', NULL, NULL, 'Textiles often incorporate multiple techniques within a single piece, providing visual interest, and also demonstrating the skill and versatility of the maker. This fragment incorporates both reticella, a type of geometric needle lace worked on a grid of plaited or laid thread, and a border of burato.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '藤蔓 · 花卉 · 几何纹 欧洲与其他传统  花草藤蔓 几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100914', '动物 · 人物', 'Band with Parade of Human Figures, Stags, and Other Fantastic Animals', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","人物故事","边饰与织锦"]', '["Italy, Sicily ?, 1500s-1600s"]', '1500s-1600s', 'Bleached linen (est.): needle lace, burato (twined ground and darned in one direction)', 'assets/patterns/archive-CMA-100914.webp', 'assets/patterns/archive-CMA-100914-thumb.webp', '7ac21162b64fe77472d68c2d8a9c32213dfef6ccea8ae0ed70bb72880d9a0ee4', NULL, 3400, 303, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1271', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1271', NULL, NULL, 'Animals viewed in profile, some with their legs raised, indicate movement, such as a parade or procession. However, the human figures are shown frontally. Linear elements protruding from their backs and hands held out and open suggest the figures may be angels modeling a gesture of prayer.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '动物 · 人物 欧洲与其他传统  鸟兽鱼虫 人物故事 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-102162', '动物 · 边饰 · 织物', 'Fragment of a Border with Repeated Pattern of Fantastic Winged Animals', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","几何与团花","边饰与织锦"]', '["Italy"]', 'c. 1550–1600', 'Bleached linen (est.): needle lace, burato (twined ground and darned in two directions)', 'assets/patterns/archive-CMA-102162.webp', 'assets/patterns/archive-CMA-102162-thumb.webp', 'e23bc1c4944dda5187ff340cc8a4da608c9c270d91c78c7299e93711a4b60b15', NULL, 3400, 2447, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.825', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.825', NULL, NULL, 'A four-legged animal pattern repeats in the top register, and winged birds appear in the central and bottom register. The birds, which are significantly larger in the central panel, may be peacocks. For related works see 1920.1245.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '动物 · 边饰 · 织物 欧洲与其他传统  鸟兽鱼虫 几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-102489', '孔雀 · 人物 · 边饰', 'Cloth with Border of Female Figures and Peacocks', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","人物故事","边饰与织锦"]', '["Russia"]', '1700s–1800s', 'Linen: needle lace (cutwork and drawnwork), straight (continuous) bobbin lace, (tape lace) edging; applied silk (est.) ribbon', 'assets/patterns/archive-CMA-102489.webp', 'assets/patterns/archive-CMA-102489-thumb.webp', '5b2594f562fe11d2cdb5a863483a8208482dc824ac336c6dda3e8c9cf07cafa4', NULL, 3263, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1921.1134', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1921.1134', NULL, NULL, 'This cloth may have functioned as a towel. On one end, there are two panels of lace work surrounded by pink silk ribbon. Within each panel are two women flanking a stylized peacock. A smaller bird flies near the head of the woman on the right side of each panel.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '孔雀 · 人物 · 边饰 欧洲与其他传统  鸟兽鱼虫 人物故事 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-102495', '动物 · 人物 · 边饰', 'Towel with Border of Figures of Men and Animals', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","人物故事","边饰与织锦"]', '["Russia"]', '1700s–1800s', 'Linen: needle lace (cutwork and drawnwork), straight (continuous) bobbin lace, tape lace edging', 'assets/patterns/archive-CMA-102495.webp', 'assets/patterns/archive-CMA-102495-thumb.webp', '89d27f2ab658e0b5dd2807a4302661e83167d60e6c434c2ab40b82f0deca48ea', NULL, 3400, 1201, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1921.1140', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1921.1140', NULL, NULL, 'On each end of this cloth is a lace border depicting a man walking with his mule and two birds flying above. The man and his mule are approached by a large feline, perhaps a panther, which is a common motif in Russian textiles. Metallic and colored silk threads are used to render the figures and create individualized details.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '动物 · 人物 · 边饰 欧洲与其他传统  鸟兽鱼虫 人物故事 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-114064', '藤蔓 · 花卉 · 鸟纹', 'Border with Double-Headed Birds and Vases with Vines and Flowers', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","边饰与织锦"]', '["Italy, Sardinia"]', '1800s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in one direction)', 'assets/patterns/archive-CMA-114064.webp', 'assets/patterns/archive-CMA-114064-thumb.webp', 'b67f2a8a25dfd3e587615398ce24cdf3d070d9fca249c7eb854fdcbba5827a38', NULL, 3400, 418, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1933.344', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1933.344', NULL, NULL, 'Double-headed birds alternating with flowering vases appear on this filet/lacis lace. The pattern repeats horizontally, with organic spirals which burst into the upper and lower registers.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '藤蔓 · 花卉 · 鸟纹 欧洲与其他传统  花草藤蔓 鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-114567', '花卉 · 鸟纹 · 织物', 'Panel with Panthers, Birds, and Floral Motifs', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","边饰与织锦"]', '["Russia, Nizhniy Novgorod, 1700s-1800s"]', '1700s–1800s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in one and two directions)', 'assets/patterns/archive-CMA-114567.webp', 'assets/patterns/archive-CMA-114567-thumb.webp', '4826930f50d34e9aca2fe85476640ee0e51843c06306fb4b46e6024f6dbbbcd2', NULL, 3400, 2115, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1934.193', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1934.193', NULL, NULL, 'In this panel, a pair of panthers, a common motif in Russian textiles, flank a stylized Tree of Life. Two different types of birds fly above the scene. One bird is small, while the other is larger and similar to a peacock. The diamond patterning and geometric motifs throughout this lace are characteristic of Russian “peasant laces.”', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 鸟纹 · 织物 欧洲与其他传统  花草藤蔓 鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-115447', '花卉 · 几何纹 · 织物', 'Fragment of a Band with Geometric Pattern and Floral Motif', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","几何与团花","边饰与织锦"]', '["Italy"]', '1800s', 'Cotton (est.): needle lace, burato (twined ground and darned in one direction)', 'assets/patterns/archive-CMA-115447.webp', 'assets/patterns/archive-CMA-115447-thumb.webp', '4887db9e7cb398efb3016f092f83406600f12de85c712eb73f970761c5de4c1b', NULL, 3400, 501, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1936.221', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1936.221', NULL, NULL, 'A scrolling vine with budding vegetation or a tendril is a recurring pattern in needle lace. The frequent use of the motif, adapted in lace from different centuries and regions, suggests that it was found in a pattern book.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 几何纹 · 织物 欧洲与其他传统  花草藤蔓 几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-116182', '花卉 · 龙纹 · 动物', 'Cloth with Unicorns, Dragons, Other Animals, and Floral Patterns', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","吉祥与礼仪"]', '["Italy"]', '1800s', 'Bleached linen: needle lace, filet/lacis (knotted ground and darned in two directions) and alternating cutwork, embroidered squares, and bobbin lace edging', 'assets/patterns/archive-CMA-116182.webp', 'assets/patterns/archive-CMA-116182-thumb.webp', 'a50adcd5bc419ae3cbdcb26dd5a455340cea4c53d795cb1e1bcaf51fb235f66c', NULL, 3400, 2841, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1936.95', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1936.95', NULL, NULL, 'Scattered throughout this textile are depictions of both real and imaginary animals: unicorns and dragons exist alongside lions, stags, and an assortment of birds. There are also identifiable plants, flowers, and fruits as well as simply decorative or fictional ones. The maker, whose initials CM appear between the unicorns, perhaps chose to mix fantastical motifs with natural ones to create a more captivating spectacle. This large textile was perhaps meant for use as a table cover.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 龙纹 · 动物 欧洲与其他传统  花草藤蔓 鸟兽鱼虫 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-118417', '动物 · 人物 · 边饰', 'Border with Mounted and Standing Figures, Chariots, and Animals', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","人物故事","边饰与织锦"]', '["Spain ?, 1800s"]', '1800s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in two directions)', 'assets/patterns/archive-CMA-118417.webp', 'assets/patterns/archive-CMA-118417-thumb.webp', '0d92172d14c3560290987a87725066f60fe90e2acd85c71812e0939d843a5e5e', NULL, 3400, 1181, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1939.453', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1939.453', NULL, NULL, 'Animals viewed in profile, some with their legs raised, indicate movement, such as a parade or procession. The human figures are also shown in profile, with the exception of the central figure riding a chariot, who is shown frontally. There is one figure riding a donkey, with another on horseback, holding a sword. On the far right, a man and woman appear engaged in conversation. Meanwhile, various animals fill the space defying all rules of perspective, with the bird in the center appearing larger than some of the humans.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '动物 · 人物 · 边饰 欧洲与其他传统  鸟兽鱼虫 人物故事 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-123447', '蔷薇 · 丝绒', 'Four-color Velvet with Medici Armorial in Rosettes', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","几何与团花","边饰与织锦"]', '["Italy, Florence"]', '1450–1500', 'silk, velvet: cut pile and voided', 'assets/patterns/archive-CMA-123447.webp', 'assets/patterns/archive-CMA-123447-thumb.webp', '264d768be3a875d882e35cfbafb12124186f11b1cee66919f833dbe0ecf94a55', NULL, 785, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1943.67', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1943.67', NULL, NULL, 'This polychrome velvet displays the heraldic design of the Medici family of Florence, where it was probably made. The device of crimson balls on a yellow ground appears in the centers of the colorful rosettes. Gilt-metal thread forms the heraldic ground in more lavish examples. The striped selvage helps identify the late 15th-century dating. The rosette pattern created with four colors of pile warp is silhouetted on the ivory satin weave foundation, known as voided velvet. Its color scheme and tile-like design have often been associated with influence from Islamic lands, most likely Turkey.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '蔷薇 · 丝绒 欧洲与其他传统  花草藤蔓 几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-133710', '树木 · 动物 · 织物', 'Panel with a Pattern of Trees and Unidentified Animals', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","边饰与织锦"]', '["Spain"]', '1800s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in two directions)', 'assets/patterns/archive-CMA-133710.webp', 'assets/patterns/archive-CMA-133710-thumb.webp', 'bf70f88b7a25d4f92b0fe2f99b99567884b43e307537c26ccddd2cd1956aca24', NULL, 2557, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1956.323', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1956.323', NULL, NULL, 'The darning, or area of woven pattern, on these two attached panels is much thicker than the ground. In the center, a tree is flanked by four-legged animals, perhaps horses, lions, or griffins.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '树木 · 动物 · 织物 欧洲与其他传统  花草藤蔓 鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-146182', '藤蔓 · 鸟纹 · 织物', 'Silk fragment with scrolling vines, grape leaves, grapes, and birds', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","边饰与织锦"]', '["Italy"]', '1325–50', 'Silk: lampas weave', 'assets/patterns/archive-CMA-146182.webp', 'assets/patterns/archive-CMA-146182-thumb.webp', '8a1b6365def010583ef5678fe2b81e06ee0fc150ea9b47a831b9f3ab9e77f88a', NULL, 3388, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1971.75', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1971.75', NULL, NULL, 'This silk fragment displays a revolutionary new fashion in Italian textile design, influenced by the exotic patterns in silks imported from China, Byzantium, and Islamic countries of the Middle East. Beginning in the 1320s, instead of the static arrangement of motifs stacked one above the other, Italian designers staggered the motifs, creating asymmetry and movement. Even this fragment suggests motion through the arrangement of motifs in a curved lattice layout. However, the actual motifs—the grape leaves and bunches of grapes—remain typically Italian.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '藤蔓 · 鸟纹 · 织物 欧洲与其他传统  花草藤蔓 鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-148984', '藤蔓 · 鸟纹 · 织物', 'Silk with Dogs and Birds amid Vines', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","边饰与织锦"]', '["Italy, second half of 14th century"]', '1350–1400', 'silk, gold thread; a combination of two weaves, 2/1 twill and plain weave (lampas)', 'assets/patterns/archive-CMA-148984.webp', 'assets/patterns/archive-CMA-148984-thumb.webp', '3cf81626172a65263c677ae946b9a3a623cb4116423bd6b7becf3d4203e689fa', NULL, 3400, 2042, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1977.14', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1977.14', NULL, NULL, 'Silks from China and the Islamic Near East introduced radically new designs with asymmetry and exotic animals around 1300, which Italian silk designers incorporated in an international style to compete with imports from the East. These large palmette leaves were adapted from Islamic silks whereas the recumbent deer, birds, and dogs (visible at the bottom) were popular Italian motifs. Textiles were lucrative commercial commodities during the Middle Ages. Intrepid Italian merchants traveled by land and sea to China, Mongolia, India, and the Islamic Near East, led by the maritime republics of Venice and Genoa. The renowned Venetian, Marco Polo, published his overland journey across Asia to China in 1265.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '藤蔓 · 鸟纹 · 织物 欧洲与其他传统  花草藤蔓 鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-109229', '狮纹 · 团形纹 · 织物', 'Lampas fragment with foliate medallions', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫","几何与团花"]', '["Spain, Granada, Nasrid period"]', '1300–1499', 'lampas: silk', 'assets/patterns/archive-CMA-109229.webp', 'assets/patterns/archive-CMA-109229-thumb.webp', 'cd562864ac1a9b2b1ac1e5a3c8f2a0ce831c83a629ec676f47d9de1ca43c7d61', NULL, 3088, 2940, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1927.379', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1927.379', NULL, NULL, NULL, NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '狮纹 · 团形纹 · 织物 欧洲与其他传统  花草藤蔓 鸟兽鱼虫 几何与团花');
