INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-147823', '团形纹 · 织物', 'Textile with Paired Ducks in Roundels (Copy of a Medieval Silk)', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","几何与团花","边饰与织锦"]', '["France, early 20th century"]', 'early 1900s', 'compound twill weave woven on Jacquard loom; silk', 'assets/patterns/archive-CMA-147823.webp', 'assets/patterns/archive-CMA-147823-thumb.webp', '25ff2f384b283df4bd037d19111ca35cc23e2543c0182bdaad6b5a86edf32156', NULL, 2213, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1974.189', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1974.189', NULL, NULL, NULL, NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '团形纹 · 织物 欧洲与其他传统  鸟兽鱼虫 几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-95493', '佛教造像 · 织物', 'Curtain panel (sitara)', NULL, '欧洲与其他传统', 'archive', NULL, '["人物故事","边饰与织锦"]', '["Africa, North Africa, Algeria, Algerian weaver and embroiderer"]', '1800s', 'Linen, silk, gold, silver, dye', 'assets/patterns/archive-CMA-95493.webp', 'assets/patterns/archive-CMA-95493-thumb.webp', '5b115f72c965b4b0079e84da10e3d35006caa186caa7ad83656777545415f615', NULL, 1744, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1916.1229', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1916.1229', NULL, NULL, 'During the 1700s, stunning large embroidered door curtains such as these hung across doorways onto interior courtyards of multistoried residences. Light entered through their loosely woven linen ground while the reversible embroidered decoration provided beauty and privacy. Such curtains have three embroidered widths, the third missing here, joined by colorful plain silk ribbons flanking a French floral ribbon in the center.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '佛教造像 · 织物 欧洲与其他传统  人物故事 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100248', '花卉 · 边饰 · 织物', 'Fragment of a Border with Floral Motif', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Spain"]', '1700s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in one and two directions)', 'assets/patterns/archive-CMA-100248.webp', 'assets/patterns/archive-CMA-100248-thumb.webp', 'cc03fee56b1f29580841f1a80bdde96fdb5bf1fd06466b61a343da716c5953bc', NULL, 3400, 2856, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1919.745', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1919.745', NULL, NULL, 'The scalloped bottom edge of this lace fragment indicates that it was originally meant as the border for a larger work of lace or other textile.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 边饰 · 织物 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100254', '花卉 · 织物', 'Fragment of a Band with Floral Motif', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Spain"]', '1700s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in one direction)', 'assets/patterns/archive-CMA-100254.webp', 'assets/patterns/archive-CMA-100254-thumb.webp', '4d68aff91e27cfd0e63350f51f768233c28eb4131ed397b61021fa4eec6a9f40', NULL, 3400, 2912, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1919.750', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1919.750', NULL, NULL, 'Though it is a small fragment, this piece of lace is simple and honest in its decorative quality. The focus is on the tulips, which stand out with thick darning against the unadorned diamond ground netting.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 织物 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100257', '花卉 · 织物', 'Fragment of a Band with Floral Motif', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Spain"]', '1700s or early 1800s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in one direction)', 'assets/patterns/archive-CMA-100257.webp', 'assets/patterns/archive-CMA-100257-thumb.webp', '3e4a9228a44a8ab9cf7c9a641b43f67742007301c4edddd941af5ee790ad59da', NULL, 3400, 2895, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1919.753', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1919.753', NULL, NULL, 'Though it is a small fragment, this piece of lace is simple and honest in its decorative quality. The focus is on the abstract floral motif, which stands out with its thick darning against the unadorned diamond ground netting.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 织物 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100288', '花卉 · 织物', 'Fragment of a Band with Floral Motif', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Spain"]', '1600s–1700s', 'Bleached linen (est.): needle lace (knotted ground and darned in two directions)', 'assets/patterns/archive-CMA-100288.webp', 'assets/patterns/archive-CMA-100288-thumb.webp', 'c17aa4bc9af59e1d5e681b4163426370836b2d6d24d51ade514940538fa9775f', NULL, 3400, 1497, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1919.782', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1919.782', NULL, NULL, 'Though this fragment of lace is completed in the filet/lacis technique, the floral motif imitates a form of needle lace particular to Spain known as Ruedas or Sol Lace, due to its radial patterns.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 织物 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100290', '几何纹 · 织物', 'Fragment of a Band with Geometric Motif', NULL, '欧洲与其他传统', 'archive', NULL, '["几何与团花","边饰与织锦"]', '["Spain"]', '1600s–1700s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in two directions)', 'assets/patterns/archive-CMA-100290.webp', 'assets/patterns/archive-CMA-100290-thumb.webp', 'a0d1708e1aa560b9311ea31d6cc48c587e28d0f7b56f25189d820a3e2039cd9e', NULL, 3167, 1480, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1919.784', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1919.784', NULL, NULL, 'The thick and graphic darning, or area of woven pattern, depicts triangular and circular geometric motifs. In addition to the knotting of the thread (filet/lacis technique), the lace maker used thicker thread to create the bold and heavy pattern.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '几何纹 · 织物 欧洲与其他传统  几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100742', '花卉 · 织物', 'Fragment (of a Band?) with Floral Pattern', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Italy"]', '1500s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in two directions)', 'assets/patterns/archive-CMA-100742.webp', 'assets/patterns/archive-CMA-100742-thumb.webp', '723ad6f2a0e5d4f85cc3c9559c81514d75733237bfa3d6794914e9bdbf74389b', NULL, 3400, 2367, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1128', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1128', NULL, NULL, 'Lace was often used in large quantities to produce opulent effects of light and contrasting texture. Bands of this width may have originally adorned a woman’s skirt or petticoat, heightening the design and overall impact with its rich floral pattern.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 织物 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100743', '藤蔓 · 花卉 · 边饰', 'Fragment of a Border with Vines and Floral Motifs', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Italy"]', '1600s', 'Bleached and blue dyed linen (est.): needle lace, filet/lacis (knotted ground and darned in one direction) and bobbin lace edging', 'assets/patterns/archive-CMA-100743.webp', 'assets/patterns/archive-CMA-100743-thumb.webp', '84348ba5b9b8ae4bd93fadffb649b1638d94fbb7881d116bd5dfd956043e03fc', NULL, 3400, 2618, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1129', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1129', NULL, NULL, 'The light blue ground of this fragment of lace, together with the varying thicknesses of threads used for the ground and the embroidered pattern, create a sense of depth in the textile. The white thread is bleached linen and the blue is linen that has been bleached and dyed.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '藤蔓 · 花卉 · 边饰 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100759', '鸟纹 · 边饰 · 织物', 'Fragment of a Border with Standing and Seated Birds Amidst Vegetation', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","边饰与织锦"]', '["Italy"]', '1500s', 'Bleached linen (est.): needle lace, burato (twined ground and darned in one direction)', 'assets/patterns/archive-CMA-100759.webp', 'assets/patterns/archive-CMA-100759-thumb.webp', '6fc15554f7ea9b7a074c68f04642dbc95eaf3c7b6e080916909e54bee77134ef', NULL, 3400, 2981, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1141', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1141', NULL, NULL, 'Three distinct bird species appear in this fragment distinguished through their body, neck, and feather shapes. In the period this lace was created, there was growing interest in the scientific study of birds, called ornithology. Ornithological books and prints depicted accurate records of birds, which deviated from previous fanciful portrayals.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '鸟纹 · 边饰 · 织物 欧洲与其他传统  鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100777', '人物 · 织物', 'Fragment of a Band with Male Figure Leading Mounted Female Figure with Falcon', NULL, '欧洲与其他传统', 'archive', NULL, '["人物故事","边饰与织锦"]', '["Italy"]', '1500s–1600s', 'Bleached linen (est.): needle lace; filet/lacis (knotted ground and darned in two directions)', 'assets/patterns/archive-CMA-100777.webp', 'assets/patterns/archive-CMA-100777-thumb.webp', '006f6d21711767455360a9e1b8971a50391dee8045de1e5a130673bac5dec3ee', NULL, 3400, 2265, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1158', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1158', NULL, NULL, 'This fragment may depict a hunting scene. A male figure leads a female figure on horseback. The male figure, possibly of non-western heritage, seems to carry a weapon in his right hand and the bird he has hunted in his left.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物 · 织物 欧洲与其他传统  人物故事 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100781', '藤蔓 · 织物', 'Fragment of a Band with Vine Scroll and Leaves', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Italy"]', '1500s–1600s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in two directions)', 'assets/patterns/archive-CMA-100781.webp', 'assets/patterns/archive-CMA-100781-thumb.webp', '26a394e5872bff4d351bca8e36347c15e4a00ba69efb9346c2a874bb06f98ad6', NULL, 3400, 893, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1161', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1161', NULL, NULL, 'A scrolling vine with budding vegetation or a tendril motif is a recurring pattern in needle lace. The frequent use of the motif, adapted in lace from different centuries and regions, suggests that it was found in a pattern book.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '藤蔓 · 织物 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-100915', '人物', 'Band with Figures of Women and Angels', NULL, '欧洲与其他传统', 'archive', NULL, '["人物故事","边饰与织锦"]', '["Italy"]', '1500s–1600s', 'Bleached linen: needle lace, filet/lacis (knotted ground and darned in two directions)', 'assets/patterns/archive-CMA-100915.webp', 'assets/patterns/archive-CMA-100915-thumb.webp', 'd8bedda3e1757d75e1d910d42c42d8eaeda703237e0d187e48254811649ddd7e', NULL, 3400, 1092, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1920.1272', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1920.1272', NULL, NULL, 'Likely a religious scene, female figures bear crosses on their chests facing angels playing a keyboard instrument. Later piecing and repairs have distorted the appearance of the central figure to that of a double-tailed mermaid. The top part of her dress has been replaced with an extra bust and set of arms. This is especially visible when comparing the bottom of her dress with the dresses of the far left and far right figures.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '人物 欧洲与其他传统  人物故事 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-102493', '树木 · 边饰', 'Border with Stags, Fountains, and Trees', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Italy, Sicily"]', '1500s', 'Bleached linen (est.): needle lace, burato (twined ground and darned in one direction) and applied fringe', 'assets/patterns/archive-CMA-102493.webp', 'assets/patterns/archive-CMA-102493-thumb.webp', '1f0751589424b80206fb8ea8627832303f6bf4e23ca9cade7a483245dde6b936', NULL, 3400, 1698, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1921.1138', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1921.1138', NULL, NULL, 'Prancing stags, represented with their heads turned backward, flank an ornate fountain. The fountain motif could allude to rejuvenation and immortality.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '树木 · 边饰 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-102496', '孔雀 · 边饰', 'Border with Peacock Motif', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","边饰与织锦"]', '["Russia"]', '1700s–1800s', 'Linen: needle lace (cutwork and drawnwork), straight (continuous) bobbin lace, tape lace edging; applied silk (est.) ribbon and embroidery', 'assets/patterns/archive-CMA-102496.webp', 'assets/patterns/archive-CMA-102496-thumb.webp', 'b47c5ced9b78647f63cd3096d014e56563c86391b26bc021a88d099eae8b3762', NULL, 3400, 1361, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1921.1141', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1921.1141', NULL, NULL, 'This valance, a decorative drapery made for attachment at the frame of the bed, was a typical object from the dowry of a bride in eighteenth and nineteenth-century Russia. The valance, which shows a magnificent peacock flanked by temples or shrines, would have been made for the wedding night of a newlywed couple.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '孔雀 · 边饰 欧洲与其他传统  鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-103790', '花卉 · 边饰', 'Cover with Border of Abstract Floral Motifs', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Italy ?, 1700s"]', '1700s', 'Rose silk (est.) center: plain weave
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-103791', '鸟纹 · 边饰', 'Border with Crowned and Double-Headed Birds', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","边饰与织锦"]', '["Russia"]', '1700s–1800s', 'Needle lace, filet/lacis (knotted ground and darned in one direction) and bobbin lace (tape lace) edging; bleached linen (est.)', 'assets/patterns/archive-CMA-103791.webp', 'assets/patterns/archive-CMA-103791-thumb.webp', '388295ea0c38747a037063b2cde0a55902b01d967683f49dacec58401bae1ad5', NULL, 3400, 828, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1921.85', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1921.85', NULL, NULL, 'This long border may have functioned as a valance, a decorative drapery made for attachment at the frame of the bed. Crowned double-headed eagles confront peacocks, while smaller birds fly above them.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '鸟纹 · 边饰 欧洲与其他传统  鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-105792', '藤蔓 · 花卉', 'Band with Floral Vine Pattern', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Spain, c. 1850-70"]', 'c. 1850–70', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in one direction)', 'assets/patterns/archive-CMA-105792.webp', 'assets/patterns/archive-CMA-105792-thumb.webp', '7a379c09b0fb0a2ba898f84eeabe573940bb87da40d6bb6a8603eb729d3b9707', NULL, 3400, 580, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1923.876', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1923.876', NULL, NULL, 'This piece of lace is simple and honest in its decorative quality. The focus is on the floral vine, which stands out with its thick darning against the unadorned diamond ground netting.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '藤蔓 · 花卉 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-105793', '几何纹 · 边饰', 'Border with Geometric Patterns', NULL, '欧洲与其他传统', 'archive', NULL, '["几何与团花","边饰与织锦"]', '["Spain, c. 1850-70"]', 'c. 1850–70', 'Bleached linen (est.) and cotton (est.): needle lace, filet/lacis (knotted ground and darned in one direction)', 'assets/patterns/archive-CMA-105793.webp', 'assets/patterns/archive-CMA-105793-thumb.webp', '0c6ddbd6d3ea6651d177a30399a96959b357c6a8a77242fb7be8a828922bbf5b', NULL, 3400, 642, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1923.877', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1923.877', NULL, NULL, 'This piece of lace is simple and honest in its decorative quality. The focus is on the thick and graphic darning, or area of woven pattern, depicts triangular and geometric motifs. In addition to the knotting of the thread (filet/lacis technique), the lace maker used thicker thread to create the bold and heavy pattern against the unadorned diamond ground netting.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '几何纹 · 边饰 欧洲与其他传统  几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-111312', '几何纹 · 丝绒', 'Two-color Velvet with Gold in a Double Curved Lattice Pattern', NULL, '欧洲与其他传统', 'archive', NULL, '["几何与团花","边饰与织锦"]', '["Italy, possibly Florence, 15th century"]', '1450–1500', 'silk, gold thread; polychrome velvet: cut pile, brocaded, and voided', 'assets/patterns/archive-CMA-111312.webp', 'assets/patterns/archive-CMA-111312-thumb.webp', '0b28a2a3c480118806a5cd2652e2fc942d0d56d486e8eb00ec6f1e9d08141848', NULL, 2020, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1929.82', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1929.82', NULL, NULL, 'Although plain velvets were woven in Italy by the end of the 13th century, polychrome-patterned velvets were not produced until the late 14th century. This velvet with two colors of pile incorporates a limited amount of costly gold thread while a fourth color, ivory, is formed by the satin weave of the foundation, called voided velvet. Palmette leaves composed of gold thread and crimson pile dominate the pattern on the green pile ground. The palmettes are arranged in an overlapping curved layout, popular in Italy and in Ottoman Turkey during the second half of the 15th century.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '几何纹 · 丝绒 欧洲与其他传统  几何与团花 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-114030', '鸟纹 · 边饰', 'Cloth with Border of Vegetal Motifs and Insertion with Bird Motifs', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","边饰与织锦"]', '["Cyprus ?, 1700s"]', '1700s', 'Plain weave wool with needle lace, burato insertion (twined ground and darned in two directions), filet/lacis border and edging (knotted ground and darned in one direction), drawn work, and embroidery; bleached linen (est.), wool (est.), and cotton (est.)', 'assets/patterns/archive-CMA-114030.webp', 'assets/patterns/archive-CMA-114030-thumb.webp', '6b2152c0d1c90d5b3e64f5bd85172c26bff9540f65d28e125143f8bf2565ee07', NULL, 3400, 1076, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1933.311', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1933.311', NULL, NULL, 'Textiles often incorporate multiple needlework techniques within a single piece. One of the techniques in this example of lace is called cutwork. In cutwork, portions of the textile ground, such as a linen or cotton cloth, are cut away and threads are removed to create holes. The edges of the hole are then reinforced with embroidery and a pattern of needle lace can be created within the perimeter. Rather than adding to the cloth to create a design, the craftsperson removes threads to fabricate a pattern.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '鸟纹 · 边饰 欧洲与其他传统  鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-114034', '鸟纹 · 动物 · 边饰', 'Cloth with Border of Crowned Double-Headed Eagles with Various Emblems, Birds, and Other Animals', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","边饰与织锦"]', '["Italy"]', '1800s', 'Bleached linen (est.): needle lace, burato (twined ground and darned in two directions), bobbin lace insert and edging, and crochet insert', 'assets/patterns/archive-CMA-114034.webp', 'assets/patterns/archive-CMA-114034-thumb.webp', 'e7373323e9932aac9aa429b26931cf2f4d6ca44e0a896a4329f2630299d0b935', NULL, 3400, 1678, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1933.315', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1933.315', NULL, NULL, 'A range of techniques were used to create textural variation in this lace cloth: buratto, bobbin, and crochet. Figural motifs appear within the inserted buratto bands. Different birds, with crosses visible on their chests, crowned double-headed eagles, and feline figures facing a vessel may allude to the heraldic symbols of a particular family.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '鸟纹 · 动物 · 边饰 欧洲与其他传统  鸟兽鱼虫 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-114036', '花卉 · 边饰', 'Border with Floral Motifs', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Italy, Sardinia"]', '1800s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in one direction)', 'assets/patterns/archive-CMA-114036.webp', 'assets/patterns/archive-CMA-114036-thumb.webp', '42beda1cb50265e52ceb4aab5425378ca87cda85bcc35b45e9959e9d6850e1a5', NULL, 3400, 441, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1933.317', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1933.317', NULL, NULL, 'A tendril motif is a recurring pattern in needle lace. The frequent use of the motif, adapted in lace from different centuries and regions, suggests that it was found in a pattern book. Here, the pattern is unusually ornate with additional swirling and flowering motifs.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 边饰 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-114171', '花卉 · 织物', 'Floral Panel, Probably from a Curtain', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["England, James I Period, early 17th century"]', 'early 1600s', 'Silk, linen; plain weave, embroidery: couch and stem stitches', 'assets/patterns/archive-CMA-114171.webp', 'assets/patterns/archive-CMA-114171-thumb.webp', 'a8d93349a21bf388190c23fd038138af3c94bec05c4abcb8928a96d199c12ac1', NULL, 3400, 2965, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1933.421', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1933.421', NULL, NULL, 'Natural forms and brilliant colors of silk thread radiate in this embroidery. The refined floral sprays are offset in successive rows and repeated every sixth row. Flies, moths, and other insects are scattered among them, and a seated squirrel eats a hazelnut. The profusion of flowers and plants, such as thistles, hazelnuts, and foxgloves, were probably copied from pattern books that were increasingly available to embroiderers. Only a master embroiderer could have created such splendor evidenced here.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 织物 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-115448', '花草藤蔓', 'Band with Leaf Motifs', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Italy, Sardinia"]', '1600s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in one and two directions)', 'assets/patterns/archive-CMA-115448.webp', 'assets/patterns/archive-CMA-115448-thumb.webp', 'fcc23891ad328f70a1d165f588131244dde4a698ccc77e00cdc1aabdfcb4ece7', NULL, 3400, 1113, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1936.222', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1936.222', NULL, NULL, 'A scrolling vine with budding vegetation or a tendril motif is a recurring pattern in needle lace. The frequent use of the motif, adapted in lace from different centuries and regions, suggests that it was found in a pattern book. The maker of this piece used thread of different thicknesses to give texture and variety to the design.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花草藤蔓 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-115449', '藤蔓 · 织物', 'Fragment of a Band with Vines and Leaves', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Italy"]', '1600s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in one and two directions)', 'assets/patterns/archive-CMA-115449.webp', 'assets/patterns/archive-CMA-115449-thumb.webp', 'd4e1865a810ad6be8cf89fe79ecfb3f39b6ebc45e4ed11a8dd70e05f4c31fe09', NULL, 3400, 775, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1936.223', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1936.223', NULL, NULL, 'A scrolling vine with budding vegetation or a tendril is a recurring pattern in needle lace. The frequent use of the motif, adapted in lace from different centuries and regions, suggests that it was found in a pattern book.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '藤蔓 · 织物 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-116181', '花卉 · 人物', 'Cloth with One Figure of a Woman Carrying a Cross Surrounded by Floral and Vegetal Patterns', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","人物故事"]', '["Italy"]', '1700s', 'Bleached linen (est.): needle lace, filet/lacis (knotted ground and darned in two directions), alternating reticella squares (open cutwork) and bobbin lace edging', 'assets/patterns/archive-CMA-116181.webp', 'assets/patterns/archive-CMA-116181-thumb.webp', 'e8ce0cb748f47881e392f52fd49616c1d9103fd7456de89c2783671e3eb1f79e', NULL, 3400, 2366, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1936.94', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1936.94', NULL, NULL, 'The only figure represented on this large lace cloth is located in the center. The figure is a woman, shown in profile, carrying a cross, standing on top of a creature or within a vessel shaped like a creature.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '花卉 · 人物 欧洲与其他传统  花草藤蔓 人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-118366', '团形纹', 'Lampas with foliate roundels', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","几何与团花"]', '["Spain, Granada, Nasrid period"]', '1300s', 'lampas: silk and gold thread', 'assets/patterns/archive-CMA-118366.webp', 'assets/patterns/archive-CMA-118366-thumb.webp', '3fc86ffbd2db522cb52e68b2b1b3dbcf0db891d2276b789019b0911422fa2f76', NULL, 2457, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1939.42', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1939.42', NULL, NULL, 'This textile shows the development of the Hispano-Moresque style in the 1300s. The bright green, blue, white, and gold design against a rich red ground produces a jewel-like quality that was not seen again after the end of the century.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '团形纹 欧洲与其他传统  花草藤蔓 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-119763', '石榴 · 丝绒 · 织物', 'Silk Velvet with Gold in Pomegranate Pattern', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Italy, possibly Florence, 15th century"]', '1450–1500', 'silk, gold thread; velvet: cut pile in two heights, uncut pile loops, gold-thread loops', 'assets/patterns/archive-CMA-119763.webp', 'assets/patterns/archive-CMA-119763-thumb.webp', 'ad993ca76e30b2a7d5ace8139a9b10b9cb0eb72bd2e9027f2d874b5e6ee5de21', NULL, 2245, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1940.596', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1940.596', NULL, NULL, 'Luxurious silk velvets with expensive gold thread were symbols of wealth and power. The finest velvets during the 1400s have two, or even three, heights of lush projecting pile. This fashionably large pomegranate pattern features exorbitant gold-thread loops enriching the lower level and a plain higher level. The curved upper and lower contours suggest this was the back of a sleeveless ecclesiastical vestment known as a chasuble. The striped green and ivory selvage was the equivalent of a label, required by law. It identified the fiber content, its quality, and quantity, which determined the price. Selling prices reflected the costs of the raw materials—gold thread, silk, and dyestuffs. Compensation for artisans was generally minimal.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '石榴 · 丝绒 · 织物 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-123709', '狮纹 · 织物', 'Fragment with crowned lions, palmettes, and escutcheons', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","鸟兽鱼虫"]', '["Spain, Granada"]', '1400s-1500s', 'Silk: lampas weave', 'assets/patterns/archive-CMA-123709.webp', 'assets/patterns/archive-CMA-123709-thumb.webp', '77aa6f02f76a72f02247a68d0f55e8c64f7e3140dc7cb298f66d2cfc3f20d87a', NULL, 1857, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1944.240', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1944.240', NULL, NULL, 'Pairs of yellow lions are framed beneath arches formed by elaborate green leaves in a sumptuous repeated pattern. The city of Granada in southern Spain, where the Alhambra palace stood, continued to be a major center for silk production and commerce through the 1500s. Because the upside-down shields contain no Arabic inscriptions, it was probably made after the fall of the last Muslim sultan to the Christian King Ferdinand and Queen Isabella in 1492.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '狮纹 · 织物 欧洲与其他传统  花草藤蔓 鸟兽鱼虫');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-127182', '树木', 'Orphrey Band: The Tree of Jesse', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["England"]', 'c. 1350', 'Silk, gold and silver thread, linen; embroidery: split and couching stitches', 'assets/patterns/archive-CMA-127182.webp', 'assets/patterns/archive-CMA-127182-thumb.webp', 'fc5f2cc33522e81d144e2c9ea71dfe200321b1740de6423e7429c163e20c35a0', NULL, 664, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1949.503', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1949.503', NULL, NULL, 'From the 1100s to the 1300s in London, both men and women worked as professional embroiderers. Here, the Tree of Jesse, a favorite medieval theme illustrating the ancestry of Christ, appears as a grapevine with three ancestors—Achim, Ezechias, and Eliud—seated on tendrils. Painters often provided embroiderers with designs, revealing a close relationship between the professions.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '树木 欧洲与其他传统  花草藤蔓 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-129261', '团形纹 · 织物', 'Fragment with eagles in roundels from the Reliquary of Saint Librada in Siguenza Cathedral', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","几何与团花"]', '["Spain, Almeria"]', '1100–50', 'Silk and gold thread: lampas weave', 'assets/patterns/archive-CMA-129261.webp', 'assets/patterns/archive-CMA-129261-thumb.webp', 'a8dad3c16147c2acb0f34edddb1f56571acf49ec601057b4bb2af3da9c1d2687', NULL, 3400, 3104, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1952.15', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1952.15', NULL, NULL, 'This fragment belongs to a group of Spanish silks characterized by their design of aligned, slightly oval roundels that frame animals or birds. A single heraldic eagle fills the center of the roundel, and under his talons are Arabic inscriptions that read Blessing. The beaded border is animated with composite beasts and harpies. It was made during a period when the Islamic cities of Spain were the leading producers of luxury silks in Europe.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '团形纹 · 织物 欧洲与其他传统  鸟兽鱼虫 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-129264', '团形纹', 'Lampas with griffins in roundels, from the Reliquary of Saint Librada in Siguenza Cathedral', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","几何与团花"]', '["Spain, Almeria"]', '1100–50', 'Silk and gold thread: lampas and plain-weave variant', 'assets/patterns/archive-CMA-129264.webp', 'assets/patterns/archive-CMA-129264-thumb.webp', '1d511424708922e16ffe1ca0d1c659797082f593558683a391eb45f530499528', NULL, 3400, 2844, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1952.152', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1952.152', NULL, NULL, 'Mirrored griffins with gold heads dominate these roundels, as they turn their heads unnaturally to stare at each other across their wing tips. The pairs of dragons in the framing border, however, have lost their artistic impact since the green silk thread has disintegrated into brown specks. Luxury silks woven in Islamic Spain were worn by Christian kings throughout Europe. Their patterns also influenced designs in Jewish synagogues and were the standard aesthetic of the elaborately decorated walls in the Muslim Alhambra palace in Granada. This silk is from the reliquary of Saint Librada in Siguenza Cathedral, northeast of Madrid.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '团形纹 欧洲与其他传统  鸟兽鱼虫 几何与团花');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-130166', '鱼纹 · 人物', 'Spring: Fishing Scene', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","人物故事"]', '["France"]', 'designed c. 1535, woven mid- to late 1600s', 'Wool, silk, and gold filé: tapestry weave', 'assets/patterns/archive-CMA-130166.webp', 'assets/patterns/archive-CMA-130166-thumb.webp', '514fd1a2c9cac2793fb62cf2b63a1ca630015a34f431321edad9d4edf914a238', NULL, 3400, 3250, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1952.544.1', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1952.544.1', NULL, NULL, 'In this springtime scene, two fishermen wade in a river, dragging a net suspended between two poles. A noble couple on a bridge gestures toward other fishermen, who occupy the other side of this scene in other extant examples of this tapestry with a larger picture plane. In the background, townspeople walk on bridges that lead to the gateway of a town with brick walls and portals. In the far distance, farmers till the soil to sow new seeds, another typical activity associated with spring. The trees on the hills are just beginning to sprout new buds.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '鱼纹 · 人物 欧洲与其他传统  鸟兽鱼虫 人物故事');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-130364', '刺绣', 'Embroidered Tondo from an Altar Frontal: The Coronation of the Virgin', NULL, '欧洲与其他传统', 'archive', NULL, '["人物故事","边饰与织锦"]', '["Italy, Florence"]', '1459', 'Embroidery with gold, silver, and silk thread; split, satin, and couching stitches, or nué (shaded gold)', 'assets/patterns/archive-CMA-130364.webp', 'assets/patterns/archive-CMA-130364-thumb.webp', '0a7826c53db2e632d3f208bed10789b5861ef42ac36be584890516243dd79e24', NULL, 3351, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1953.129', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1953.129', NULL, NULL, 'This masterpiece of Florentine embroidery takes the circular form called a tondo and was likely once attached to an altar frontal. The scene depicts the coronation of the Virgin, the final and culminating event in the narrative cycle of her life. Honoring her as queen of heaven, Christ places the crown on his mother’s head. They are surrounded by eight angels as well as Saints Verdiana and John Gualberto, both much esteemed in Florence, creating a joyous scene. During the Renaissance, Florence emerged as an important center for a specific type of embroidery known as or nué, or shaded gold. This stunning technique used metal and silk threads, as seen here, to create pictures that rivaled paintings. It was frequently used for vestments and altar frontals.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '刺绣 欧洲与其他传统  人物故事 边饰与织锦');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-130609', '龙纹 · 孔雀', 'Peacock and Dragon', NULL, '欧洲与其他传统', 'archive', NULL, '["鸟兽鱼虫","吉祥与礼仪"]', '["England, Surrey, Merton Abbey"]', '1878', 'weft-faced compound twill; wool', 'assets/patterns/archive-CMA-130609.webp', 'assets/patterns/archive-CMA-130609-thumb.webp', 'b3479a71df80d1b36a66767c1309788804c98b8b5a0e363227afbbc54f6cc168', NULL, 2752, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1953.330', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1953.330', NULL, NULL, 'Morris sought to produce textiles that could function as he imagined medieval wall hangings had, bringing warmth to stone-cold rooms. Boldly designed with soothing colors in thick wool, Peacock and Dragon is the closest Morris came to achieving this ideal. In the same year he designed this textile, Morris visited the shop of the London dealer Vincent Robinson, where he saw a room re-created from Damascus, “all vermillion and gold and ultramarine, very beautiful, and is just like going into the Arabian nights.” It partly inspired the exotic motifs seen here. This design was one of the most popular among Morris’s customers; it was available in five colorways.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '龙纹 · 孔雀 欧洲与其他传统  鸟兽鱼虫 吉祥与礼仪');
INSERT INTO patterns (id, title, original_title, subtitle, region, collection, style_family, tags, culture, period, technique, image, thumbnail, image_sha256, thumbnail_sha256, width, height, source_platform, source_name, source_url, source_api_url, author, license, license_url, accession, museum_object_id, rights_verified_at, description, curation_note, label_note, featured, sort_weight, search_terms) VALUES ('CMA-147465', '石榴 · 丝绒', 'Velvet with Pomegranate Pattern', NULL, '欧洲与其他传统', 'archive', NULL, '["花草藤蔓","边饰与织锦"]', '["Italy, Florence"]', '1450–1500', 'silk, gold thread; velvet: three heights of cut pile, gold thread loops', 'assets/patterns/archive-CMA-147465.webp', 'assets/patterns/archive-CMA-147465-thumb.webp', '57e8aa0eb8871a72c9c11e346016ee94a2d3752d60d9eb674a061b94038d6d5e', NULL, 962, 3400, '克利夫兰艺术博物馆', '克利夫兰艺术博物馆', 'https://clevelandart.org/art/1973.20', NULL, '馆方未注明', 'CC0', 'https://www.clevelandart.org/open-access', '1973.20', NULL, NULL, 'This extravagant Italian velvet with three heights of lush crimson pile is lavishly embellished with gold-thread loops. Large pomegranate patterns such as this were fashionable in Europe for more than a century, about 1420 to 1550, and were often featured in paintings and in large wall tapestries. Variations occurred in pattern details, pile height, and gold thread. Since pomegranates symbolized eternity, fertility, and resurrection, these velvets were often used in Roman Catholic churches. This pomegranate pattern inspired the cope, or cloak, worn by the Archbishop of Canterbury when he officiated the royal wedding of Prince William and Kate Middleton in 2011.', NULL, '中文检索名与题材标签由本素材库整理；原作名称及文化归属以馆方原文为准。', FALSE, 0, '石榴 · 丝绒 欧洲与其他传统  花草藤蔓 边饰与织锦');
